MailLocalData.tab = {
[100000] = {id = 100000, name = "吉雅", head = "90000", type = 6, title = "關於生日……", txt = "領航，作戰辛苦了。現在應該正在返航途中？希望沒有打擾到您。\n到現在為止，今天已經收到了不下百封賀信，是各部工作人員們發來的，還有駕駛員們。以免回程途中有突發事件發生，這些郵件將待您返回支部後再進行同步。此外還有不少送給領航的禮物，經掃描，裏面沒有危險物品。以上。\n……哥哥，生日快樂。\n吉雅知道，身為情報官，不應該佔用公共頻道說私事……可明明是生日，哥哥卻一早就被調派出去執行任務……對不起，吉雅不該抱怨這些的。\n吉雅只是想說，吉雅會等哥哥回來，然後再給哥哥慶生的。不管多晚，哪怕過了零點，也會乖乖等著……", goods = "1_100000_300,1_110122_1", effective = -1, "0", "0", "0", "0", "0"},
[10000101] = {id = 10000101, name = "吉雅", head = "90000", type = 6, title = "恭喜生日", txt = "哥哥，生日快樂！\n從一個月前我就想為你慶祝了——如果這麼說是不是有些誇張呢？但考慮到生日一年一度，稍微提前準備也還算好啦，聽說有些大型慶祝會都是提前一年就開始準備工作的，每當舉行完畢，就會立刻著手籌備下一年的慶祝會。如果工作可以不用這麼忙碌，我也好想提前一年為哥哥舉辦盛大的生日會，邀請哥哥的駕駛員朋友們，大家一起度過今天。\n呵呵，好像越說越誇張了呢，但這是我的真心，並不是開玩笑哦~世界的情況正逐漸好轉，這離不開哥哥的努力，而等到原罪被徹底消滅，也許剛才說的都會成真。\n嗯，我相信，這樣的未來已經不遠。", goods = "1_100000_300,1_110122_1", effective = -1, "0", "0", "0", "0", "0"},
[110000] = {id = 110000, name = "露露啦", head = "10000", type = 5, title = "一起玩遊戲吧！", txt = "終於……等到今天了！托金庫啦幫忙，順利搶到了《中轉戰2》的限量版首發！\n之前不是借領航玩過《中轉戰》嗎？那可真的是個佳作，在我玩過的競技遊戲裏，排名少說也是前三！《中轉戰2》裏還增加了不少新機制、新角色……總而言之！領航，記得把今晚空出來哦。您之前答應了的，等新作發售後會陪我玩個通宵。\n不可以拒絕。這可是壽星的請求……等等，您應該沒有忘記今天不僅是《中轉站2》的首發日，也是我的生日吧？！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000001] = {id = 11000001, name = "露露啦", head = "10000", type = 5, title = "緊急求助！", txt = "生日什麼的先不管，最近又推出了一款機甲遊戲，而且還是時隔十年的續作哦！\n但是這一作的PVE關卡難破天際，不全收集通關就直接PVP又有些吃虧，畢竟不少強力裝備無法使用，所以我正在想辦法攻克難關……雖然這麼說，但實際上，我已經卡在第一章關底BOSS戰整整三天了！想要繼續推進流程，果然還是得來向領航求助吧？\n說起來，領航會不會覺得我明明很擅長PVP，對程序驅動的AI敵人卻束手無策很奇怪呢？這也沒辦法，人人都有不同的長處嘛~等領航幫我通關後，我就帶你PVP一百連勝作為報答好了，這款遊戲的2V2模式很有意思哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000002] = {id = 11000002, name = "露露啦", head = "10000", type = 5, title = "首發請勿拖延！", txt = "欸欸欸，太激動了吧！\n我最近一直在關注的遊戲，忽然公佈的首發日竟然是我的生日！\n要是能搶到限定版的話……不誇張地說，在不影響戰鬥的情況下我要沒日沒夜地玩！\n領航要和我一起去排隊嗎？我會帶零食的，還準備了能量飲料和暖寶寶，今晚是不會讓你困的！\n……有你在的話，好像就算冷風吹一晚上我也不怕啦～等遊戲到手了我們一起通宵開玩哦！\n嘿嘿，這種小事以後也要一直一起做啊～", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000003] = {id = 11000003, name = "露露啦", head = "10000", type = 5, title = "拯救世界的方法為什麼是通馬桶？", txt = "為了通關《ATG6》，我已經連續通宵一周了。每天的睡眠時間僅有2小時，除了出任務之外，我把所有時間都獻給了這款遊戲。\n終於在今天，我完成了主線任務。然而，我絲毫沒有感到快樂，尤其是看到任務列表裏還有無窮無盡的支線任務沒有完成。\n到底是為什麼要讓肩負拯救世界重任的主角去幫人送信、修水管和通馬桶啊！難道這個世界沒有其他人可以做這些事了嗎？\n直到通關後，我才想起今天是我的生日。好險好險，差點因為這個遊戲而錯過慶祝的環節。\n不過，我慶祝生日的方式，也就是找領航一起玩遊戲罷了。 ", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110001] = {id = 110001, name = "朱利乌斯", head = "10001", type = 5, title = "還請多多指教", txt = "您看到這封郵件時，我應當已經離開支部了。\n啊，並不是什麼人員調動，也不是出任務……今天我請了半天的假，想回家陪陪母親大人。\n請假的事，我沒有告訴查麗莎她們。感覺也沒有必要，畢竟只是半天假期，待不了很久。但如果她們察覺到此事，甚至找到了領航您這裏，還請替我說聲抱歉。我會帶伴手禮回來的，當然，領航那份也會準備——請先不要急著拒絕。沒有規定說壽星在生日當天只能收禮，不許送禮吧？況且這可是我的一份心意。\n接下來的一年，也請您多多指教，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000101] = {id = 11000101, name = "朱利乌斯", head = "10001", type = 5, title = "請您攙扶我。", txt = "母親大人叮囑我今年的生日不必回家。\n她似乎希望我在多瑙中舉辦生日宴會，廣交各大的方舟朋友，踐行騎士的好客精神，共同維繫世界的安全。\n說實話……我對此感到為難，我實在是不擅長張羅這些事情，但如您所見，勉勉強強地籌備成功，我已經向各個方舟熟悉的駕駛員發出了邀請函，宴會將在晚上舉行。\n但我感覺我差不多也到極限了……如果可以的話，希望領航能在我的身邊攙扶我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000102] = {id = 11000102, name = "朱利乌斯", head = "10001", type = 5, title = "請求您的協助", txt = "今年生日，母親大人給我送了一份特別的禮物。是一匹漂亮的牝馬，雖還只是小馬駒，擡起頭時只到我一半高，卻目光熠熠步步生風，可見其血統的優異。\n母親大人説這是一項家族傳統，每个家族成員都需要培養一匹自己的戰馬，當然幷不是為了上戰場，這只是一種傳承。據説以前的騎士便是如此，從小與戰馬一起生活，培養足够的默契，才能做到配合無間，所向披靡。\n然而養馬幷不是件易事，我從沒養過馬，也不懂任何養馬的知識。坦白講，我現在有些不知所措，因此想來領航您這裏尋求一些幫助。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110002] = {id = 110002, name = "漢克", head = "10002", type = 5, title = "很快就到你房間門口", txt = "喲，領航！知不知道今天是什麼日子？今天可是由我請客盡情瀟灑的日子，你的話肯定不會錯過吧？\n蛋糕那種軟綿綿又甜得發膩的東西就不准備了，我只想泡在酒池肉林裏，既不在乎錢包也不考慮健康，胡吃海喝一頓就好！以前當自由傭兵攢的錢，可就是為這種時候準備的~\n我知道你也不是喜歡長篇大論的人，郵件裏就不多廢話了，我這就來找你出去搓一頓，很快就到你房間門口！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000201] = {id = 11000201, name = "漢克", head = "10002", type = 5, title = "糟糕了糟糕了！", txt = "糟糕了，這下真的糟糕了，應該不會有比這更加糟糕的事情了！\n今天不是我的生日嗎？於是我就想著要和你暢飲到明日天明……明明是這樣想的！\n但是剛剛我打開冰箱的時候，裡面卻空空如也，簡直比發薪水前的錢包還要空——雖然我們用的是電子貨幣啦。\n冰箱裡連一罐酒都沒有，氣得我差點把它劈成倆半……總之，趁著今天還沒結束，讓我們去把酒吧的貨掃光吧。\n決不能讓這一年一度的日子少了酒的香味！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000202] = {id = 11000202, name = "漢克", head = "10002", type = 5, title = "莫名其妙的問候", txt = "唉——領航，你知道我是誰吧？我是獨眼的漢克！曾經是艾吉斯染血的利刃，也是瀟灑的自由傭兵，還是精英部隊獵騎的駕駛員。\n這樣的我，居然會被不知道多少年沒有聯繫的父母問了句“你結婚了嗎？”\n開什麼玩笑！這是哪門子老掉牙的展開！\n再說了，駕駛員也不能結婚吧！\n真是莫名讓人火大，對了，領航，今天也陪我去喝酒吧——剛好也聊聊催婚這種煩人的話題。\n……你應該沒有背叛我們倆的單身聯盟吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000203] = {id = 11000203, name = "漢克", head = "10002", type = 5, title = "戰個痛快，喝個盡興", txt = "最近日子過得太舒坦，連骨頭都快生鏽了，這樣下去可不行。今天是我生日，我打算找點“原罪”練練手——刀鈍了就得磨。\n雖然日子好起來了，但是當僱傭兵時的那股狠勁兒可不能忘。\n照老規矩，結束戰鬥後必須要再喝個痛快。爲了更快地忘掉傷痛，也爲了更牢地記住教訓。\n用酒精刺激記憶細胞，這就是我變強的祕笈。廢話不多說，我待會兒就去你房裏找你。今天我們不旦要戰個痛快，也要喝個盡興。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110003] = {id = 110003, name = "森村鬼之介", head = "10003", type = 5, title = "我不喜歡生日", txt = "生日……我對這種用來哄小孩的事情不感興趣。\n你應該是了解我的，我不想把時間浪費這種無意義的事情上。\n……本來是這麼想的。\n但不知火說和親近的人過生日可以鍛煉精神——無論怎麼聽都像是在哄人——總之，我來找你，你老實待在房間裡，我馬上就到。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000301] = {id = 11000301, name = "森村鬼之介", head = "10003", type = 5, title = "生日當天的噩夢", txt = "領航，隊長她們應該沒有打擾你吧？還是說，已經把我的事情說給你聽了？\n總之，今天一大早的時候，她們就在敲我的門，說要給我慶祝生日……\n但是我沒有給她們開門，沒有和她們見面，甚至連交流都沒有。\n她們肯定想不到，理由只是因為我做了個噩夢……一個不好的噩夢……\n就算是關係再好的朋友，不能說的話還是不能說的。\n那個噩夢裡也有你，所以……所以……總之就是，我希望你能跟我說一下，夢和現實的關係之類的……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000302] = {id = 11000302, name = "森村鬼之介", head = "10003", type = 5, title = "難以選擇的願望", txt = "生日可眞是一件麻煩事。一般來説，慶祝生日就必須要準備蛋糕和蠟燭。如果要邀請別人的話，還得額外準備其他小喫，裝飾品等等。\n然而對我來説最麻煩的還不是這些，“生日願望”才是頭疼的。\n該許下什麽“願望”呢？\n雖然説“願望”這種東西，就算誠心誠意地祈求也大槪率不會實現，但如果因爲這就隨隨便便説些奇怪的“願望”，掌管“願望”的神明又説不準就會將它變成現實……\n唉，我自己也不知道該許下什麽願望比較好。領航，你來幫我選擇一个願望吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110004] = {id = 110004, name = "D型b2", head = "10004", type = 5, title = "那個人的生日", txt = "啟動確認——認證開始——......啟動完畢。\n領航，您好。\n我的資料庫裏有記載，人類誕生的那一天對於其本人而言具有非常意義的一天。\n作為一臺量產型的機器，我想所謂的生產日期就可以當作是我的生日。甚至能精確到某一天的幾分幾秒。甚至能根據地球的自傳自動矯正誤差。\n但我更想把這一天當作我的生日，就算那名少女靈魂的痕跡早已衰退，餘下的只是被稱作D型b2的空殼的我。\n今天是她的生日。我想邀請你一起慶祝了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000401] = {id = 11000401, name = "D型b2", head = "10004", type = 5, title = "待補全的記錄", txt = "已確認，現在的時間為，淩晨零點。\n為避免打擾您的休息，這則消息將被設置在八小時後發送。\n早上好，領航。\n自去年的10月13日開始，已經過去了完整的365天。因此，我推測這一天為自己的第二個生日。\n我聽一些時常交流的駕駛員說，人類會在生日的這天，收到來自其親友的禮物。\n我雖然沒有物質上的欲求，但還是有想向您講述的願望。\n這具軀體無法輕易外出。因此，雖能從數據庫中查閱大致描述，我仍無法得知這個世界的具體樣貌。\n為此，我希望能通過您對自己見聞的講述，盡量填補這份空缺。\n這只是一份申請。我會一直在此處靜候您的到來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110005] = {id = 110005, name = "華戀", head = "10005", type = 5, title = "每天飽含愛意地踢出一百腳", txt = "最近的時間小生沉迷在書本的武俠江湖之間不可自拔。直到華夢姐姐告訴我今天是小生的生日，我才發覺已經荒廢了不少的練武時間。\n不過正所謂亡羊補牢為時未晚，小生決定從今天開始要每天迎著朝陽踢出飽含愛意的一百次踢腿。飽含對自然的愛意，飽含對武術的愛意，也飽含對領航你的愛意。沒錯，小生希望領航能監督我完成這每天的一百腳，並在你準備好的時候接受我的全力一擊。\n這就是小生的生日願望。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000501] = {id = 11000501, name = "華戀", head = "10005", type = 5, title = "生日的時候反而要提高警惕", txt = "不知不覺又過去了一年，去年過生日的景象還殘留在小生的記憶，眼下又迎來了新的生日。\n生日是喜慶的日子，但喜慶之中卻暗藏殺機。據小生所知，生日宴會上通常會發生一些了不得的事情。\n自己徒弟的仇人尋上門復仇；騎著神雕的俠客送上三件大禮；或者是借祝壽之名來上門奪取武林盟主之位——這都是經典的橋段了吧，為了不讓小生的生日也成為經典橋段的犧牲品，小生決定在今天將練武的時間加倍。\n就麻煩領航過來陪練吧，這是小生的生日願望，在此謝過了！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000502] = {id = 11000502, name = "華戀", head = "10005", type = 5, title = "命運之日已至！", txt = "大事不妙，領航！\n就在剛剛！小生在桌上發現了不得了的東西！\n【値此吉日，在會客室中為你準備了期待已久的場地與宴席，還請賞臉赴約。】\n毫無疑問，此乃一決生死的戰書，雖然筆跡不知為何與彩華隊長有些相似！\n領航，在前方等待著小生的，定是一場就算了卻此生都能不畱遺憾的對決！\n無論是點到為止，還是以命相搏……就算要與這位好敵手雙雙巨大化，再將畢生的所見所學寄宿於融貫生命的一腳——這樣的覺悟，小生都已經做好了！\n小生希望身邊能有你的見證！\n這是小生自相識以來最認眞的請求！小生會在九州方舟的大堂中，靜候你的到來！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110006] = {id = 110006, name = "棲琳", head = "10006", type = 5, title = "悲喜之日", txt = "終於又到了今天，這個人生中最悲痛的日子，初次與母親分別的日子。\n不管是誰，長大後成為了多麼堅強的人，初來世間都會哭聲連天，可是在之後的很多年裏，每到生日卻又興高采烈…這難道不是人類強大精神力的一種證明嗎？同樣具有化悲為喜能力的我，總是對此有所共鳴。\n不過直到現在，我還是更願度過和首個誕生日有著相同體驗的日子，那種悲痛讓我懷念。\n為今晚而訂的蛋糕上，我特意插了許多紅燭，想必蠟液一定會因那時的快樂而變得滾燙。如果對此有興趣，還請領航快點過來；當然…要是覺得不妥，也歡迎大力責罵、懲罰我喲~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000601] = {id = 11000601, name = "棲琳", head = "10006", type = 5, title = "請盡情鞭打我吧", txt = "黎明前的黑暗是最黑的，生日到來前的前一天是最漫長的。\n在過去的二十四小時裡，我深刻地體會到了這個道理。\n您能體會到我望著時間遲遲沒有買入00:00時的焦躁嗎？是您的話，一定能夠理解的吧？\n現在，終於進入了第二天，我也終於等到了我的生日。\n我盼望著您能像過去那樣帶給我痛苦，帶給我快樂。\n請鞭打我，責罵我，用您的雙手去觸及從未有人觸碰過的領域，讓我靈魂都戰慄起來吧，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000602] = {id = 11000602, name = "棲琳", head = "10006", type = 5, title = "我正在等你", txt = "多瑙的市區裏，那家一直很熱門的咖啡店最近推出了一款叫做“深淵001”的新品咖啡。\n到底有多苦呢？光是想想就很讓人期待——要是能在生日的時候，用最苦的咖啡來懲罰自己的味蕾，那也太幸福了……\n所以，領航，今天能請您陪我去一趟嗎？\n要是能讓領航親手喂我最苦的咖啡，我一定會幸福道昏厥過去的！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110007] = {id = 110007, name = "海姬", head = "10007", type = 5, title = "生日的新娘修行", txt = "冒昧詢問一句，領航對於陪人過生日是否抱有興趣呢？\n您知道我一直在進行新娘修行，為了將來某天能成為一個出色的妻子而努力。而除日常家務以外，在生日這種具有紀念意義的特殊時刻，為家人準備盛宴也相當重要呢。\n不知不覺又到了我的生日，不嫌棄的話，領航可以扮演丈夫陪我一起練習嗎？權當是過家家就好，還可以品嘗到豐盛的菜品，很不錯吧？願意的話，我會在房間靜候您的到來哦~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000701] = {id = 11000701, name = "海姬", head = "10007", type = 5, title = "新婚預演", txt = "領航有空嗎？我給您做一件衣服想讓您試穿下看看合不合身。\n不是什麼奇怪的衣服，只是一套男士禮服，特別適合……婚禮的時候穿,我還給自己做一套婚紗。\n其實我想讓您陪我預演一下婚禮時的情形。“新娘”這個詞可以說本來就是為婚禮而準備的，婚禮是新娘最閃亮的時刻，我不想自己在婚禮上出醜。\n之所以挑在今天，就是希望領航能看在生日的份上不要拒絕我的這個小小生日願望。嘿嘿，這也是我從新娘修行中學到的——身為妻子應該有的一點小心機。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000702] = {id = 11000702, name = "海姬", head = "10007", type = 5, title = "紀念日", txt = "又要來打擾領航了，每年的這个時候我就會想到領航你，明明是我一个人的生日，現在快變成了兩个人的節日了。就像是夫妻間的紀念日一樣。\n如果是夫妻的話應該要互相贈送禮物，而身為妻子更應該在這一天準備一頓豐盛的晚餐。我對自己的廚藝向來充滿了信心。禮物的話，領航喜歡什麽呢？男士手表？手織圍巾？新出的遊戲掌機又或者限量款拼裝模型？\n抱歉，不了解心上人的喜愛之物，正説明我的修行還不够。\n領航，我想要更加了解你！從今天開始，我要為成為領航的新娘而加倍刻苦修行！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110008] = {id = 110008, name = "多洛莉絲", head = "10008", type = 5, title = "新年和生日一起。", txt = "1月1號，新的一年最開始的一天。\n我想您應該還不知道……1月1日同樣也是我的生日。\n有時候我也會想，“生日和新年一起過的話，一年中值得紀念的日子對我來說不就少了一個了嗎？”，類似這樣的問題在我年幼的時候經常困擾著我。\n呵呵，但現在的我認為，兩個日子的重疊讓我的生日和新年都更為特殊，就比如說——我可以在新年的時候吃到生日蛋糕。\n同樣，值得紀念的日子也是可以由我來創造的——我想把我的這份特殊分享給您，讓您的這一天也不同尋常。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000801] = {id = 11000801, name = "多洛莉絲", head = "10008", type = 5, title = "謹賀新年，生日快樂", txt = "新年好！轉眼間又是一年，過去的一年裏我為隊伍的事情而忙碌著，能坐下來好好聊聊天的時間少了許多。\n不知領航近來可好？在這個辭舊迎新的時刻，當然同時也是我的生日……我想與領航一起講講話，共同迎接新一年的到來。\n因此，我誠摯地邀請您參加我的生日新年聚會，共同祈願大家新的一年每一刻都鋪滿希望，每一步都走向我們所期望未來。\n期待您的回復，希望能收到您參加的好消息。如有任何時間上的調整需求，請隨時告訴我，我們可以商量修改安排。\n祝新年快樂，身體健康，萬事順遂！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000802] = {id = 11000802, name = "多洛莉絲", head = "10008", type = 5, title = "心的新境界", txt = "新年快樂領航！\n時間過得眞快，不知不覺又和領航一起度過了一年呢。\n在過去的一年中發生了許許多多的事情，也經歷了很多相遇和分別，總感覺我的心撲通撲通地像是要到達新的境界了……啊！我當然不是説心跳加速了。\n嗚……我也不知道怎麽形容這樣的感覺……就是能感覺到過去的自己進步了，並且希望在未來的一年一定也要再次加油……我想到了，是“野心”……！我的野心是——明年和大家一起變得更好！這就當作生日願望了，嘿嘿。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110009] = {id = 110009, name = "摩根勒菲", head = "10009", type = 5, title = "世界的魔術", txt = "如果說，魔術的本質是為人們帶去無法預測，且不解緣由的驚喜，那麼生命的誕生或許就是世界本身所施展的魔術吧？\n沒人知道自己人生的未來會是怎樣，也不可能明白自己究竟從何而來，但，欣賞魔術的樂趣不正在此嗎？如果真的解明了其中原理，那份神秘色彩反而會煙消雲散，所以，今天就不想這麼多好了，盡情享受施展在我們身上的魔術、這份奇跡吧~\n今晚，為您上演的私人魔術表演已經籌備完畢，還請領航光顧我的房間哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000901] = {id = 11000901, name = "摩根勒菲", head = "10009", type = 5, title = "魔術摩根勒菲", txt = "領航，你好呀！\n最近，為了在我的生日給大家一份驚喜我一直在練習一場特別的魔術表演，可是總覺得少了點什麼……\n後來……我想明白了……魔術最美妙的部分，不是道具、不是手法，而是和特別的人一起完成它。\n所以，我想邀請你，成為我的搭檔，一起在舞臺上創造屬於我們的魔術。\n放心啦，不需要很厲害的技巧，我會一步步教你。\n只要你願意伸出手，和我一起編織光影，見證那些令人驚歎的瞬間，這場表演就一定會是最完美的魔法。\n你願意嗎？如果願意的話，就告訴我吧，我會準備好一切，等你來的——你的魔術搭檔，摩根勒菲。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000902] = {id = 11000902, name = "摩根勒菲", head = "10009", type = 5, title = "做了一个美夢", txt = "昨天晚上難得的做了一个與魔術無關的夢。\n藍天、綠草地、好聞的空氣，然後還有月冕的大家帶著詫異的表情看著我……好懷念，當我第一次給她們展示魔術秀的時候她們也露出過類似的表情呢。\n嗯……遺憾的是我忘了我在夢中做了什麽她們會露出這樣的表情，難道是我在夢中表演了更驚天的魔術秀……對了，領航也在的，我還牽著領航的手要去什麽地方……難道是魔術的一部分？。\n我還記得我穿著純白色的衣服……唔……記不清了，好想知道我究竟在夢中做了什麽，領航我可以去你那裏嗎，也許在你身邊會想起來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110010] = {id = 110010, name = "阿萊塔", head = "10010", type = 5, title = "與“海妖”的燭光晚餐", txt = "回到房間了嗎？\n剛才還好有你路過，不然堆在大廳的那些禮物，我真不知道該怎麼搬回房間……又不能放著不管，畢竟都是粉絲的心意。如果被其他工作人員當成“礙事的垃圾”，在我搬運時把剩下的都清理掉了，那可真是……幸虧有你搭把手，謝謝。\n不過沒想到你力氣居然這麼大，看來以前都小瞧你了呢，領航。那麼以後如果又有類似的事情，我都找你幫忙，如何？放心，我會準備好報酬，不讓你吃虧的。\n至於這次的報酬，讓我想想……不如來個浪漫的燭光晚餐吧？這可是無數薩爾人夢寐以求的哦。尤其今天還是“海妖”的生日。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001001] = {id = 11001001, name = "阿萊塔", head = "10010", type = 5, title = "我即是驚喜", txt = "收到這封信之後，請務必確保在無人的環境下——尤其是多洛莉絲隊長不在的情況下——閱讀該信件的內容。\n嗯，我相信你看了開頭後，不會在公共場合打開這封信，這是我對你的信任噢，領航。\n好了，領航你一定好奇我要跟你說什麼事。\n我也不賣關子了——\n——今天是“海妖”的誕生日，而我決定將這寶貴的一天交給你。\n現在，請你回到自己的房間，將會有一個驚喜在那等著你。\n對，就是我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001002] = {id = 11001002, name = "阿萊塔", head = "10010", type = 5, title = "時間有限", txt = "你有關注最近討論度很高的那個音樂劇嗎，領航？叫《藍瑪瑙》的那個。\n那個是我最喜歡的女演員的謝幕之作。聽說為此特地安排了在全部七個大區的巡演，因為排期太緊所以在薩爾市只安排了7月29這一天的演出呢。\n注意到什麼問題了嗎？\n對，和我的生日撞上了。\n偏偏最近防衛班的工作還挺忙的，回頭再跑去別的支部看演出又很麻煩，所以我想，不如把生日慶祝和看演出安排在一起好了。\n綜上所述，我給你買了今晚8點的票。\n讓手下的駕駛員保持好心情是很重要的吧？所以我就等你赴約咯，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110011] = {id = 110011, name = "弱水", head = "10011", type = 5, title = "有領航哥哥陪著的一天生日", txt = "領航哥哥，我查遍了多瑙所有影院的排片表，發現今天的檔期全都排滿了工業流水線大片！那些電影一看簡介就感覺好無聊喔，難得到了我的生日，還想和領航哥哥一起去看cult片……\n不過後來我想，既然市面上已經被那些毫無靈魂的電影霸佔，不如我們一起來拍部曠世神作改變業界吧？唔……標題的話就叫《有領航哥哥陪著的一天生日》？至於內容，其實可以跟標題完全沒有關係，只是我喜歡這個片名而已。\n如果願意當這部電影的主演，領航哥哥就請來找我吧，相信我們一定能拿到這屆最佳新人獎的~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001101] = {id = 11001101, name = "弱水", head = "10011", type = 5, title = "今天要b級片精通", txt = "領航哥哥……您覺得作為生日的慶祝的話，哪種題材的電影更適合在這一天看呢？我的話……會覺得只要是b級片不管什麼題材都合適喲？牛仔、情欲、黑幫、恐怖、神怪、科幻有關的劇情題材……嗯也許恐怖片不合適……我準備了很多的零食，所以哥哥來我的房間吧。一起在被窩裡看電影……品鑒爛片……累了就睡覺……醒來就吃飯……\n這個生日我想這樣子沒有意義又很有意義地度過，您覺得怎麼樣？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001102] = {id = 11001102, name = "弱水", head = "10011", type = 5, title = "拍一部紀錄片吧！", txt = "領航哥哥！領航哥哥！今天是弱水的生日噢！也是弱水和領航哥哥認識後的第三個生日！\n一、二、三……居然已經是第三個了， 好厲害！\n為了紀念這一天，我們就像最初的那樣，拍一部弱水和領航哥哥的紀錄片吧！\n製作經費什麼的，就從弱水存下來的錢裡出就好了，領航哥哥只需要打扮帥氣地出鏡就好了。\n希望拍出來的電影能成為像那部鯊魚災難片一樣的曠世名作！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110012] = {id = 110012, name = "格洛麗亞", head = "10012", type = 5, title = "致我唯一的理解者", txt = "生日是什麼？是慶祝自己出生的慶典？是恭喜自己又成長了一歲的儀式？我不理解。\n我從未真正意義上理解過“生日”的喜悅。對那些沉浸在生日的快樂中的同學，也只能為她們獻上不解的掌聲。\n直到我遇到了您。\n今早，在聽到你的祝福時，我第一次覺得，過生日似乎真的是一件不錯的事情。\n——啊，真是不好意思，一上來就是些負面言論。但領航先生是唯一想要瞭解我的人，所以我覺得，即便是這樣的我、這樣的話語，您也能全盤接納……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001201] = {id = 11001201, name = "格洛麗亞", head = "10012", type = 5, title = "致我理解的理解者", txt = "請原諒我提前的打擾，在收到領航的祝福之前就送上這份回信，因為我堅信您的祝福一定會如期而至。\n想必您一定能理解我的迫不及待，時隔一年的生日慶典，我積攢了很多話想要向您傾訴，也希望能聆聽您真實的心聲。單方面的尋求理解並不可取，互相的理解才是我最終的目標。\n希望在今天過後，我們之間的瞭解能達到更深的層次。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001202] = {id = 11001202, name = "格洛麗亞", head = "10012", type = 5, title = "慶祝的收尾", txt = "我參考您的建議，邀請第三防衛班的大家一起慶祝了生日。\n多洛莉絲前輩和我一起規劃了整天的安排，羅德尼亞靠一時興起帶我們找到了好多有意思的地方，阿萊塔學姐還唱了她專門編曲的生日歌。\n……說實話，結果好得有些嚇到我了。如果沒有來到艾吉斯的話，我大概一輩子都不會有機會體驗這樣的生日吧。\n不過，愉快歸愉快，有些事我覺得還是代替不了。\n那些我想好要跟領航您談論的話題，我果然——至少現在，還沒辦法直接和多洛莉絲前輩聊起來。\n所以，雖然這完全是我的任性，但在生日的最後幾個小時，能請您像往年那樣，和我聊聊天嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110013] = {id = 110013, name = "莉莉絲", head = "10013", type = 5, title = "再給我點時間……", txt = "我算是明白了，斯卡蒂就是個笨蛋，十足的大白癡。\n今天從起床起就一直嚷嚷著什麼要讓我過個完美的生日，她難道已經退化到聽不懂人話了？我說過我最討厭過生日吧？！\n暫且不說芙露露和吉雅，我怎麼也沒料到她今年居然連摩根都說動了，聚在一起折騰派對的事……好吧。我承認，斯卡蒂這麼做是出於好心，而不是打算以此來膈應我。想也知道，她沒這智商。\n只不過……現在的我，果然還是無法坦然慶祝自己的生日……再給我點時間吧……\n\n……不行，鬧得我頭疼。\n領航，你看到郵件後趕快過來。感覺現在就只有你能管管她們了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001301] = {id = 11001301, name = "莉莉絲", head = "10013", type = 5, title = "需要去看醫生", txt = "從今天早上醒過來開始，腦子裡就有一個聲音在不斷地在吵鬧著，“今天是你重要的日子，請幸福吧，生日快樂。”\n起初我認為這是被通感所感知的聲音，因為這聲音讓我感到很熟悉\n但在仔細聆聽之後卻發現這並不是我認識的聲音。\n我很確定多瑙方舟今天就只有我一個人……只有我一個人過生日。\n領航，為了進一步地確認這是否是我的病情——【偽通感】惡化的徵兆，請你帶我去看“專業”的醫生。\n順便——摩根，斯卡蒂和芙露露正在為我舉辦生日會……請快點來，並且在生日會結束後帶走我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001302] = {id = 11001302, name = "莉莉絲", head = "10013", type = 5, title = "不能辜負大家的好意……", txt = "今年……大家又準備一起給我過生日了。\n我能清晰地通過【通感】知道她們是懷揣著給我驚喜的心情為我準備生日的，尤其是斯卡蒂那個笨蛋，根本藏不住自己活躍的感情。\n所以我在想……我也差不多也應該接受這件事情了，我想開開心心地和大家過生日，不辜負大家想要給我帶來快樂的感情……畢竟大家不知道我的往事。\n所以……領航，我需要你的幫助……有你這種總是帶著白癡笑容的傢伙在旁邊，我應該會更加有勇氣去面對她們吧，呵呵。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110014] = {id = 110014, name = "科羅溫", head = "10014", type = 5, title = "我的生日，你的禮物", txt = "親愛的領航，\n距上一次見面過去很久了，不知道你最近生活還好嗎？\n今天是我的生日，但是我寫這封郵件的目的並不是想向領航索取生日禮物。反而是想送領航一些禮物。\n領航你是知道的，我和家裏的關係不太好。但是父親大人不知道從哪里得知了我在灰燼，派人送了很多東西過來。都是些衣服，珠寶，首飾什麼的用不上的東西，我全給伊莉雅拿去換錢了。剩下一些不太好出手的東西，就只能自己分了。\n我在整理這些的時候突然想到“領航會不會也需要這些呢？”，所以就打包了一些送給你，希望領航會用得上。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001401] = {id = 11001401, name = "科羅溫", head = "10014", type = 5, title = "第二次離家出走", txt = "親愛的領航，正如郵件標題所寫，我又離家出走了，不過這次的家變成了“灰燼”。\n起因兩天前我從外面撿回來了一只“小狗”。我發誓我真的以為那只是一只普通的白色小狗，沒有考慮過“北極熊幼崽”這回事。反正是把伊莉雅嚇了一跳，讓我趕緊把這小生命送回去。我不放心把這小傢伙獨自放在野外，所以就只能跟著它一起離家出走了。\n我在想這個小傢伙會不會是上天給我的生日禮物呢？或許它迷路了，或许它和我一樣都是離家出走的孩子。\n如果哪天我迷路了的话，真希望是领航捡到我呢！糟糕，这算不算是许下生日愿望了呢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001402] = {id = 11001402, name = "科羅溫", head = "10014", type = 5, title = "請原諒自私的我", txt = "親愛的領航，我想問你一个問題。\n如果讓你在家族和朋友之間選擇，你會選擇哪个？\n即便是再任性胡鬧，有些事也是逃不開的，比如説繼承家族的産業。作為家族這一代的獨女，這是我不得不承擔的責任。隨著年齡的增長，那一天也離我越來越近，説不定明天管家就會出現再一次把我帶回去。\n我也想過如果我回去，或許就能更好地幫助伊莉雅她們，或許這才是最好的選擇。可是我不想離開灰燼的大家，也不想離開領航。回去之後和你見面的時間只會更少。\n“如果結局無法改變的話，我只希望中間的路程能變得更長一些。”\n請原諒我許下這个自私的生日願望。\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110015] = {id = 110015, name = "索菲亞", head = "10015", type = 5, title = "關於出擊申請", txt = "領航，你知道今天是我的生日吧？如果可以，我也想像普通人那樣，和喜歡的人一同慶祝。但那是不可能的。\n我明白自己的異常，明白心底那難以克制的欲望……呵呵，或許是因為今天在卡佳支部裏看到了你，現在胸口翻湧的這份渴望，比往常更濃厚、更難壓抑。\n所以領航，不要再拖延了，通過我的申請吧。如果不盡早將這份躁動發洩在那些原罪身上，我或許會……不行，我現在還不想將領航你弄壞掉啊……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001501] = {id = 11001501, name = "索菲亞", head = "10015", type = 5, title = "渴望肉宴", txt = "領航，我渴望破壞。\n為了慶祝我的生日，請來和我一起準備生日宴會吧。\n我準備了很多廚具和肉。接下來要用廚刀去掉肉的皮膚，連帶著血肉一起從肉的表面剝離掉，肉和皮膚要分開料理。\n再破壞掉皮下組織……啊……啊……一想到滿溢的脂肪被破壞的瞬間，真是令人陶醉……希望來賓們會喜歡這些脂肪，作為駕駛員可不能太瘦弱，我還是喜歡豐滿一點的身材，更讓有人有破壞欲……\n當然……還有順著紋理就能暢快地切割到底的深層組織……這就是我的生日宴會，把大家的體重破壞殆盡的肉宴……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001502] = {id = 11001502, name = "索菲亞", head = "10015", type = 5, title = "破壞節制之日", txt = "最近是節制的時間。\n如果可以的話我當然想要一直破壞下去，但是那樣只會讓我不斷地分泌快樂的多巴胺，成為多巴胺的奴隸，越是殺戮越是渴求越是殺戮，直到最後失去理智……沒錯我已經不知道幾次地犯下這樣的錯誤了。\n失去理智，這並不是我想要的，我追求的是能清晰地感受殺戮的清晰感……如果失去理智的話，那就不過是只會狂吠的野獸罷了。\n所以——就讓我們這次和平地度過這次生日吧，破壞蛋糕的殊榮——這次就交給你了，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110016] = {id = 110016, name = "安安", head = "10016", type = 5, title = "今天是我的生日", txt = "老師，百忙之中不慎打擾，今日是我的生日，本想邀請您前來一同慶祝，但考慮到多瑙距這路途遙遠，不忍讓老師顛簸......\n其實...上面這些話是班長幫我的寫的，寫作方面...我不是很擅長。但是我只是想告訴領航今天是我的生日，並沒有其他什麼意思。\n生日蛋糕很好吃，是天天幫我做的。天天真的好厲害，會做那麼多好吃的，而我只會煮面，而且鄉下的家裏也沒有那麼多食材可以烹調。\n所以我許願的內容是要在接下來一年裏學會一道湯麵之外的料理。等我學會的那一天，一定會請領航來吃。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001601] = {id = 11001601, name = "安安", head = "10016", type = 5, title = "老師我學會了！", txt = "老師，你還記得嗎？\n去年生日的時候，我說過要向天天學習做料理，老師應該還記得吧？\n雖然安安我很笨，花了很久都沒學會——但就在昨天，我終於讓天天師傅滿意了！\n總之，今年的生日，請老師品嘗由我製作的，天天師傅親傳的芥末蜂蜜千層漢堡肉吧！拜託了，請一定要來！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001602] = {id = 11001602, name = "安安", head = "10016", type = 5, title = "時間好快呀！", txt = "騙人的吧！誒！？眞的假的，今天又是生日了嗎？！\n明明感覺前不久才學會天天師傅的親傳料理，和老師一起度過了讓人心臟怦怦跳的生日……\n時間，眞是不可思議啊——那、那，老師！今年的生日，我還可以和你一起過嗎？可以嗎？安安是不是太貪心了？\n如果老師願意的話，我什麼都願意做的！！！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110017] = {id = 110017, name = "羅莎琳德", head = "10017", type = 5, title = "貴族的盛邀", txt = "本小姐相信，領航若是一名傑出的紳士，就早已該知道今天是什麼日子。而正如每位貴族都當遵守的禮儀那樣，本小姐親筆寫下此信，旨在向您發出盛情邀請，望您能駕臨羅斯柴德家族宅邸，參加本小姐的生日宴會。\n屆時除了商政界顯要人士，瑪雅最傑出的音樂家、舞蹈家，以及傳奇主廚都會到場為宴席添色——雖然想這麼說，但上述這樣庸俗的陳腔濫調，想必領航也已經聽到厭了吧？\n於是，本小姐決定這次慶祝儘量從簡，就當是體驗一次尋常人家的生日，享用些家常菜倒也獨有風味。事先提醒，領航到場後大可不必驚訝，這並不代表本小姐落魄了哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001701] = {id = 11001701, name = "羅莎琳德", head = "10017", type = 5, title = "一個不幸的消息", txt = "領航，貴安。\n想必您現在一定在為籌備本小姐的生日禮物而絞盡腦汁吧。\n但不幸的消息是今年家族的經營出現了一點問題，苦心操辦的一家企業出現了財政危機，不得不面臨解散重組的困境。當然，對於資金財產雄厚的羅斯柴德家族來說這只是平靜海面上翻起的一個小波浪而已。\n而此次危機恰逢本小姐生日，作為家族長女，本小姐需要表現出一點擔當。所以本小姐主動向家中請願，取消了原定的奢靡華貴的晚宴，省去那些不必要的開支，本小姐也難得有了閑餘。\n記得之前領航曾談到過幾家味道不錯的平民小吃。如不嫌棄，本小姐今日陪您一同前去。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001702] = {id = 11001702, name = "羅莎琳德", head = "10017", type = 5, title = "也就是——注重精神體驗的旅遊", txt = "最近，似乎在流行一種時尚的、潮流的、先進的、讓人為之欽佩的旅遊方式。\n本小姐動用了一點家族的手段，稍微了解了下這種旅遊方式。\n“刻意剥离那些浮华的物质附加，让旅行回归纯粹的精神探索，一種低物質密度，高精神濃度的旅行方式。”\n的確，本小姐平日裡已經習慣了千篇一律的物質生活，當下欠缺的是更為豐富的精神體驗。\n於是，領航，有興趣與羅斯柴德家族的長女——羅莎琳德出門旅行嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001703] = {id = 11001703, name = "羅莎琳德", head = "10017", type = 5, title = "必要事物的購置", txt = "領航，貴安。\n當你收到這則消息，我正為一些尋常的家族瑣事所擾。\n如您所知，作為羅斯柴德家的長女，每年生日，我的家人們總是會為我準備奢侈過頭的賀禮。\n像是能連著換一個月不重樣的禮裙，瑪雅知名藝術家制作的珠寶首飾之類的……我雖然能體會到她們的心意，但諸如此類的東西並不適合我平時作為駕駛員的生活。\n因此，我特意從自己的積蓄裏抽出了一些，準備出發去購置一些更為實用的衣物。\n作為我最為信任的上級，我需要一些來自於您的可靠意見。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110018] = {id = 110018, name = "莉法", head = "10018", type = 5, title = "晚宴菜品清单", txt = "今天我很早就起床開始準備生日晚宴。\n我準備了一些醃青瓜，胡蘿蔔和土豆沙拉作為前菜，搭配奶油蘑菇濃湯和黑面包。主菜我選用九州進口的豬腿肉切成碎，調味後用包菜葉包成卷狀後做成包菜卷，另外還準備了一大鍋的美味紅菜湯。最最重要的甜品部分當然就是我親手製作的水果生日蛋糕。還好廚房庫存裏有足夠的剩餘水果，省去了去市場選購的時間。\n本來我覺得已經完美無缺了，但直到我佈置餐桌時才想起來我還沒有邀請過任何人赴宴。\n所以我想邀請您來參加生日晚宴，再帶上您的朋友，無論多少人都可以。身為最優秀的女僕我有信心一定會服務好大家。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001801] = {id = 11001801, name = "莉法", head = "10018", type = 5, title = "大事不妙了啦主人！！", txt = "大事不妙啦！大事不妙啦！莉法小姐陷入前所未有的大危機了啦！\n雖然每個人對“大危機”的定義不同，相同的人也會因為時間場合的不同而對同一件事的危機等級判定不同，但不管怎麼說，對於我來說，現在就是“莉法小姐的大危機！”\n總而言之，莉法小姐睡過頭了！原本要預定做的生日晚宴來不及做了！“完美女僕”的形象要毀滅了！要被第一親衛班的人嘲笑了啦！\n請幫忙想想辦法吧，主人！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001802] = {id = 11001802, name = "莉法", head = "10018", type = 5, title = "是時候評定誰才是眞正的女僕了", txt = "女僕係角色太多了。\n這是我最近（也可能很早）就意識到的問題。\n“完美無缺的莉法小姐”是女僕係的角色，第一親衛班的那些人也是女僕係角色，而且最近也冒出了好多女僕角色變種的人……莉法小姐的身份獨特性出現大危機了！\n所以，為了確保莉法小姐——也就是本人獨一無二的全能女僕（暫定）地位，我決定在生日這天召開“女僕大賽”，就以“準備滿分的生日宴席”為比賽項目，決出眞正的至高女僕！\n領航，評分的時候要給我打高分噢！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110019] = {id = 110019, name = "結束希", head = "10019", type = 5, title = "也想听你演奏、唱歌", txt = "生日啊……\n記得以前組樂隊的時候，每逢生日都能收到好多粉絲禮物——我是說隊友她們。畢竟我的天賦擺在那裏，只是個凡人，演出時被天才的光芒吞噬什麼的，再正常不過了。於是生日也就自然只有朋友、家人記得。\n好啦，不說這些喪氣話了。我只是突然想起，領航你以前都是在一旁聽我演奏、唱歌的，對吧？我們今天可以顛倒一下。正好生日快樂歌的譜子不難，能很快上手。\n至於樂器，架子鼓、吉他、薩克斯、小提琴、鋼琴……嘛，基本上常見的樂器我都會、都能教，你隨便選一個想嘗試的。選好了記得給我回信。我先校正一下音高，再帶著它來找你。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001901] = {id = 11001901, name = "結束希", head = "10019", type = 5, title = "“向世界展示結束希的樂隊”", txt = "祝我今天生日快樂！！！嘿嘿……終於能大聲地說出這句話了。\n生日真是一個很神奇的日子呢。對我而言期待著生日的那些日子會很開心，過生日的時候當然是最很開心的時候，過完之後這份開心還會繼續陪伴我一段時間，所以我想我的生日是以一個月為單位計算的。\n那麼來做一些有意義的事情吧，為了紀念這一天要來和我來組建“一日樂隊”嗎？名字就叫“向世界展示結束希生日的時候很開心樂隊”，主打歌是我們兩人的生日快樂歌，嘿嘿……這首歌送給你也送我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001902] = {id = 11001902, name = "結束希", head = "10019", type = 5, title = "生存戰略時間！！！！", txt = "不好了！！！！\n我宣佈現在是結束希的生存戰略時間！！！\n我一直在聽著的《迷路》樂隊竟然宣佈要解散了！！\n明明昨天才開了演唱會……為什麼會變成現在這副樣子！！\n我要去問個究竟……以前輩的身份！\n領航快點換上衣服，我們去一探究竟吧。不然的話今年的生日一定會變成我絕對不想記住的血色誕生日的！！\n我結束希，是絕對不會讓這個樂隊就這樣結束的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001903] = {id = 11001903, name = "結束希", head = "10019", type = 5, title = "樂隊排練視頻洩露！！！", txt = "領航領航，緊急事件——不對，是超級大發現！\n我今天早上本來在調試新買的loop效果器，結果在房間的角落裏突然發現了一卷神秘的錄影帶。你知道是什麼嗎——是我還在【逆向燃燒】時期的排練錄音！就是那種，貝斯手忘譜了、鼓手搶拍了、主唱破音了的那種原始錄音！！\n這些錄影帶理論上應該在第三次搬地下室的時候弄丟了才對……居然在生日這一天找到了這麼具有紀念意義的磁帶，這可是我最珍貴的寶物……不可思議……\n我已經準備好了零食和飲料（很豐盛哦！），你要不要一起來聽結束希音樂考古學發表會？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110020] = {id = 110020, name = "未來", head = "10020", type = 5, title = "受歡迎的日子", txt = "變態先生能不能來我家陪我過生日……因為新年和生日一起過的原因，所以爸爸媽媽準備了很多很多我喜歡吃的……我一個人絕對吃不完！超級推薦變態先生過來試一試媽媽的拿手菜！\n順便還可以看到我穿的好好看的衣服，是變態先生絕——對——沒有見過的新衣服哦~能看到這樣的我的變態先生真是世界上最幸福的人呢~\n快點來吧！我會等著你哦！大家也都很歡迎變態先生！（但是還是沒有我受歡迎，大概變態先生是第二受歡迎！）", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002001] = {id = 11002001, name = "未來", head = "10020", type = 5, title = "見證未來的未來", txt = "變態先生！祝我生日快樂！\n聽我説聽我説——今年的願望是去世界上最大的遊樂園！事不宜遲現在就來實現我的願望吧！\n人家長大以後的目標可是要成爲世界上最歡迎的人的，作爲參考對象，我要搜集受世界歡迎的要素。\n已經被我迷得神魂顛倒的變態先生會見證我的成長的對吧！你可不能拒絶哦！\n所以——帶我去遊樂園吧，然後一起見證未來的未來吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110021] = {id = 110021, name = "辛西婭", head = "10021", type = 5, title = "兩人的信", txt = "是辛米亞提議寫信的。\n我跟她說了生日的事情，也準備了禮物，結果卻被反問為什麼特地巨大化找她……當然是想要和她一起慶生啊……\n今天是我的生日，也是辛米亞，明明說好了的……每年都這麼問，辛米亞是大傻蛋！\n辛西婭把紙和筆扔給我後就不理我了……\n她應該為我著想一下，這麽大的身體該怎麽寫字嘛……\n巨大化後她和我說了很多有關於你的事情。她很喜歡你，我能聽出來。那麼相比於我，今天這個難得的日子，她更應該和你呆在一起才對。\n可是不管怎麼勸說，她都不肯取消巨大化。我只好提議寫信。\n你看到這封信後，來帶她去過一個難忘的生日吧。領航，拜託了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002101] = {id = 11002101, name = "辛西婭", head = "10021", type = 5, title = "三人慶生！", txt = "對於“倆人一體”的我們來說，生日是同一天是理所當然的。\n但是，領航你也是知道的……通常情況下，“辛西婭”和“辛米亞”是沒辦法一起度過生日的，除非……\n好啦，我就不裝神弄鬼啦，總之現在是辛米亞，也就是我在寫信！\n今年的我們決定和領航你一起度過生日，為了實現這一目的，辛西婭特地申請了巡邏任務。\n接下來只要你同意，我們就可以用巡邏任務當做三人慶生的方式啦！\n雖然這樣做有點瀆職……但只要任務也好好完成就會被原諒吧？\n領航，快來，這時候的我們應該已經準備萬全了！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002102] = {id = 11002102, name = "辛西婭", head = "10021", type = 5, title = "兩人的邀約", txt = "我是辛西婭。\n我是辛米亞。\n我們是二人一體的駕駛員！\n怎麼樣，這是我精心設計的自我介紹，可惜辛米亞她不喜歡。\n其實我也沒說不喜歡，只是覺得有點老土。\n這不叫老土，應該叫經典。\n還是快點說正事吧，領航還記得今天是什麼日子嗎？\n生日，辛西婭的生日……\n也是辛米亞的生日。\n我正要說的。\n我幫你說了，不用客氣。\n……\n我們在等著領航你來。\n與我們一起慶祝這個日子。\n就像之前一樣。\n我，辛西婭。\n我，辛米亞。\n我們等著你。\n……\n領航你感覺到了嗎？今天的辛米亞似乎和之前有點不太一樣。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002103] = {id = 11002103, name = "辛西婭", head = "10021", type = 5, title = "兩人的慶祝", txt = "過去幾年的生日都是三個人在一起慶祝，雖然很開心就是了，不過每次都得巨大化還真是很麻煩呢。\n所以今年我想就不要這麼麻煩了，領航也可以輕鬆一點，一起逛個街，吃點甜點，在山間的小路上遙望恢弘的落日。過一場正常人的生日。\n因為，我希望以後得每一場生日都能成為我們美好的回憶，而不是辛苦的負擔。\n忘了說了，我是辛米亞，所以不用擔心我的感受，這原本就是我提出的想法，辛西婭已經答應了。\n另外，用巨大的手寫信真的好難啊。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110022] = {id = 110022, name = "法芙娜", head = "10022", type = 5, title = "惡龍與巧克力慕斯", txt = "沒想到報應這麼快就降臨到我身上，說什麼懺悔的話也來不及了。雖然一度陷入了和昨天生日的梅爾一樣的窘境，但是僅憑她們三個想要馴服惡龍，多少有點不自量力了。惡戰無法避免，手臂到現在還有些發麻，好在趁著完全暴走前，離開了訓練場。\n一年一次的生日時間，我能感覺到心中的惡龍在躁動，唯有蛋糕可以將其安撫。惡龍告訴我她想要吃巧克力慕斯蛋糕，淋上淡奶油、蜂蜜和榛子仁混合製成的甜漿，搭配一杯撒滿巧克力粉的熱可可。\n惡龍似乎變得更貪婪了，她還想要領航你來一起慶祝惡龍的誕生。\n不過從很早之前我就在想，惡龍的誕生真的值得慶祝嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002201] = {id = 11002201, name = "法芙娜", head = "10022", type = 5, title = "惡龍的渴望", txt = "我發現現在有很多故事都喜歡寫——“勇者打敗惡龍又變成新的惡龍”。\n似乎想通過這樣的結局，來探討人性的貪念。但是我想說，他們都沒有說到點子上。\n“勇者”是不會變成“惡龍”的，只有”惡龍“才會變成”惡龍“。很多故事的主角從一開始就是披著人皮的“惡龍”。\n或許我也是這樣。\n我能感覺到，隨著年齡的增加，藏在我心中的那條惡龍似乎越來越難以約束。她渴望著在生日這天，將領航你從所有人身邊奪走。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110023] = {id = 110023, name = "摩", head = "10023", type = 5, title = "毛衣還是圍巾？", txt = "不想過生日嗼，每一次過生日都意味著又老了一歲嗼。特別是在地球上的一年又如此短暫，感覺生命飛速流逝了嗼。\n生老病死，好想改變自然規律嗼，但是就算能改變衰老的進程，也還有生病和死亡需要克服嗼。不過我也沒有資格抱怨就是嗼，畢竟還沒有老到一只腳跨進棺材的窘境嗼。\n另外，我想問問領航你是喜歡毛衣還是圍巾……可能是因為季節原因，最近我掉了不少毛嗼，收集的量已經足夠一件衣物嗼。反正我現在無所事事，正好有時間可以織衣服，領航還沒有穿過用埃塔人的毛髮製成的衣物吧嗼。\n期待我的手藝吧，手工編織可是“牧者”的必修課嗼。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002301] = {id = 11002301, name = "摩", head = "10023", type = 5, title = "襪子還是內褲？", txt = "早上好，下午好，晚上嗼。\n因為不知道領航會在什麼時間看到這封信，所以乾脆一次性把招呼都打了嗼。\n寫信來也不只是為了打招呼嗼，到生日了嗼。不過雖然是生日，可現在忙得不可開交嗼。告訴領航一個好消息，我找到新的工作了嗼。和我原本的工作一樣在幼稚園照顧小孩子嗼，是人類的幼稚園。\n原本還擔心我的樣子會嚇到他們，但孩子並沒有害怕嗼。似乎是把我當成打扮奇怪的人類老師嗼，這樣也不錯嗼。\n另外抱歉嗼，最近攢的絨毛有點少了嗼。毛衣大槪是不夠了，但是一雙襪子綽綽有餘，或者說是……一條內褲嗼？\n領航想要哪個嗼？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110025] = {id = 110025, name = "梅爾", head = "10025", type = 5, title = "自由的煩惱", txt = "今天是我生日了呢。\n明明還要進行戰鬥訓練，卻被小隊其他人摁著頭放了一天的假。她們下手太狠了，我腦袋上的包到現在還沒有消下去。三個打一個算什麼本事，有本事一對一較量！\n今天的我，暫時算是自由了……平時的時候倒是常會想有時間一定要去哪裏玩，去吃哪家店。真空閑下來反而不知所措。\n剛才換衣服的時候，看到鏡子裏的自己好像又長高了。算算時間，二次發育應該早就結束了，是巨大化的副作用嗎？要是爸媽看到我現在長這麼高，一定會嚇一跳吧，不過在上學的時候我就是班裏最高的孩子。\n自由啊自由……既然是生日，先去買個蛋糕吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002501] = {id = 11002501, name = "梅爾", head = "10025", type = 5, title = "我可是隊伍最聰明的", txt = "今天訓練的時候，那三個傢伙一直心不在焉的，都被我通通教訓了一頓，就連平日最囂張的法芙娜也被我狠狠打了腦袋。\n哼，鬼鬼祟祟的，一看就知道她們是故意放水讓我贏的，畢竟今天是我的生日。\n她們不會以為這樣做，就能讓我高興了吧？\n我想要的是貨真價實的強大，是能守護所有人自由的強大，可不是被哄著就能滿意的！\n領航，既然她們沒有這份覺悟，那就由你來過來陪我訓練吧！\n即使是生日，我也不能懈怠！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110026] = {id = 110026, name = "娜斯佳", head = "10026", type = 5, title = "綁架信", txt = "當你收到這封信的時候，說明娜斯佳·阿·伊莉莎白正在我手上。\n放心，我會保證她的人身安全，只要你按照我的要求做到以下幾件事。\n第一，去蛋糕店訂購店裏最大的蛋糕，在蛋糕上要寫上“生日快樂，祝我一生的女王”。蛋糕的樣式隨便，但是不要放芝士，也不要放巧克力，我減肥。\n第二，去最近的首飾店，選一個最貴的鑽石戒指，不用擔心價格，有人會幫你付錢。\n第三，帶著上面兩樣東西在今天晚上八點去塞倫公司門口等著，到時候會有人帶你到你該去的地方。\n記住不要報警也不要告訴其他人，只要做到這些，我保證你和她能夠一起看到明天的日出。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002601] = {id = 11002601, name = "娜斯佳", head = "10026", type = 5, title = "演唱會邀請", txt = "今天是什麼日子，你應該沒忘記吧?\n猜猜看今年我要用什麼方式來慶祝，算了直接告訴你好了，就憑你那個雜魚腦袋就算想爆了也絕對想不到本小姐的絕妙點子。我要讓原罪給我唱生日快樂歌，而且不止一隻，是一群。\n一群巨大兇殘的怪獸為我的生日合唱，如此動人的場景真令人熱淚盈眶。\n現在“合唱團”的成員已經到齊了，甚至還有一隻准罪級擔任“主唱”，還缺少一名“指揮”，想來雜魚領航你來擔任再合適不過。\n至於安全方面不用擔心，這些本來就是些抓起來做實驗的“小白鼠”。而我們也會在一個絕對安全，安靜的房間裏一起享受這場美妙的演唱會。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002602] = {id = 11002602, name = "娜斯佳", head = "10026", type = 5, title = "沒有任何疑點的通知函", txt = "我相信你還記得今天是什麼日子？很好，那你應該也把相應的時間空出來了。\n放心吧，今年沒什麼讓你光是看資訊就臉色發靑的安排。\n兩小時後來見我，別帶什麼亂七八糟的東西。這可是原罪都會識趣地去睡大覺的冬天，我保證，你可以安心地在卡佳最負盛名的雪景酒店裏度過一個美好的夜晚。\n讓我猜猜，你現在正因為今年的安排太普通而一臉錯愕？\n最失禮的那種情況，可能正為思考本小姐會在那個環節設置“驚喜”而皺著臉？\n儘管瞎想吧，雜魚領航。\n我會把你困擾的表情也當做今天的點綴的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110027] = {id = 110027, name = "亞爾薇特", head = "10027", type = 5, title = "感到荣幸吧。", txt = "\n我的合作者，你近来的表现我都看在眼里，作为对你不断砥砺自己的奖励，我特别准许你参加我的宴会，感到荣幸吧，你是唯一一位获得这份殊荣的人。\n人造人被决定制造出来的那一天，一枚胚胎成型的那一天，获得意识的那一天……都能成为我的生日，不过你要谨记，我更愿意把我获得自由的那一天作为这值得纪念的日子。\n哼哼，我想今夜应该会稍微有趣一点了，你不会让我感到无聊的吧，我的合作者。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002701] = {id = 11002701, name = "亞爾薇特", head = "10027", type = 5, title = "肆意慶祝吧！", txt = "作為被我認可的合作者，你應該不會忘記今天這个重要的日子。\n想必你現在還在忙著拯救世界，但請記住，世界需要拯救，宴會也需要參加。\n這是所謂的儀式感，也是調節情緒的方式之一。我可不希望看到你挺過了戰場的槍林彈雨，卻倒在自己的胡思亂想裏。\n我想優秀如你應該明白我的意思。\n這封信件也是邀請函，今夜的生日宴會，我最遲會等候到12點。\n可不要讓我失望，我的合作者。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110028] = {id = 110028, name = "墨君", head = "10028", type = 5, title = "望明日相聚", txt = "展信佳。\n每逢生辰，總有往屆學子前來造訪。她們多已有所建樹，屬實讓人欣慰。\n然今日有人在慶生之餘，問我近日課上言語不似往常那般嚴厲，莫非是遇了喜事？彼時我未作回答，只覺得是種打趣，當不了真。待幾人離去，我回顧近期舉止，發現竟確有其事。\n領航，我許是在模仿你。\n自結識以來，你引領駕駛員時的那份溫柔，及可使朽木成才的耐心，讓我看到了另一條教學之路，以及……事到如今才察覺此事，愧悔無地，但為時未晚。故起筆作信，妄將之記述其中，卻書不盡意，只得餘候面敘。不知明日可有空小聚？\n\n敬候回諭。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002801] = {id = 11002801, name = "墨君", head = "10028", type = 5, title = "與君共勉", txt = "致吾之良師亦摯友\n許久未見，倍感葭思。今日磨墨提筆，並非有何要緊事。起因是昨日酉時三刻，我的幾位學生尋到我的住處來，遞上蛋糕、鮮花等裝飾精美之物，說是提前為我慶生。\n我方才醒悟，原來是又到了慶賀誕辰之日。隨即想起，自去年今日與領航相聚以來，已然有一年之久。在這一年的光陰裏，我已將從領航處習得的諸多教學之法，躬行實踐，融會貫通，施行於日常教學之中。學生們似是喜於新方式，學業更是竿頭日上，我倍感欣慰。\n但我深知教書育人，絕不能因循守舊，故步自封。故今日想再請領航小聚一番，共談育人之理。\n拜書以聞，企盼還雲。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002802] = {id = 11002802, name = "墨君", head = "10028", type = 5, title = "人生碌碌", txt = "領航，見信如面。\n“時維九月，序屬三秋”——夏日的餘溫早已從雲端散盡，枝頭與庭院的秋菊，都掛滿了濃濃的秋意。\n我知你總是醉心工作，這些起居小節上難免疏忽。眼下正是季節交替，涼意最重，一不小心便易感染風寒，望你務必多多留意，善自珍重。\n些許寒暄叮囑之語，請勿見怪。/其實此次起信，是有一件歡喜事想與你分享。\n今日正逢我誕辰之日，我已在庭院備好酒席，願與領航小酌一敘。\n人生碌碌，得一知己共此良辰，足慰平生。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110029] = {id = 110029, name = "莉莉", head = "10029", type = 5, title = "我會努力過好生日的！", txt = "一直以來照顧我們的人已經不在了，萊薇又從來不注重生日這種事，所以這種時候，我要振作起來才行！\n領航，來幫我吧，我們一起籌辦一個讓所有人都能開開心心享受的生日晚會吧。\n萊薇可能會喜歡那種浪漫風格的，千秋小姐應該想要那個……霜淇淋漢堡對吧？\n領航呢？領航喜歡什麼樣的生日晚會？可以的話請儘快回復我！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002901] = {id = 11002901, name = "莉莉", head = "10029", type = 5, title = "今年的生日，也希望能和大家一起過", txt = "領航最近一定特別忙吧……嗯，就算你不說，我也是知道的。\n不管是九州的方舟，還是多瑙的方舟，在駕駛員之間都流傳著您在暗地裡活躍的傳聞\n不只是領航，千秋小姐……咳——千秋，還有星爍小姐，也一定在世界各地因自己的使命而奔波吧。\n這種時候，我就會覺得，“生日”真是一個偉大的發明，有了“生日”，我就有和大家聚會的藉口了。\n今年的生日，我和萊薇也會在方舟上等大家回來的！\n請一定要來啊。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110030] = {id = 110030, name = "法爾奈斯", head = "10030", type = 5, title = "權當一次考驗", txt = "誠如您所知，今天是我的生日，根據蘭特家族的傳統，我會回自己出生時的那座莊園赴宴，重遊那座春意盎然的花園。\n不過所謂宴會，其實也只是種說法罷了，對於家族內部成員而言，我們更愛叫它“派對”，因為這裡不會邀請陌生人，也沒有社交場合那種繁文縟節，它只為開心而存在。\n我很想邀請您一同參加這場派對，但又考慮到我們家族樹敵不少，塔斯卡尼不算太平，只能看您自己如何決定……或者，就當是我對您勇氣的一點小小考驗也好？呵呵，總之，啟程的專機已經備好，如有意願還望盡快回復。\n期待與您一起分享主廚最拿手的那道墨魚汁燴墨魚。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003001] = {id = 11003001, name = "法爾奈斯", head = "10030", type = 5, title = "派對開始前的異味", txt = "9×19mm的手槍子彈擊穿莊園裡的綠葉時，瀰漫在空氣中的火藥味像突然紮在鼻子裡的一根針，讓我明白今年的生日派對註定要被不識趣的人掃興了。\n您是知道的，我們家族在塔斯卡尼算不上受歡迎，總會有不長眼的人想方設法找我們的麻煩。\n別擔心，派對會按時舉行，發給您的邀請函依然作數。\n當載著您的專機落地時，我會親自迎接您，向您展示蘭特家族待客的最高禮遇。\n只是遺憾的是，火藥味恐怕不會那麼快散去。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003002] = {id = 11003002, name = "法爾奈斯", head = "10030", type = 5, title = "50％的私人邀約", txt = "可能只是我多心了——但，您沒有刻意放置我的消息，對吧？\n咳咳，我承認，去年晚宴上的不速之客有些超出家族的預料。塔斯卡尼的風土和多瑙確實存在一些無法彌合的差異，我能理解艾吉斯方面擔憂您安危的想法……\n太繁複的話語只會顯得無力，請允許我將場面話放到一邊。\n在有不速之客光顧時解決麻煩的；願意穿過半個塔斯卡尼迎接您到來的；向家族同胞們發號施令的，和切實希望在生日這一天有您陪伴的——這些無一例外，全都是我。\n如果您對家族的風格有所顧慮，但還有餘力回應一位駕駛員的私人邀請的話——我會盡力，在這一年打消您的疑慮。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110031] = {id = 110031, name = "奧菲莉亞", head = "10031", type = 5, title = "等待您的回信", txt = "冒昧打擾，關於今天……我想知道領航會不會有空呢？\n其實也沒什麼特別的啦，只是家裡人突然打電話祝我生日快樂，我才想起有這件事。以前過生日，奶奶都會做好多豐盛的菜，而且還不讓我去廚房幫忙，說是有爸爸媽媽幫忙就夠了，我只用幫忙吃……但今年，我想買票回老家一趟，他們卻讓我在這邊和朋友一起開心玩，體驗下在大城市過生日的感覺，說這個比較重要。\n於是，我就想到了領航，記得您之前想帶我去逛商業街、去遊樂園玩，還有看電影……唔，倒也不用這麼複雜，我認為有領航陪著的話做什麼都會開心。當然如果沒空也沒關係的，我會等待回信。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003101] = {id = 11003101, name = "奧菲莉亞", head = "10031", type = 5, title = "恭喜水車村第一駕駛員奧菲利亞生日快樂", txt = "我、我今年沒有回家……每一年都麻煩領航陪我回家，領、領航會不會感到麻煩？不過今年就不用那樣了……。\n啟泉會的大家說想要和我一起慶祝。我已經和家裏人打好招呼不回去了……說、說實在的，每一年生日回去的時候，村、村子裏都會貼一些“恭喜水車村第一駕駛員奧菲利亞生日快樂”的橫幅……我、我每次都不敢抬頭看……\n所以……這次……我的生日會領航可以給我一起嗎……嘿嘿……\nPS：生日當天從水車村寄來了【“恭喜水車村第一駕駛員奧菲利亞生日快樂”的橫幅】，被梅莉雅壞心眼地掛到了顯眼的位置。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110032] = {id = 110032, name = "克裏斯蒂娜", head = "10032", type = 5, title = "已經沒有多餘的時間了", txt = "非常糟糕……今天竟然是我的生日，但是這一周我已經沒有多餘的時間了，就連透支的部分也沒有了。\n今天晚上還有一組數據沒有測，果然過生日對我這種人來說太浪費時間……有辦法了，領航要不要來實驗室和我一起過？剛好我這裏有一份基於尼姆比斯能的有趣報告，如果實驗順利的話，晚上還能吃到我親自做的蛋糕呢。你不好奇嗎？用尼姆比斯能幻化出的草莓蛋糕會是什麼味道。\n不過也只能僅此一次了，畢竟用珍貴的能源來生成廉價的蛋糕，太過於奢侈了……聽起來還有點不符合我審美夢幻色彩。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003201] = {id = 11003201, name = "克裏斯蒂娜", head = "10032", type = 5, title = "快給我點靈感", txt = "啊哈……值得慶祝的日子，我沒有靈感了。\n包括昨天也是，我睡得可舒服了，哦，這樣的日子合該用來浪費，就連那個亞爾薇特也一臉憐憫地對我說要不我還是去找找靈感好了，然後她給我特別批准了假期。\n好極了，我現在終於有時間去做點自己應該做的事情了，比如好好地規劃我的生日，也許你可以過來和我一起做……哦，我想起來了一些有趣的東西。請你來我的實驗室吧，我剛剛想到了要是讓每一天都是我的生日該多好，有沒有這樣的時間裝置或者認知改變裝置呢？\n快來實驗室和我一起想想……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003202] = {id = 11003202, name = "克裏斯蒂娜", head = "10032", type = 5, title = "睡了兩小時依然很興奮", txt = "領航，今天是值得慶祝的日子對吧？\n但我發現了一件更有趣的事情——起因是這樣的：上周我突發奇想，決定做一個對照實驗。一組塗新買的眼霜，另一組什麼都不塗，然後分別記錄睡眠2小時和4小時的黑眼圈變化。結果你猜怎麼著？我忘記給自己安排“正常睡覺”的對照組了！\n更糟糕的是……現在左眼比右眼黑半個色號，看起來像只奇怪的熊貓。\n生日快樂？不，這是實驗紀念日才對。\n你要不要來看看這個“不對稱熊貓”？順便一起吃蛋糕——我提前買好了正常的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110033] = {id = 110033, name = "柯朗", head = "10033", type = 5, title = "關於你發給我的那封慶生賀語", txt = "既然你會給我發祝福短信……抱歉，是我的疏忽。忘記提前跟你說明一下情況了。\n雖然檔案上確實記載了我的生日是今天，但實際上嘛，由於駕駛員必須要填寫檔案，我就隨便寫了個上去。\n好吧，也不是很隨便。至少從實驗記錄裏能倒推出，我是在11月份左右出生的。所以也算不上欺詐，至少前面的月份是對的。\n或許你會好奇，為什麼不是31號，不是15號，而是1號。原因很簡單啦。\n因為好記。一個月最初的一天。\n不過要說好記……比起今天，或許我們初次相遇那天的日期更好記一些？也更具有紀念意義。決定了，我這就去找人修改檔案上的生日。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003301] = {id = 11003301, name = "柯朗", head = "10033", type = 5, title = "關於修改生日這件事……", txt = "還記得去年的今天，我說過要修改檔案上的生日……\n那件事被人事部的管理員給拒絕了……說是一旦封檔，即使是駕駛員本人也沒有權限去修改檔案上的內容。\n真是讓人絕望，真是讓人看不到希望——\n不過，我也並非那種拘泥於形式的人，比起哪一天是生日，有生日可以慶祝就已經滿足我的要求了。\n好了，領航，你應該不會剝奪我人生中為數不多的希望之光——和你共度生日之夜的權利吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110034] = {id = 110034, name = "洛基", head = "10034", type = 5, title = "這只是約會", txt = "生日……為自己從羊水中離開的日子賦予特別的意義的人，和以慶祝聖誕節為由去享受私密時光的笨蛋情侶沒什麼區別。\n我並不想為這種尋常的日子大張旗鼓地慶祝……如果在別人的眼裡成了白癡，那我寧願選擇在無人的角落安靜去死。\n不過，這是我單方面為自己考慮的想法。如果我不慶祝生日的話，恐怕會被領航你當做是故意冷落了你吧。如果你會這樣想的話，我就頭疼了。為了不產生這種誤會，你就來我的房間一趟吧——\n對，我是在邀請你約會，明白了嗎，史蒂芬妮的養子。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003401] = {id = 11003401, name = "洛基", head = "10034", type = 5, title = "習慣不了的生日", txt = "興趣使然的事情一旦成為定期要做的例行事項，就會成為人生的負擔。\n在這件事上，我深有體會。\n一想到去年慶祝了生日，今年還要慶祝，而以後的每年都要慶祝下去，我就忍不住想要找一座寺廟，在裡面靜坐百年。\n不過，只是為自己每年的生日慶生都讓我倍感頭疼，我實在無法想象你把每個駕駛員都寫在日程表上的生活……\n好吧，就當是為了你，我也得好好面對自己的生日。\n那麼，請史蒂芬妮的養子光臨寒舍，和我共度今宵吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003402] = {id = 11003402, name = "洛基", head = "10034", type = 5, title = "又來了，生日", txt = "對同一件事抱怨第一次時，人們會認眞傾聽你的想法，當抱怨第二次時，人們會敷衍對待你的抱怨，但第三次抱怨時，人們只想對你敬而遠之。\n雖然我討厭無意義的社交常識，但並不代表我不懂這些道理。\n只要我還活著，生日就始終會到來，想要為我慶生的人，我希望為我慶生的人，都不會消失。\n所以，與其像一個受了氣的小孩一樣嘟囔抱怨，倒不如像其他我瞧不起的笨蛋一樣，去享受這一天。\n你覺得我說得對嗎，領航？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110035] = {id = 110035, name = "赫莉", head = "10035", type = 5, title = "不許爽約！", txt = "當你收到這份郵件的時候，想必你已經知道了——是的，今天是我的生日，是我加入艾吉斯後過的第一個生日！\n是的是的，我知道你肯定已經習慣給別人慶生了，也一定覺得“啊，區區赫莉的生日而已，也沒有什麼大不了的”，但是今天是我的生日，這件事對我很重要！\n我打算邀請的人……你，店長，還有那個擺臭臉的受刑人，還有星爍，還有……對了，還有我的隊友！\n你要是有想叫的人也一起叫過來吧，我準備了一個超大的蛋糕，還有好多牛排，不管多少人都夠的。\n不許爽約，接到郵件的時候就代表你同意來了！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003501] = {id = 11003501, name = "赫莉", head = "10035", type = 5, title = "原來如此，這就是幸福", txt = "當大家還是孩子的時候，肯定都想過這樣的問題吧——“幸福是什麼呢？”\n我當然也想過……想過“媽媽其實只是躲起來了”，想過“每週都買的彩票中了頭等獎”，要是這些事眞的發生了，那就一定是“幸福”吧。\n現在我已經是成熟的大人了……別笑！我都已經是萬中無一的駕駛員了！當然是“大人”！\n所以對“幸福”的理解就更加深刻了……換句話說，在生日的這一天領到工資，還有比這更幸福的事嗎？\n哼哼，今天我請客喫飯，你就在心裡好好感謝我吧！\n快點來，我還要聯繫洛基她們呢！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110037] = {id = 110037, name = "軫宿四", head = "10037", type = 5, title = "我的選擇", txt = "其實今天幷不是我的生日，其實我也不知道我的生日應該是哪一天。\n進孤兒院的日子？還是被老夫婦領養的那天？抑或是眞正出生的日期？全都不記得了，全被遺棄了。\n至於現在的“生日”，你可以猜猜為什麽我會選定在今天？\n你肯定在想，這一天一定是一个對我很有意義的日子，或許過去的某年今日發生了某些重要的又難忘的故事。\n實話告訴你吧，什麽都沒有發生過。往前倒數的數十个今天，什麽好的壞的重要的意外的興奮的刻苦銘心的痛哭流涕的事，都沒有過。\n但今天還是有著一定的特殊意義，這份意義在於是我選擇了“生日”而不是“生日”選擇了我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110038] = {id = 110038, name = "赫洛卡", head = "10038", type = 5, title = "你的回答", txt = "也是到這个時候了，我從其他駕駛員那邊聽説，多瑙支部有在生日這天給領航你寫信的傳統？\n挺奇怪的，但我尊重傳統。\n眞麻煩啊，不過和寫信比起來還是檢討書寫起來更令人討厭。我很好奇那麽多駕駛員的來信，領航看著不會累嗎？想想就知道，大部分信件的內容肯定是邀請領航參加生日派對什麽的。大家對領航可都是虎視眈眈呢，肯定不會放過生日這種好機會。\n我本身不在乎生日這天和誰一起度過，你也知道的，我一有空就會去釣魚，生日也不例外。不過我倒是比較好奇，如果我向你發出邀請，你會給予我什麽回答呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110039] = {id = 110039, name = "哈莉特", head = "10039", type = 5, title = "健身房生日折扣", txt = "喲，領航，有件好事說給你聽。\n今天去健身房續卡的時候，正好趕上店裏的活動——生日當天可以折扣辦理健身會員，並且可以用於親友或家屬。我一看，今天不正好我生日嗎！二話不說就幫領航你辦了一張會員卡，因為我想起來之前你就說過想要鍛煉肌肉。\n今後我們就可以一起鍛煉！放心，有我在，不出半年就能讓領航也擁有一身健壯的肌肉。\n我這就來給領航你送會員卡，領航你准備准備，我今天就帶你去鍛煉鍛煉肌肉，先做個十組深蹲和俯臥撐。\n在健身房慶祝生日，不覺得很有趣嗎！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003901] = {id = 11003901, name = "哈莉特", head = "10039", type = 5, title = "我必须雪耻!", txt = "哟，我又找过来了，领航。\n很奇怪啊……你不觉得各种角度上都太奇怪了吗，领航。\n我承认，我对于如何带一个人从头开始入门健身确实没有经验。让一个新人上来直接以十组为单位起练也可能太欠考虑了……\n但是，完全没产生效果算什么啊！就算只是安慰剂效应也该适当地出现一下吧！\n再给我一次……不对，三次机会吧，领航！我必须找出原因在哪才行。\n不然的话，明明出发点是想帮领航锻炼身体，结果却变成我单方面在趁生日霸占领航了，这不就没法形成等价交换了吗！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111000] = {id = 111000, name = "查麗莎", head = "11000", type = 5, title = "看內容", txt = "終於到生日這天了，真讓本小姐等得煎熬呢。\n哼，是不是開始誤會了？我當然不是指期待，而是希望早點翻過這一頁，畢竟從生日的前三天、前一周、前一個月開始，爸媽沉重的親情、身邊朋友的調侃就都鬧個不停，讓我早就對生日厭煩了。\n以往的每個生日我都不能做自己喜歡做的事，而是按照家人安排好的行程計劃，不是到哪家高級餐廳就是去選購豪車，可生日的意義難道不是壽星本人開心才好嗎？\n所以，今天我只想正常度過一天，我的生日願望就是這樣而已。這不是求助，但領航，我希望至少你能一如既往地陪著我，沒問題吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100001] = {id = 11100001, name = "查麗莎", head = "11000", type = 5, title = "我是從來不相信傳說的", txt = "領航，咳咳，你聽說過一個叫“荊棘拱門”的地方嗎？好像是以前一名被詛咒的煉金術師和村民相愛殉情的地方，據說只要去了那個地方，就會成為情侶……\n這肯定是騙人的，用來欺騙年輕男女的營銷陰謀。\n我從紅博士那買到了它的相關資料，你能陪我去打假嗎？\n對了——旅費能不能麻煩你先墊一下，等下個月的工資發的時候我會還給你的！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100002] = {id = 11100002, name = "查麗莎", head = "11000", type = 5, title = "今日陽光明媚", txt = "今天是什麽日子，領航沒有搞忘吧？要是敢搖頭，本小姐可要生氣了。\n至於想做什麽，難道要壽星給你安排嗎？千萬別提什麽工作，所有和本小姐無關的事都統統丢到一邊去！\n總之，這一天裏本小姐什麽都不想操心！不必服從家裏的行程，只是想自由自在地度過最開心的一天！\n雖然，平時好像就是這樣的，但……如果能和領航一起度過……\n正好、大蛋糕喫膩了，本小姐知道有家甜品店每天會有二人限定菜單……\n咳，都説到這份上了，還愣著干什麽？雖然平時想去喫也能去喫，但、但最美味的東西，最好和特殊的人在特殊的一天專門分享嘛！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111001] = {id = 111001, name = "愛麗絲", head = "11001", type = 5, title = "茶會邀請函", txt = "今年生日，家族決定讓我親自籌辦一次慶宴，以從多方面對我進行考驗。我當然深知，這是成為一家之主的必經之路，領導家族不僅需要掌握學識與劍藝，還當具備足夠的行動力、組織能力，以及不懼壓力的強韌心靈。\n而作為駕駛員小隊隊長，我相信這些能力亦可於作戰中大放光彩，所以直到不久前我都忙於此事，未能提前告知領航，我深感抱歉。\n在此，我正式向您發出邀請：愛麗絲·克雷蒂亞的慶生茶會將於今天舉行，持續整日，還請領航作為貴賓賞面光臨。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100101] = {id = 11100101, name = "愛麗絲", head = "11001", type = 5, title = "貴族的私教", txt = "“完美”的定義是什麼，您有想過嗎？\n這並不是一次質問或者提問，而是想和您探討這件事。\n我們好好地想一想吧，如果“完美”是指什麼都能做到，那麼“完美”便是人類窮盡一生也無法達成的事情。哪怕是我，也只能做到自己能做到的事情。\n可“完美”只是指在自己會做的事情上能做到盡善盡美，那若是進入自己不擅長的領域，那這脆弱的“完美”不就輕易被觸碎了嗎？\n關於這件事，我想好好和您探討一天，於是我打算在生日的這一天，聘請領航您擔任我的私教。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100102] = {id = 11100102, name = "愛麗絲", head = "11001", type = 5, title = "人生的預演", txt = "貴安，今日來信一共是為了兩件事。\n首先，第一件事是邀請領航您來參加我的生日晚宴。今年的生日恰逢克雷蒂亞家族建立250周年紀念日，所以舉辦得極其隆重，各界的名流人士將悉數到場。給領航您的邀請本來應該在幾個星期前就送到的，不過因為某個原因，我私自壓下，直到今天才鼓起勇氣告知您。而這個原因則和我要說的第二件事有關。\n我想要邀請領航您來參加我的生日晚宴，以我未婚夫的身份。\n果然，說出這句話還是感覺有些羞恥。當然這只是一場表演，為了給家族長輩交代，具體的情況等見面後再詳說。希望領航不要有負擔，就當是為我們的將來做預演。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111002] = {id = 111002, name = "心紙", head = "11002", type = 5, title = "拜帖", txt = "今乃神誕之日，乃救世天職降至此身之刻。將希望歸還人民，用信仰指引群眾，是老身存在於世的全部意義。\n遠年近歲，雖未曾並肩作戰，但您的諸多事蹟，老身已有所聽聞。您之於駕駛員，亦同“心紙”之於民眾，作為燈塔，為其驅散迷霧，護得一方和平。\n老身與心經屋的命運，或已成定數。然其餘駕駛員，乃至世界的未來……多瑙的領航，您將引領她們去往何處？老身拭目以待。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100201] = {id = 11100201, name = "心紙", head = "11002", type = 5, title = "想成為人類", txt = "近日來，參拜心經屋的信眾寥若晨星。即便是今日的“神誕之日”祭典，參加的信徒也只有寥寥數人。\n為找出其中緣由老身喬裝打扮，多方探尋。雖未找到直接原因，卻發現人們常討論原罪與駕駛員爭戰之事，甚至還多次聽到領航之名。人類的“希望之星”，此乃眾人給與領航的愛稱。\n至此老身方才了然。\n說來慚愧，領航僅憑人類之軀便為世人燃起希望的星星之火，與之相比老身只是徒有“神”之虛名。想來信仰之力或可於黑暗中保護希望的火種，卻無法將其燃成熊熊烈火。古往今來，成就非凡者從未是縹緲的“神明”而是活生生的人。\n老身……想與領航徹夜討論，關於神的事情，關於人的事情……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100202] = {id = 11100202, name = "心紙", head = "11002", type = 5, title = "就算是虛偽的生日", txt = "您在之前有提起過類似的話題吧……“神誕日與我曾經的生日是否存在聯繫”。\n我已經遵守約定，放棄了那些與自己過去有關的事物。因此無法回答這個問題，請您見諒。\n不過平心而論，那一天確實是我最容易感受到各種尋常喜悅的日子。\n為了祭典精心裝飾過的神社，忙忙碌碌的巫女們，齊聚一堂的信徒，許多人臉上安心的表情……想到這些事物能因我背負起的東西而存在，我就會有種異樣的充實感。\n另外……作為要主持祭典整整一天的回報，巫女們會給我畱下半個晚上的時間，讓我能隨意地在後山放松身心。\n如果您尙有空閑的話……我期待您的到來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111003] = {id = 111003, name = "鈴木清風", head = "11003", type = 5, title = "一起來做超大壽喜燒吧", txt = "領航，你應該知道了吧？\n沒錯，今天就是咱的生日！\n在咱的老家，村子裡的人過生日了都會邀請大家來吃飯、\n就算當了駕駛員，咱也不能忘了老家的習俗！\n咱已經想好了，咱要做一頓超大的壽喜燒，把所有駕駛員都叫來一起吃！\n怎麼樣，這個想法很好吧？既然如此，領航就趕緊過來幫咱一起做吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100301] = {id = 11100301, name = "鈴木清風", head = "11003", type = 5, title = "請假幾天", txt = "咱的生日要到了哦領航。\n咱已經請了幾天的假期，準備回家看看父親與妹妹。\n他們今年寄了很多照片和信件過來，照片上的他們看起來可開心了。\n嗯……仔細一想咱已經很久沒有回家了，不過咱覺得還好咱當上了駕駛員，哈哈……雖然在那個時候咱是出於無奈才加入的。\n結實了風林火山的大家們……也賺到錢……還遇到了領航。\n所以，領航今年有時間陪我一起回家嗎？我想差不多也應該向他們介紹你了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100302] = {id = 11100302, name = "鈴木清風", head = "11003", type = 5, title = "最難過的生日", txt = "三月份到了，咱的生日也到了。\n爲了今年的生日，咱本來是早早就做好了規劃的。\n咱原本準備乘坐遊輪進行个一周的郵輪遊。但是誰知道，遊輪必經的海域上，不知道什麽時候出現了一批魚群原罪！讓整片海域都被封鎖了。咱的遊輪遊計劃也被迫取消。\n爲了這次生日，咱可是從去年這个時候就開始做規劃，排日程表，攢錢。好不容易才在上个月攢够了預算。唔……原罪也太壞了！\n領航，咱能來找你嗎？咱現在心裏眞的眞的眞的好難過……想找你來談談心。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111004] = {id = 111004, name = "栗山青鸞", head = "11004", type = 5, title = "謝謝", txt = "今天真的太感謝領航了。多虧有您在，大家才沒有繼續用異樣的目光打量我……這奇怪的身體。\n記得剛才您有誇讚過我的砍價能力？如果不介意，下次外出採購也帶上我吧？\n啊，這麼說是不是顯得有些太自滿了？對不起……\n領航，最後請容許我再對您說一聲謝謝。\n謝謝您願意帶這樣的我出門，謝謝您在外人面前袒護我，謝謝您從未恐懼過我……還有，謝謝您今天陪我度過了一個堪稱完美的生日。我會永記於心的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100401] = {id = 11100401, name = "栗山青鸞", head = "11004", type = 5, title = "想變得時髦", txt = "領航，聽說最近新開了一家服裝店，專為特殊人士設計了許多款式新穎的服飾，我有些想去嘗試，想知道即使是這樣的我，是不是也有辦法變得時髦起來呢？\n但我卻一直拿不準主意，一方面是覺得自己可能沒必要學別人追求華麗，另一方面對自己的衣品也不太自信，不知道換上新衣服後領航是否會喜歡……所以，可以請領航給我點建議，或是在生日這天陪我一起逛逛這家店，挑選些適合我的衣服嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100402] = {id = 11100402, name = "栗山青鸞", head = "11004", type = 5, title = "今天，很高興", txt = "領航，我今天遇到件很高興的事。\n就在剛才我去蛋糕店取預訂的生日蛋糕的時候，有一個小孩子向我說了聲“生日快樂”。\n我很開心，因為她沒有被我奇怪的“眼睛”嚇到，而且孩子的母親，那位和藹的夫人也只是笑著看著我們，並沒有急切地把孩子護到身後。\n就好像我，在她們眼中是個……正常的人。\n可是我真的能被當做正常人看待嗎？或許她們只是表面上裝做不在意……對不起，腦子又泛起這些不好的想法了。明明她們在向我表達善意，我不應該妄加揣測。\n不說這些了，其實我寫信來是想問問領航您想要吃蛋糕嗎？我買的蛋糕太大了，我一個人恐怕吃不完。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100403] = {id = 11100403, name = "栗山青鸞", head = "11004", type = 5, title = "另一半的星空", txt = "又到了一年一次的生日這天。今年我攢了些勇氣，想邀請領航陪我去一個地方——市郊的天文館。\n您說我是不是有些貪心了，只用一隻眼睛就奢求星空全部的美，恐怕最後也只能收穫一半的星空。不過您曾告訴我，星星不會避開任何人，它們也不會避開我，就和領航您一樣。\n如果您願意陪我的話，我想聽您給我描述那另一半的星星，如此我便能在心中拼湊起一片完整的星空。\n偶爾我也會想，如果此後遇見的每一顆星星都能和領航一同銘記，那我的人生也足以稱得上幸福美滿。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111006] = {id = 111006, name = "燕妮", head = "11006", type = 5, title = "一個探幽獵奇的好日子", txt = "俺的生日終於到啰！\n生日禮物要什麼好比較呢？蛋糕吃完就沒，物品遲早會壞，所以顯然是要個能經久不衰的大新聞比較好啦！難得一年一度的日子，領航就陪俺出去，一起找遍多瑙的大街小巷，挖掘那些潛藏在陰影裏的秘密吧！\n嗯~當然啦，如果領航本身就攜帶著什麼諱莫如深的驚天異聞，趁著今天將它作為禮物向俺袒露也好。無論何等陰暗、何等罪惡的欲念，俺和俺的鏡頭都早已準備好接受了哦~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100601] = {id = 11100601, name = "燕妮", head = "11006", type = 5, title = "採訪預約", txt = "終於又到俺的生日了，領航你準備好接受採訪了嗎？\n不要驚訝，俺最想要的生日禮物就是與領航的一對一採訪環節。\n領航的身高、領航的體重、領航的愛好。喜歡穿的衣服、喜歡吃的美食、喜歡光顧的商店，喜歡在晚霞下漫步的那條街道……這裏一條條羅列出的問題，都是俺精心收集的“想要知道領航的1001件事”中人氣最高的幾條。\n不過請放心，作為俺的生日禮物，這次採訪的內容只會刊登在俺心裏的頭條上，這是俺要與領航共同守護的秘密。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100602] = {id = 11100602, name = "燕妮", head = "11006", type = 5, title = "實地取材！", txt = "總而言之又到俺的生日！\n看到這句話的領航肯定會想著“啊反正肯定又要以這個名義安排什麼麻煩的私人采訪或秘聞收集吧？”，然後露出像嘴裏含著檸檬一樣的表情了吧？\n相反！今年俺可是要過一個正常的生日的！\n你看，這是俺准備好久的《多瑙人都可以參考的重要日期出行安排》專欄，內容涵蓋從市內觀光路線到精選晚餐地點的多個方面，現在只要加上俺的實地體驗就大功告成了！領航你一定要幫俺哦！\n\n【以下為回複信息】“說了半天不還是記者工作嗎？”是啦是啦俺承認。\n“說來晚餐裏有好幾家都是去年采訪裏我常去的店。”——啊哈哈，巧合吧，巧合。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111007] = {id = 111007, name = "莉迪婭", head = "11007", type = 5, title = "今天是姐姐我的生日", txt = "嚴寒和太陽，真是多麼美好的日子！\n你還有微睡嗎，我的美麗的朋友——\n是時候啦，醒來吧…\n喜歡這首童謠嗎？每年的這個時候，我就會想起小時候母親唱著童謠叫我起床的日子。那代表著我的生日又到了。\n生日，多麼美好的日子，象徵著人們第一次與世界接觸的日子。\n我一直認為，嬰兒的啼哭不僅是對害怕之情的宣洩，更是向世界證明自己降臨的宣詞。而出生在冬天的孩子是最幸運的，他們不必對冬日抱有擔憂，只需對春天充滿嚮往。\n我就是這樣一個出生在冬天的幸運兒，既已能忍受嚴冬，那之後的每一天都將是溫暖的春。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100701] = {id = 11100701, name = "莉迪婭", head = "11007", type = 5, title = "新的一天已經開始了", txt = "從鐘錶的時針邁過12時，新的一天對我來說就已經開始了。\n隔壁的九州有一句古話：“一年之計在於春，一日之計在於晨。”雖然現在不是春天，也不算早上，但無疑是一天的開始。\n大姐姐想從自己生日的開始，便一直陪伴在自己在意的人身邊。\n所以，當你收到這封郵件時，請打開門。\n不出意外的話，會有一個白頭髮的大姐姐站在門口等你噢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100702] = {id = 11100702, name = "莉迪婭", head = "11007", type = 5, title = "節日預演", txt = "你有聽過送冬節嗎，領航？\n那是所有卡佳人都不會錯過的大節日哦。會有持續七天的大宴會、各種活動，還有比人臉還大的煎餅，姐姐每年的那段日子都忙得不得了呢！我一直想邀請你來一次。\n當然啦，這則消息不是送冬節的邀請函——畢竟它是在三月，離現在還有快一個冬天那麼遠呢。\n但再過幾天就是耶誕節了，為了能在迎接你時做好準備，我想用多瑙那邊最重要的節日作為參考。\n姐姐會把最拿手的幾種煎餅作為禮物帶過去的，要和你的親友一起做好準備哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111008] = {id = 111008, name = "艾希麗卡", head = "11008", type = 5, title = "地獄派對的邀請函", txt = "每年這個時候，我的耳邊總會響起一個聲音，仿佛是來自地獄的嘶吼。那吼聲撕碎了我的肉體，震散了我的靈魂，給我的音樂創作帶來無限的靈感。\n趁著靈感爆棚的時候，我創造了三首新的樂曲。每每在作完新曲之時，我就特別希望和他人分享我的創作。但是這邊方舟裏的人一聽到我的歌就全都嚇跑了，就連那些駕駛員也是。哈哈哈，都是些沒有膽量的懦夫罷了。\n思來想去也就領航算得上與我合拍，這次的新曲中也有一首是為領航而寫。所以我在此發出邀請，不知道領航有沒有膽量與我共赴黃泉呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100801] = {id = 11100801, name = "艾希麗卡", head = "11008", type = 5, title = "希望深淵", txt = "領航，最近我聽說了一個說法——“每過一次生日就意味著離死更近了一步。”\n這種說法真的是……可笑。難道不過生日人就不會死了嗎？難道就因為要死所以不再努力當下的生活了嗎？在我看來，這種想法只有真正的懦夫才會推崇，而強者就是要在死亡的恐懼下活出精彩的人生。\n我突然有了個靈感，我要寫一首關於生日、死亡和成長的曲子。我要成為“希望”的行刑官，用我的貝斯，我的音樂殺死這些懦夫心中的恐懼。我要讓她們墜入比死亡更深的，名為“希望”的深淵永世不得輪回。\n這就是我今年的生日願望。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100802] = {id = 11100802, name = "艾希麗卡", head = "11008", type = 5, title = "致新篇章", txt = "不是有個算是很多人常識的說法嗎，領航？\n“每到冬天，原罪的活動都會顯著性減少”這個說法。\n說實話，我完全不想知道這個規律是何時被總結出來的，對它背後的原因也沒興趣。\n只是，在我所熟知的領域裏，“相對平淡的旋律，是對後續爆發的鋪墊”，這才是更為大家所知的常識。\n我在這樣一個相對和平的時節降生，又最終背負上這樣的使命，這時刻在提醒著我，永遠不要忽視這兩者中的任何一邊。\n冬季已經邁入尾聲了。\n我會用一首嶄新的曲子，向明年所有襲向我們的災厄宣戰。\n你有興趣當第一個聽眾嗎，領航？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111009] = {id = 111009, name = "波琳娜", head = "11009", type = 5, title = "生日禮物", txt = "【以下內容為音訊轉錄】\n領航，祝你生日快樂！哦，是祝我生日快樂！今天是我的生日!是伊莉雅說的今天是波琳娜的生日。\n不過生日是什麼呢？波琳娜不知道，但是生日可以吃蛋糕！大蛋糕，波琳娜第一次吃這麼大的蛋糕。所以，想和領航一起吃。\n大家還送了我禮物，柯洛溫送的是小說，唔~波琳娜看不懂。克裡姆送的是酒？伊莉雅不許我喝酒。不過波琳娜本來就不喜歡喝酒，波琳娜喜歡果汁。伊莉雅送的是...啊，對了大蛋糕是伊莉雅送的！\n所以所以所以，領航什麼時候過來，波琳娜就在家裡，一定要來哦。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100901] = {id = 11100901, name = "波琳娜", head = "11009", type = 5, title = "波琳娜波琳娜波琳娜", txt = "波琳娜波琳娜波琳娜。\n波琳娜是波琳娜的名字！波琳娜喜歡自己的名字，波琳娜會寫字了哦！\n波琳娜不止會寫自己的名字，大家的名字波琳娜都會。\n克利木\n科羅文\n伊莉雅，是伊莉雅教的波琳娜寫字！\n還有領航！但是領航的名字是不是不是領航呀？\n對了還有就是……生日快樂！\n波琳娜的生日快樂，波琳娜希望領航也一起快樂！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100902] = {id = 11100902, name = "波琳娜", head = "11009", type = 5, title = "致波琳娜最喜欢的领航", txt = "领航，你一定想不到会收到波琳娜的信吧，信里面还有波琳娜的生日礼物，因为伊莉雅说领航的工作很忙，来不了生日派对，波琳娜想让领航也开心。\n生日一年只有一次，对吧。这么说已经过去一年的时间了。\n这一年里波琳娜可是学会了很多东西。波琳娜学会了一个人吃饭，学会把果酱抹面包上时不弄在桌子上。学会了看天气自己加衣服，不去踩结冰的路面。学会了认路，也学会了一个人变大然后出发打原罪。\n波琳娜还学会了看书，也认识了更多的字，虽然写得不好经常被伊莉雅说。不过波琳娜会继续努力，等到明年生日，波琳娜还要给领航写信。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100903] = {id = 11100903, name = "波琳娜", head = "11009", type = 5, title = "波琳娜的新一天", txt = "領航領航！這一年裏，波琳娜覺得自己比過去更加進步了。\n比如波琳娜會自己做飯，還能順便做一些讓大家喫了都點贊的小點心，而且……\n波琳娜又給領航寫信了！而且這次寫得很快，不像過去一樣要想好長時間。\n雖然大家總說波琳娜的字歪歪扭扭，但波琳娜覺得它們很可愛！\n畢竟每一個字裏都藏著波琳娜想對領航說的話呢。\n另外今年最驚喜的，是波琳娜今天又長大了一點點！雖然看不太出來……但波琳娜覺得視野變得更高了！\n雖然看起來波琳娜很在乎身高，但波琳娜眞正許下的願望，是希望領航每天也開開心心的。\n畢竟領航的快樂才是波琳娜的快樂嘛。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111010] = {id = 111010, name = "瓏", head = "11010", type = 5, title = "一起去拔胡蘿蔔嗎？", txt = " 那個那個那個那個那個那個......\n領航......那個......聽說瑪雅這邊的農業園裡的胡蘿蔔成熟了，他們正在舉辦收穫季的活動。只要是在當天生日的人，就可以免費領取一筐胡蘿蔔......\n但是我不知道埃塔人能不能參加這個活動......\n這幾天正好也是換毛的季節，渠都在忙著幫大家換毛的事，銀如往常一樣一直在訓練所，我一個人去的話又有點害怕......\n所以，領航能陪著我嗎？唔~到時候拿到的胡蘿蔔可以分領航一半。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101001] = {id = 11101001, name = "瓏", head = "11010", type = 5, title = "做個好夢/想睡你", txt = "領航，地球上的時間過得真快呢……一眨眼又到了生日這一天。\n過去的一年，對我來說似乎只有一天。早晨，從鋪滿棉花和稻草的床上醒來，簡單洗漱後出門，向遇到的銀隊長和渠前輩打招呼報到，然後一同整備巡邏，直到落日黃昏再一起返回，回到各自的住所休息。\n日復一日。\n我喜歡在床上鋪墊稻草，曬乾的稻草蓬鬆而溫暖，殘存的稻穀清香氣味格外令人安心，也更有家的感覺。\n領航喜歡在床上墊些什麼入睡呢？如果您最近有被失眠困惱，不妨……不妨……嗯……來瓏這裏，在稻香和瓏陪伴下，做個好夢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101002] = {id = 11101002, name = "瓏", head = "11010", type = 5, title = "還沒做好準備。", txt = "地球上……有和“埃塔星人”長得差不多的生物……就是小兔子們……\n好可愛的小兔子……瓏在來到地球的時候後就養了兩只小兔子……現在已經有好多好多小兔子了……這一點和“埃塔星人”完全不一樣呢……我們在組建家庭和生育孩子上的理念和……是和地球人一樣的……\n不會有控制不住自己繁衍欲望的時候……啊、啊！不好意思領航，一不小心就説了很多不相關的事情……\n其實我來找領航是説想説……今、今天是我的生日……不知不覺已經和領航相處這麽久了……所以……特地來邀請您……\n瓏已經準備好了……！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111011] = {id = 111011, name = "轟雷", head = "11011", type = 5, title = "非領航者若窺此信格殺勿論", txt = "書此密件實屬無奈，還請寬宥我的唐突。事出緊急，我開門見山吧：僅此一天，懇請領航借予閒暇時間，以助我照常恪盡職守。\n也許您已猜到，今天是我的生日，只是我從來沒有為這天慶祝的習慣，何況繁重的任務也不容我將時間浪費於消遣。但冥火她們卻多次以忍術暗中干擾我工作，說是非要讓我老實度一天假。\n忍心社的使命至關重要，豈能就此拋開不管？若領航能與我一起行動、佯裝幽會，她們窺見定會放心離開。這便是我的計謀。\n當然，此恩情轟雷必將報答，待交易處理完畢，無論何種要求您只管提出，我一定傾力相助。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101101] = {id = 11101101, name = "轟雷", head = "11011", type = 5, title = "密信領航閱後請速速焚毀不留痕跡", txt = "不知領航是否還記得今日是我生日一事？如若忘記倒也無妨，實不相瞞，我此番是有事求於領航。\n事情說起來也簡單，近來總部突然傳聞有人正在計劃對您進行某種不可告人的行為，牽扯到心經屋的某位駕駛員，忍心社正在調查此事。我想近距離接觸那位駕駛員，但又不想暴露忍心社……或者說我的身份。\n假如領航能提供一下幫助，找個藉口與那位同僚見面，屆時我偽裝身份跟隨，即可與其近距離接觸。這便是我的計劃。\n至於這個偽裝的身份……青梅、戀人又或者是妻子……領航更喜歡哪一個呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101102] = {id = 11101102, name = "轟雷", head = "11011", type = 5, title = "涉及機密任務請領航閱讀後即可焚毀切記不可說給第三人", txt = "忍心社的使命，以及忍心社存在的意義，就是為了維護艾吉斯這面盾牌不被奸人歹人惡人沾污。\n為此即使粉身碎骨也在所不惜——明明是這樣的。\n但是，史蒂芬妮卻說，從今天開始的五天裡都不許我執行任務。\n這……這是什麼荒謬的命令？\n我在床上翻來覆去思考了四小時三十二分鐘二十一秒，想到了一個答案。\n也許，這是某個暗語，史蒂芬妮博士是在下達某個不能言說的機密任務。\n為了尋找答案，我只好向最了解史蒂芬妮博士的您尋求幫助了。\n接下來的五天，我們一起解開真相吧，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101103] = {id = 11101103, name = "轟雷", head = "11011", type = 5, title = "此為並不機密的私人申請，但還請務必不要外傳", txt = "敬啟領航：\n又到了每年的這個日子……對於去年因我太過多疑，而導致您也一起在無意義的捕風捉影中浪費了數日時間一事，請允許我表達誠摯的歉意。\n為避免重蹈覆轍，今年我在安排好忍心社之後的工作，且專門確認了史蒂芬妮的命令並無深意之後，正嘗試在幾小時內度過一個符合普通人標准的生日。\n然而，雖然對偽裝成其他人一事得心應手，但不知為何，我卻怎麼都無法在“扮演自己”的過程中靜下心來。\n無奈之下，我第一時間想到的便是求助於領航。\n畢竟，要說誰比較了解那個“工作之外”的我，除您以外，應該並無他人。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111012] = {id = 111012, name = "阿爾法", head = "11012", type = 5, title = "阿爾法的生日", txt = "生日……數據庫裡說，“生日”是人類誕生的日子……是人類為了紀念自己出生而設立的節日……\n阿爾法，不是人類，也能有自己的生日嗎？\n阿爾法不明白……但是慶祝生日的話，大家就會高興吧？\n阿爾法希望領航能享受阿爾法的生日，這樣一來，阿爾法的生日就有了意義。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101201] = {id = 11101201, name = "阿爾法", head = "11012", type = 5, title = "……享受生日？", txt = "致尊敬的領航：\n最近，阿爾法的數據庫一直在分析您去年說過的話。\n“別把生日當做他人的附屬品，要認眞尋找慶祝它的方法”\n……很慚愧，阿爾法仍然不明白。\n阿爾法，是基於新的使命而被重啟，同時有義務償還過去罪孼的機體。\n探尋和慶祝，都是容易摻入主觀判斷的行為，阿爾法擔心?!q2L$pX9@kM!sT5%fG7，這很可能hB3*vZ1^nR8#d——\n……實在抱歉，推演過程似乎又誘發了額外的錯誤。\n阿爾法……不想迎來一個與應有的效果完全相悖的生日。阿爾法需要您的幫助，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111014] = {id = 111014, name = "斯卡蒂", head = "11014", type = 5, title = "隱秘於暗影中的女王之盛宴", txt = "歡呼吧！今乃吾之誕辰，亦是影之國的傳統佳節！而汝，受吾垂青之人，有資格踏足影之國的國土，與吾之子民共同慶賀，享受這一年僅有一次的女王之盛宴！\n若孤身途經光影交接之處，汝等靈魂將會在時空夾縫中迷失。然無須擔心！此信物承載著吾的祝福，可護汝——\n\n\n領航！你快管管莉莉絲，她今年又來打擾我給你們寫生日邀請卡片了！還說我用詞有問題，語法也錯了不少……\n哼，她懂什麼？我明明寫得超棒的！！！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101401] = {id = 11101401, name = "斯卡蒂", head = "11014", type = 5, title = "吾將熠熠生輝", txt = "影之國緊急聯絡事項\n好久不見了，領航，吾結束了第六天之界的戰鬥，得勝歸來。\n此次第六天之界在吾等影之國的干涉下變得和平，吾等月冕成功為不斷褪下遺脫的永劫之喵咪進行了聖體的滌淨化。\n這不禁讓吾想起了與汝並肩作戰的那些日子。\n期待與汝的再一次見面，在影之國女王的神誕之日，請務必賞臉。\n\n\n附件\n啊——哈——哈，怎麼樣！領航！是不是被吾端莊而又正式的行文震懾了心神。嚇了一跳對吧！但是這還不是吾的極限——生日會上的吾一定會更加！更加熠熠生輝的！吾已經準備好了，所以一定要來哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101402] = {id = 11101402, name = "斯卡蒂", head = "11014", type = 5, title = "史上最為盛大的王之慶典", txt = "歡呼吧！今乃吾之誕辰，亦是影之國的傳統佳節！而汝，受吾垂靑之人，有資格踏足影之國的國土，與吾之子民共同慶賀，享受這一年僅有一次的女王之盛宴！！！\n哼哼，是不是覺得眼熟？沒錯！這正是身為影之國女王的吾，又一次向汝發來的邀請函！\n在與夏日的雙面惡魔莉莉絲結束了“半日戰爭”後，吾決定要舉辦一個讓世界，不，是讓宇宙都為之變色的盛大慶典，用來慶祝女王的誕日與勝利。\n而汝，身為吾的靈魂契約的契約者，汝理應成為第一位受邀之人。\n快來吧，吾將於王座上等候汝的到來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111015] = {id = 111015, name = "鈴", head = "11015", type = 5, title = "來自天才的生日問候", txt = "領航，你好嗎？\n今天是鈴的生日，是一百年只有一百次的生日！\n話說你知道嗎？最近我們這邊有一件事很流行，據說每個駕駛員在生日的時候都會給她們的領航寫信並附送禮物。\n這不是很奇怪嗎？\n明明是自己的生日為什麼要給別人送禮物呢？\n這裏面肯定藏著什麼秘密，本天才一定會找出來。\n所以天才我呀，就趁著今天生日給你送這些禮物。\n本天才倒要看看這麼做到底會發生什麼好事！\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101501] = {id = 11101501, name = "鈴", head = "11015", type = 5, title = "最特別的日子", txt = "今天是大天才鈴的生日。\n今天是母親的忌日。\n今天是我和第二位母親相遇的日子。\n對於我來說，今天是十分特別的日子，是一個可以歡笑，可以落淚，可以自由自在做自己想做事情的日子。\n我會珍惜這特別的一天，用一百倍的心意去過好這一天的。\n領航，你能和我回一趟故鄉嗎，我和想我的第一位母親聊聊你的事。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101502] = {id = 11101502, name = "鈴", head = "11015", type = 5, title = "她們偷偷摸摸的！", txt = "你好，領航！我最近發現了一個大秘密！\n嘿嘿……大家正在瞞著本天才為我偷偷準備生日派對！大家以為能瞞過本天才的眼睛嗎！我可是要成為英雄的人！\n但、但是我也只能通過大家最近對我的態度感覺到“有那麼一股氛圍”在。嗯……都準備了什麼東西呢……好期待啊……好想去問問她們啊……不行不行！要裝作不知道的樣子！不然就辜負了她們的好意了……\n領航今天可以和我一起過生日嗎！我們就裝作什麼都不知道，一起去聚會的現場吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111016] = {id = 111016, name = "黑羽", head = "11016", type = 5, title = "請領航賜教", txt = "方才收到忍心社成員們的短信，我才想起今天是自己的生日。在信中，“另一個冥火”表示生日是個值得慶祝的重要日子，應該和信賴親密的人一起度過。可…倘若此言正確，那麼自從擔任您的護衛起，我豈不是每天都在過生日嗎？\n記憶中，在我歲數尚小、作為下一代“黑羽”而被族人培養的那段年月，我並未因所謂的生日而得到長輩嘉獎，如今自然也不知該怎樣慶祝。\n但既然守在您的身邊就是正確之舉，那麼，我認為也許不需要採取額外行動，今天只要和往常一樣就好。\n當然…對於如何度過生日一事，領航若有更為合適的想法還請賜教，我一切都悉聽尊便。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101601] = {id = 11101601, name = "黑羽", head = "11016", type = 5, title = "守護之道就在其中。", txt = "“黑羽”一族是守護的忍者，我們貫徹著自己的信念在世間行走，直到找到值得效忠的主公。\n據說歷來冠以“黑羽”之名的忍者，都是在找到了自己真正想守護的事物之後才懂得了感情為何物。\n我想我的家人一定是異類中的異類，我能切實的感受到，他們把我當作“人”來培養，我也回應了他們，在角逐中贏下了“黑羽”之名。\n但即使如此我也沒有和他們一起度過生日。\n所以我想借這次機會回去見一見我的家人。\n我也想和家人們好好介紹作為我主公的您。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101602] = {id = 11101602, name = "黑羽", head = "11016", type = 5, title = "您在想些什麼呢？", txt = "奇怪，您想要什麼呢？\n在打掃完您房間裏的每個角落，確保床底、衣櫃裏沒有藏著諸如巫女、未來視的超能力者之類的可疑人物後，我在您房間裏找到了一個寫著“黑羽”二字的木匣。\n作為侍奉您的忍者，我不該覬覦您的秘密，也不該對您的行為有所疑問。\n但看到它時，我便想起了今天是我的生日。\n難道說——不，我想只有這種可能了吧，這一定是您為我準備的生日禮物吧？\n您為我準備了怎樣的禮物，我會心懷期待地等待您揭曉答案的那一刻。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111017] = {id = 111017, name = "芙蘿拉", head = "11017", type = 5, title = "四月陣雨催生五月芬芳", txt = "近來氣候有變，春雨頻降，空氣也潮濕了許多，不知領航的身體是否安好。\n城中草木無不沾染露水，葉梢被壓得一天比一天彎，猶如繃緊的弓弦，似乎正蓄勢待發。你知道，多瑙古時便有句諺語：四月陣雨催生五月芬芳。當雨季結束以後，相信空氣中會彌漫著更加沁人心脾的芳香吧。\n我的生日總是與這種時節重合，幸而于方舟內散步不用顧及天氣。領航若也有這般興致，歡迎與我一起欣賞雨中多瑙，待散步累了，就坐在窗旁一邊聽雨，一邊享用上好的玫瑰花茶吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101701] = {id = 11101701, name = "芙蘿拉", head = "11017", type = 5, title = "一同品茶嗎？", txt = "百忙之中的打擾，不知領航近來可好。\n幾日的降雨仿佛是在提醒我生日又到了。今年不知怎的，在生日這天特別想見你一面。\n最近有收到一份從九州發來的貨物，我在裏面翻找到一包茶葉，好像是九州的特產。這茶葉嫩綠隱翠，香氣襲人，與多瑙的茶葉大有不同。想來這多瑙的方舟上或許只有領航你最懂九州的茶文化，不會糟蹋這難得的珍品。\n若今日無事，能否請領航來我的住處，我們一同品茶，順便我也想聽你講講這方舟之外的人和事。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101702] = {id = 11101702, name = "芙蘿拉", head = "11017", type = 5, title = "四月结束之前", txt = "首先，请允许我先说一声抱歉，每年的这个时候都来打扰领航。虽说本意是与您分享生日的喜悦，但还是过于任性了。\n感谢领航如此宽容我的任性，以至于我的内心升起了更加逾矩的想法。\n我想与领航一同在雨中散步。\n想象我们二人躲在同一把伞下，手臂挽着手臂，小心翼翼地跨过每一个小水塘，在石子路上缓慢地前行。聆听雨水滴落在不同的表面，击打出高低错落的鼓点……\n如若路有尽头，也请允许我倚靠您的胸膛片刻，在四月结束之前，将您的心跳铭记在心。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101703] = {id = 11101703, name = "芙蘿拉", head = "11017", type = 5, title = "懂得美的人", txt = "倘若將這個世界的人劃分爲兩類，一類是懂得欣賞美的人，另一類則是不懂得欣賞美的人。\n領航您是哪一類人呢？我想您必定是前者，是一位懂得欣賞美的人。\n您目光所及的風景，親身丈量的土地，肯定比我這個方舟衛戍要多得多。那海面上跳躍的浪花，山林間嬉戲的清風，不知與方舟上所見的晚霞和星空相比，哪一個更爲美麗。\n 假如在生日這天許下的願望真的能夠實現，我希望能與領航一同去欣賞方舟之外，更多的美景。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111018] = {id = 111018, name = "銀", head = "11018", type = 5, title = "月亮和蘋果派", txt = "其實生日對我們埃塔星人來說是非常重要的日子，畢竟以我們星球的時間跨度來看，兩次生日間隔差不多是地球的好幾年。不過既然現在我們暫居於地球的話，那就入鄉隨俗改為地球的一年一次好了。\n當然慶祝的方式也得跟著改變，像在埃塔時那樣連續幾天的大餐會就不能舉辦了。渠告訴我，地球人的習慣是在生日時和親近的人一起享受美食並討論未來的事。\n早上的新聞報導裡說，今晚有百年難見的超級月亮。我已經準備好了蘋果派，不知道領航晚上有沒有空，我們一起商討下討伐月亮上的原罪如何。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101801] = {id = 11101801, name = "銀", head = "11018", type = 5, title = "新的倒計時", txt = "又到了要慶祝生日的時候了，我現在有些後悔將生日與地球的公轉週期同步，這段間隔太短了些，對我來說尤其如此。\n我覺得生日快成了一種負擔，它就像爆炸物上的倒計時，以天為單位，催促著我要在新的365天中學習、鍛煉、變強。然後在倒計時歸零時，回頭審視自己，做下剪斷紅線還是藍線的決定。\n當然無論我做出什麼選擇，倒計時都不會停止。它會回到365的刻度上，有時也會是366，然後在下一個生日等著我。最重要的是……年齡也……\n不過生日還是有很多值得期待之處，比如蘋果派，比如能給領航你寫信。\n如果可以，我想當面和你……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101802] = {id = 11101802, name = "銀", head = "11018", type = 5, title = "即便，只是稍有適應", txt = "三年……就算按照埃塔的標准，一年的大部分時間也已經過去了。我也差不多該適應地球年帶來的文化差異了……\n畢竟，地球人的生活擠滿了比時間更值得操心的事。\n不會經過預分配的社會身份，各種重要卻只能分開處理的事務，還有，一樣的原罪。\n無論活了多久的人，在因為原罪喪命時都是一樣的。從這點上講，自然壽命確實是個最不貼合生活的煩惱。\n既然這樣，把生日當成稍微特別的休息，烤好蘋果派，叫上在這天想見的人……雖然和傳統相差甚遠，但想象一下，感覺也會是不錯的一天。\n我准備從今年開始實踐……領航，你能來看看我有沒有什麼疏漏嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111019] = {id = 111019, name = "天天", head = "11019", type = 5, title = "肉醬蛋糕研製大成功！", txt = "領航！領航！領航！我成功了！\n我做了一個超級大蛋糕！雖然很早之前我做過蛋糕，但是這次的做法不一樣。這次的蛋糕原料只有肉！\n用九州牛肉作為蛋糕坯，塗上肉醬做成的奶油,最後把雞肉裱花裝飾在蛋糕上，全部放進烤箱烘烤。雖然出來的成品樣子不太符合“美食”的定義，但是聞起來和吃起來的味道超級棒！\n如果要說有什麼缺點的話，那就是一不小心做得太大了，根本吃不完。所以領航如果還沒吃飯的話，我這裏給領航留了位子，隨時恭候領航光臨。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101901] = {id = 11101901, name = "天天", head = "11019", type = 5, title = "踏上尋找傳說之廚具之旅之前", txt = "領航知道傳說之廚具嗎？那是據說可以將食材變得美味的神奇廚具。\n悄悄告訴領航一個秘密——我已經找到傳說之廚具了。準確來說是找到了傳說之廚具的線索。\n沒有廚師能夠抵抗傳說之廚具的誘惑，我也已經決定獨自踏上尋找傳說之廚具之旅。不會太久，最多三天時間。\n但在踏上尋找傳說之廚具之旅之前，有件事必須拜託領航。為了不讓安安和班長擔心，我沒有告訴她們真相而是謊稱到領航您家過生日了，要是她們問起請領航一定要給我打掩護，拜託拜託。\n回頭我再用傳說之廚具製作的料理向您表示感謝，也會把欠的生日聚會補上，拜託你啦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101902] = {id = 11101902, name = "天天", head = "11019", type = 5, title = "聚餐邀請！", txt = "領航，出大事了！超級大的事！\n爸爸媽媽上周聯繫我說，他們把餐廳開到離撒哈拉方舟很近的地方了！真的超級近，我昨天結束訓練後都從方舟上遠遠望到他們的招牌了！\n去年生日時我光顧著自己胡鬧了（而且最後還是被班長訓了）。今年有這麼好的機會，我一定要請平時照顧我的大家好好吃一頓才行！安安和班長她們都會來，到時候一定會很熱鬧的！\n我會和爸爸媽媽一起準備一個超棒的秘密菜單，一定要來哦，領航！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101903] = {id = 11101903, name = "天天", head = "11019", type = 5, title = "料理對決！", txt = "我發現一件不得了的事，領航！卡蓮班長她們前幾天開始好像就在偷偷策劃著什麼！\n我對此進行了好幾次秘密調查，發現她們還聯系上了爸爸媽媽，似乎是想聯合起來偷偷給我准備一頓生日大餐！\n——真是氣死我了！雖然知道班長她們肯定是想著“這種日子讓我好好享受”什麼的，但策劃這種活動不帶上我就是不行！\n所以，我們來組隊和她們對決吧，領航！\n憑借我長期積累的經驗，和領航你的料理天份，雖然只有兩個人，但我們一定能做出毫不遜色於她們的東西！\n對於在熱鬧的節慶籌備裏把我摘出去這種大錯，必須讓班長她們記住教訓才行！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111020] = {id = 111020, name = "卡洛琳", head = "11020", type = 5, title = "提醒？求助！", txt = "我知道，領航您也忘了，所以我又又又發來了消息！\n首先，今天是我的生日。\n其次，我特地買了個足夠大家分著吃的五層大蛋糕回來。\n最後，從十天前起，我每天都給你們發消息，讓你們千萬、一定、絕對不要忘了今早在休息室集合，一起吃蛋糕。\n但……但是到現在都沒有一個人來！為什麼啊？！\n剛才試著給隊長她們發消息，到現在都還是未讀狀態……領航，我只能指望你了。快幫幫我。這冰淇淩蛋糕化得滿桌都是，還有不少流到了地上，我、我現在該怎麼辦啊？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102001] = {id = 11102001, name = "卡洛琳", head = "11020", type = 5, title = "不普通的生日", txt = "既然隊長她們總是忘記我的生日，並且連消息也不回，今年就決定只有你、我，我們兩個人一起過吧！\n至於怎麼過，那自然是遊樂園、水族館、電影院一整套流程？不行，果然還是太普通了吧……可只要是向公眾開放的地方，無論哪裡也都會顯得很普通的，沒有例外。除非，能找到不向公眾開放的地點。對了，比如說領航你的家裡！\n那麼，到時候就先在外面玩一整天，玩累之後，行程的最後一站就定在領航家裡吧？嗯嗯，就這麼決定了哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102002] = {id = 11102002, name = "卡洛琳", head = "11020", type = 5, title = "請讓我的生日變得有趣起來吧！", txt = "Bonjour！領航。\n您或許還記得吧，今天是我的生日這件事。\n想想之前的生日過得都太普通，也太無趣了。看電影、逛水族館、吃蛋糕……都是些和大家一樣的，普普通通的慶祝方式。\n我並不介意普通，我自己本身也已經足夠普通了，但至少生日這天，我還是想要變得有趣一些。\n而能讓生日變得有趣的方法……我不知道。普通如我實在無法想像什麼樣的慶祝方式如何才能稱得上有趣。想破了頭也想不到，到頭來能請教的只有領航您了！每天生活充實而有趣的您一定知道更有趣的慶祝生日的辦法吧。\n拜託了，領航，求求您讓我的生日變得有趣起來吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102003] = {id = 11102003, name = "卡洛琳", head = "11020", type = 5, title = "來看我的獨家舞臺！", txt = "Salut！\n又到了這個熟悉的日子啦！難得的生日，我還是想搞一點特別的形式。\n而且，一定要和帶給我無數驚喜的領航，一起享受這場的盛宴——\n所以今晚我特意準備了一個超級厲害的壓軸節目。\n現在，請領航推開窗。\n看見那邊已經準備就緒的劇場了嗎？我可是給你留了特等席呢！\n哎呀，其實也沒有破費啦，畢竟這麼簡陋。\n何況我本就不是什麼配得上大舞臺的閃耀英雄啦。\n但至少……至少在今天，只要我最在乎的人的目光，正一眨不眨地注視着我，哪怕是像我這樣普通的少女，也算是綻放過最獨一無二的光了吧？\n如此一來，我就是全世界最幸福的壽星了！嘿嘿！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111023] = {id = 111023, name = "曉夢", head = "11023", type = 5, title = "來命令曉夢吧！", txt = "澄練說，生日當天，壽星必須要向所有為她慶生的人說出請求，這是多瑙的習俗。曉夢有入鄉隨俗，但請求被駁回了。\n“希望今天一整天都能被大家命令著去做任何事情”而已，很簡單，為什麼沒有一個人願意？就連吉雅也拒絕了曉夢……曉夢以前從來沒見她拒絕過其他人的生日請求，是被討厭了麼……\n不過曉夢知道，閣下不討厭曉夢。\n所以閣下絕對不會拒絕曉夢的請求，對吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102301] = {id = 11102301, name = "曉夢", head = "11023", type = 5, title = "一年只有一次的思考時間！", txt = "因為曉夢“不想思考，只想被命令著去做某件事情”，所以在平時大家為了讓曉夢開心，絞盡腦汁地想了很多種方式來滿足曉夢的願望。\n所以曉夢在想，偶爾也要自己好好地思考一下，接下來應該做什麼，有什麼是曉夢應該為大家做的，能讓大家開心的事情。\n但是曉夢不擅長這些東西，所以想請求閣下和曉夢一起想想。\n曉夢是一年只動一次腦子的笨蛋，而閣下是每天都在思考的聰明人，我們兩個人一定能想出讓大家開心的辦法。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102302] = {id = 11102302, name = "曉夢", head = "11023", type = 5, title = "生日願望要是多幾個就好了！", txt = "希望閣下能多一點的休息時間……這樣就能有更多的時候陪我了。\n也希望隊長有很多的休息時間、嗯……還有韶音和澄練……她們也要休息才對。\n但是我的生日願望只能許一個……那就先讓閣下多一點休息時間吧，過完生日的我會努力去實現這個願望的，嘿嘿，這樣就有很多很多時間被閣下和大家命令了。\n曉夢會創造讓曉夢開心的世界！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111024] = {id = 111024, name = "妍妍蘿", head = "11024", type = 5, title = "一個小提醒", txt = "怕你忘記了，特地通知一下，今天是我的生日。\n生日禮物什麼的就不必準備了，我不是很需要。\n但你要是想陪我去海邊進行潛水活動的話，我倒是非常樂意。近期熱門的潛水點有三個，一個是多瑙近海附近的大陸架，一個是廢棄海上油井，還有一個在北冰洋底下的潛艇遺跡。\n我比較推薦潛艇遺跡，因為鮮有人至，沒有多少攻略，更有冒險的感覺。\n唯一問題是那邊海水比較冷，到時候就不得不依靠你的體溫給我取暖咯。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102401] = {id = 11102401, name = "妍妍蘿", head = "11024", type = 5, title = "有關儀式感", txt = "你會在乎過生日的儀式感嗎，領航？\n早上啊，我正整理這次生日要去哪幾個地方潛水呢。結果默默突然說“平時是潛水，生日也是挑地方潛水，那生日和平時不就沒區別了嗎？”，搞得我一下有些在意起來了。\n雖然我確實喜歡潛水啦，但如果一個人一直都在旅行的話，可能也會逐漸覺得旅行沒什麼大不了的吧？爸爸媽媽好像也有跟我說過類似的話，要更珍惜自己喜歡的東西啥的。\n——所以我決定讓生日更有儀式感一些，具體你可以看彈到你終端上的那個信息。\n之前他們都不肯特批我節假日去巨大化潛水，但了解這背後的人生思考的領航一定會認可我的，對吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111027] = {id = 111027, name = "今七實", head = "11027", type = 5, title = "你還真是……讓人意想不到……", txt = "史蒂芬妮聯繫了我，說是她寶貴的養子正在找我，說是要為我慶祝生日……\n哈哈哈——領航小弟，你還真是讓我捉摸不透啊，給罪犯過生日……我還是第一次見。\n難道說，其他幾個和你有過接觸的受刑人，你也給她們慶生了？\n真是……有點搞不清小弟你在想什麼了，是籠絡人心嗎？還是說，“只要是我觸手可及的範圍，我就要為她慶祝生日”？\n算了，偶爾見到像你這種思想純粹得有些另類的人，也算是豐富人生了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102701] = {id = 11102701, name = "今七實", head = "11027", type = 5, title = "生日限定哦~", txt = "你知道嗎，領航小弟？\n在我認識的所有人裏，你是少數有閒心幫我過生日，並且第二年的同個時候還能繼續冒出來的人。\n尤其是在我倆的個性簡直談得上水火不容的情況下，像你這麼奇怪的人可真少見。\n這對你來說到底算什麼呢？史蒂芬妮的命令？對我的某種好奇心？還是說，真就像你去年說的那樣“因為正好記得，所以就去做了”？\n在有關別人的問題上耗太多心思可不是我的習慣，所以我決定乾脆點接受它。\n讓我繼續看看你想做什麼吧，這樣，我說不定也能摸索出和你更妥當的相處方式。\n這可是我一年說不定只有一次的坦率，你不會讓女孩子久等吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111028] = {id = 111028, name = "潔蘿", head = "11028", type = 5, title = "做你該做的事情", txt = "身為領航，比起給另一支部的駕駛員慶祝生日，你的時間、精力以及生命應該花費在更有意義的事情上吧？維繫所謂的朋友圈，與思索抵制原罪的有效方法，孰輕孰重，你不會不懂。還是說，你覺得如果不這麼做、不借助物質手段收買我，我就不會在作戰中聽你指揮？\n哼，看來我真的是被小瞧了。\n再強調一遍，我是卡佳最強的駕駛員。只要你的指揮合理、有用，我都會無條件聽從。至於這種小聰明……今年的禮物我就收下了，下不為例。\n——領航，請不要讓未來的我覺得，如今認可了你的自己是個白癡。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102801] = {id = 11102801, name = "潔蘿", head = "11028", type = 5, title = "想要的生日禮物", txt = "最近在整理房間的時候，不小心把一些家具弄壞了……不是我的錯，是它們太脆弱了。\n雖然我很少在家裡待，但是如果沒有那些家具的話，也會遇到麻煩的情況\n比方說衣櫃……我現在只能把衣服放在床上，睡覺的時候很不舒服。\n總之，我現在需要一套新的家具，你來陪我挑吧。\n就當做是給我挑生日禮物了！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102802] = {id = 11102802, name = "潔蘿", head = "11028", type = 5, title = "嚴正抗議", txt = "事先聲明，我完全明白你之前跟我提的那些主張。\n“該休息的時候好好休息”“即便是最強的駕駛員，也要保持一些貼近常人的習慣”，我已經和你交流過這背後的意義，並且，應該也展現過充分的配合態度。\n但今年的安排不在此列。\n為什麼蛋糕的預算又增加了？為什麼生日派對要持續整整三小時？為什麼莉法小姐在沒有預先通知的情況下“貼心”地調整了我原本的訓練時間？\n甚至連亞爾薇特隊長都同意了這些申請，簡直不可理喩。\n總之，我要駁回這些安排。\n至於下午的購物，盡快解決的話，和晚上的派對還能畱出足夠的緩沖區間，希望你也能抓緊一點。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111029] = {id = 111029, name = "千陌", head = "11029", type = 5, title = "此般叨擾甚是抱愧", txt = "尊敬的領航先生：\n今唐突叨擾，實則有一事相求……\n難得生日，我本想與天天、安安拉近關係——先生應當知道，她們是受卡蓮邀請才加入小隊的，而我平日忙於學院裏各種要事，少有關照過她們——可不知為何，今日幾次邀請，都被二人用各種理由搪塞、拒絕。\n詢問卡蓮，也只是得到一句：“雖然答應了她們保密……別擔心，是驚喜哦。”\n意味不明。\n想起天天、安安與卡蓮對先生百般信賴，我猜想她們或許近期與您談及過我的事，故只好出此下策，寫信向您討教一番。若先生知曉內情，還請務必提點一二。\n在此靜候先生回信。\n\n千陌敬上", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102901] = {id = 11102901, name = "千陌", head = "11029", type = 5, title = "一年過去，仍是叨擾", txt = "領航先生，我有一事相求……\n是的，去年的這個時候，我也是用這種方式開場的，但這絕非是興趣使然的對稱，又或者是絞盡腦汁後的詞窮，只是本意如此。\n最近，我開始重新思考起自己的管理方式是否適合這個時代——\n用“這個時代”這種詞語或許誇張了，但無論如何我也想弄清楚，在學生時代積累的經驗，那些用來規範人們行為的規矩，在我離開學校後，是否還能同樣適用於現役駕駛員身上。\n僅以一介學生的身份思考這事可能為時過早，又會顯得不知天高地厚，但我認為現在開始思考起來也未必是件壞事。\n於是，我想借生日一事，向領航先生提出請求——請教導我吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102902] = {id = 11102902, name = "千陌", head = "11029", type = 5, title = "不能被時代拋棄", txt = "領航先生，我有一事相求。\n抱歉，請允許我又再一次使用了這個開場。\n第一次是無意的，第二次是理所應當的，而第三次，用符合“這個時代”的說法，就是留下讓人印象深刻的口頭禪吧……如果這個開頭能在學校流行起來的話，我會很高興的。\n………………抱歉，有些失態了……果然，我說這種話還是太輕浮了吧？\n我知道天天的建議是為我好，但我的確——不太能適應這代年輕人的說話方式。\n可如果這種輕浮的口吻是最適合與同齡人打交道的，那麼身為蒼穹學院的學生會長，我就必要去學習它……\n所以，領航，您能協助我掌握“年輕人的說話方式”嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111030] = {id = 111030, name = "澄練", head = "11030", type = 5, title = "此般叨擾甚是抱愧", txt = "11月2日，晴\n又到生日這天了。\n翻閱了一下前幾年的生日日記，就像是在閱讀我自己的歷史。回想起那些陳年往事有些尷尬。\n但作為“史官”的我絕對會按照事實來記錄，即使是自己的事。而我現在最真實的想法是——好想領航來陪我一起過生日啊！\n不過這話只能在日記中說說，要是當面說出來……我在領航心中沉穩的史官形象就崩塌了啊，想想就好害羞……\n今天開始我要用電子書來記錄日記，之前紙質的日記本太不安全了，全都給別人看光了。不過我還沒完全弄明白電子書的操作，比如寫完的日記該怎麼儲存。\n“保存並轉發”應該是這個吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103001] = {id = 11103001, name = "澄練", head = "11030", type = 5, title = "敬啟，我的領航", txt = "好久不見，領航。我現在正在通過名為“電子郵件”的互聯網功能與你聯絡。\n距離我們平心社來到方舟也有幾年的光景了，我們也逐漸適應了這裏的生活。即使是我這樣愚鈍的人也能像這樣熟練地使用現在人類的科技產物了。\n現在回想起初來乍到時我們面對這些科技手足無措的經歷，真是讓人忍不住唏噓。\n我很慶倖能生活在這樣的時代，但因為有原罪存在，所以這個時代還不夠完美，如果可以，我想邀請您與平心社的大家一起來參加我的生日會。我想和您聊一聊您所經歷的“歷史”。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103002] = {id = 11103002, name = "澄練", head = "11030", type = 5, title = "今年的生日會也照常舉行", txt = "過去，“史官”以書面的形式記錄歷史。\n現在，人們記錄“曾經發生的事件”的方式更多依靠的是電子設備……是類似“記事本”一樣的軟體吧？\n比起容易被時光侵蝕的紙張，保存在電子網路中的數據理所當然地能夠保存更久。\n十年，百年，千年，過去因為保存方式的局限性而丟失珍貴史料的悲劇，在遙遠的未來恐怕再也不會發生了吧。\n能有幸以“史官”的身份接觸這個時代，對於我這樣平凡的人來說，無疑是一種恩賜。\n領航，今年的生日會，我希望能以“數據”的方式記下來，即使過去千年，今日發生的事也能被後人看見。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111031] = {id = 111031, name = "萊拉普斯", head = "11031", type = 5, title = "久違的生日", txt = "黎貝卡今天突然找上我，說要給我慶祝生日。\n不是她提醒，我都忘了今天是什麼日子。\n在登上方舟之前，店長每年會為我們訂蛋糕，和我們一起慶祝生日。都是靠她，我們才能想起自己的生日。\n現在說以前也沒什麼意義了，畢竟店長已經……\n不對不對，今天不是說這種事的日子。\n我裝飾了下房間，還試著做了一個蛋糕，可能外觀不太討喜，但味道應該是沒問題的……吧。\n你應該明白我說這些的意思吧？明白了的話，就快點過來吧，我和黎貝卡在等你呢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103101] = {id = 11103101, name = "萊拉普斯", head = "11031", type = 5, title = "好的改變", txt = "剛剛發給你的那張照片看到了嗎？是黎貝卡給我做的生日蛋糕。\n很漂亮吧？是她和其他小隊的朋友一起做的蛋糕。\n大概半年前，她還是那個更喜歡站在遠處觀察其他人的狀態，直到前陣子才跟我說自己試著交了幾個朋友。具體的結果，我剛剛也發給你看了。\n怎麼說呢……嗯，挺好的。\n以前在洛根市的時候，我們確實沒交到什麼同齡人朋友。但現在，聽到她吃飯時興致勃勃地跟我分享那些跟朋友之間發生的事，我想，這裏的生活確實又補上了她生活中缺失的一部分。\n——也許，還有我的生活裏缺失的某些部分。\n謝謝你，領航。\n無論多少次，我都想向你傳達這點。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103102] = {id = 11103102, name = "萊拉普斯", head = "11031", type = 5, title = "只是定期聯絡", txt = "嘿，你現在有空嗎？\n只是想定期聯絡一下。畢竟，星爍和千秋她倆總是聯系不上，我們平時的活動許可又比較有限——綜合下來，你就老實擔任我的人際交往對象吧，這在正常的社會關系裏可是很重要的。\n……好吧，我其實還有些正事找你。\n黎貝卡對慶祝生日這事很上心，這點你從前幾年的派對和手制蛋糕上也能看出來——而作為姐姐，我卻總是那個單方面的享受者，這也太不像話了。\n為了能在她下次生日時送件像樣的禮物，我需要你支支招，畢竟……我自認對身邊人的喜好把握得不算太好。\n……這可是我很鄭重的請求，你如果沒太忙的話，會抽點時間出來吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111032] = {id = 111032, name = "千秋", head = "11032", type = 5, title = "我要獨享生日蛋糕", txt = "終於等到這一天啦！哼哼，我期待這一天可是很久了！\n你要是問我為什麼這麼期待這一天，那我就要殺了你噢，我可不想聽到這麼愚蠢的問題。\n所謂“生日”，就是一個哪怕是艾吉斯的罪犯也可以理直氣壯地，不會有任何顧慮地吃蛋糕的日子吧。\n怎麼，你不會希望我把蛋糕分享給你吧？任何想從我手上奪走蛋糕的人，我都會把那不長眼的傢伙大卸八塊！\n不過，你要是說一聲“千秋大人”，我到不介意把蛋糕分享給你！快叫吧~叫一聲就好了啦，叫一聲我就會把蛋糕分給你的！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103201] = {id = 11103201, name = "千秋", head = "11032", type = 5, title = "小氣史蒂芬妮的陰謀", txt = "喂，你知道史蒂芬妮那傢伙肚子裡在打什麼鬼主意嗎？\n噢，我忘了，你還不知道發生什麼了……\n史蒂芬妮那傢伙居然一反常態，用惡心到我快吐出來的笑容說，“今天是你的生日，所以你想做什麼都可以——當然，不能做超出法律允許範圍的事情。”\n她怎麼會突然這麼大方？肯定是藏了某些我不知道的陰謀……\n總之，你快過來幫我，我一個人對付不了她！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103202] = {id = 11103202, name = "千秋", head = "11032", type = 5, title = "我討厭自來熟的小鬼", txt = "到底是誰把“生日當天受刑人可以自由活動”這種事散播出去的，是你嗎？還是哪個愛說閒話的受刑人？\n眞是的，一早上醒來就收到那個叫做“查麗莎”的人發的郵件，“滴滴滴”地吵死人了。\n說是要給我慶祝生日的……她不會以為只是在一場任務中並肩作戰了一次，我們就是朋友了吧？\n眞讓人不爽，所以我才討厭那種自來熟的小鬼，她還用上了“小千秋”這種稱呼，惡心到我頭皮都裂開了。\n不過，看在她打算花自己錢辦一場蛋糕宴會的誠意上，我就姑且不把她大卸八塊了。\n她說客人的名單上有你，你可別爽約，要是你不來的話，我就把她大卸八塊！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111033] = {id = 111033, name = "星爍", head = "11033", type = 5, title = "要來參加我的七日遊嗎？", txt = "生日——是啊，今天是我的生日，我都快忘了。要不是電子臺歷設置了提醒，我可能會把今天當做尋常的一天度過。\n既然是我的生日……那麼我稍微任性一點也沒關係吧？如果史蒂芬妮追究責任的話，就麻煩色狼先生你去幫我解釋咯~\n是不是在想我要做什麼？哼哼，我這邊抽中了七日遊的雙人旅行大獎，可以去薩哈拉度假噢。怎麼樣，要把你生命中的微不足道的七天交給我嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103301] = {id = 11103301, name = "星爍", head = "11033", type = 5, title = "給自己的生日一個驚喜", txt = "說起來，我差不多是半個月前知道自己生日要到了，畢竟每年的一月一日更換日曆的時候就會注意日期，進而想到距離自己的生日只剩下不到半個月了。\n於是在這倆周裡，我總會忍不住去想今年會有一個怎樣的生日——畢竟去年的這個時候，我和色狼先生度過了一個難忘的生日嘛。\n今年的生日……叫上千秋和萊薇她們，一起來打棒球，如何？我早就想舉辦一場星爍主題的棒球大會了\n你要是拒絕這個提議的話我會很傷心的~\n對了，史蒂芬妮那邊就麻煩色狼先生去解釋了~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103302] = {id = 11103302, name = "星爍", head = "11033", type = 5, title = "偶爾也想做些浪漫的事情", txt = "前年是七日遊，去年是棒球大會，今年是什麼呢——\n注意到生日快到的時候，腦子裡就會不自覺地去想這些。\n人是活在當下，向著未來展望的生物，因為對未來有著期待，所以才能享受當下。\n對我來說，每年能夠不用在意史蒂芬妮的意見去和你見面的日子——也就是今天，就是我最期待的“未來”。\n好了，雖然沒想好今年要做什麼，但是見了面後，我們就去做些浪漫又愜意的事吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111034] = {id = 111034, name = "羅德尼亞", head = "11034", type = 5, title = "姐姐她也很中意你哦", txt = "今天我去見姐姐了，和往年生日一樣。\n原罪的入侵、第三研究室防衛班的重組……過去一年發生的所有事，我都和姐姐說了。特別是說到領航時，風鈴響個不停，像是姐姐在催著我多講點關於你的事情呢。\n——啊，領航沒有來過，應該還不知道。姐姐的墓碑旁有棵小樹，幾年下來都沒見它長高過，仿佛和沉睡在這裏的人們一樣，時間都停留在了過去。風鈴是我掛在樹枝上的，一有風吹過就會響個不停，“叮鈴鈴鈴~”，像是在演奏樂曲，可有意思了。這樣就算平日裏沒有我的陪伴，姐姐也不會感到孤單……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103401] = {id = 11103401, name = "羅德尼亞", head = "11034", type = 5, title = "超需要領航的幫助", txt = "我決定從今日起洗心革面。\n我發現了所有超強大的人的超秘密。\n比如我的姐姐，她是一名超溫柔、超強大的駕駛員，像英雄一樣會去拯救所有遇到危險的人。\n然後是多洛莉絲隊長也有一顆超溫柔細膩的心。\n最後是領航你，你也要同樣有著這些超英雄的特質。\n所以——從這次生日之後，我的目標就是成為你們這樣的人。今天是我作為羅德尼亞的最後一天，從今往後我就是超羅德尼亞。\n來和羅德尼亞進行最後的超狂歡吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103402] = {id = 11103402, name = "羅德尼亞", head = "11034", type = 5, title = "緊急求助！", txt = "因為事態超緊急的所以長話短說！\n昨天……還是前天來著？總之前幾天，我突然收到了一封郵件。發信人是姐姐的父母。（我找艾吉斯的工作人員好好確認過了！）\n我之前只在去給姐姐掃墓時遠遠看到過他們幾次。但在那封郵件裏，那兩位老人家居居居然邀請我去他們家過生日！\n好像還說了什麼之前一直沒準備好跟我交流之類的，具體的我當時超超緊張記不清了！\n怎麼辦啊領航？艾吉斯教過我戰鬥但完全沒教過我處理這種事啊！這麼下去我會因為緊張過度噎死在姐姐家裏的！\n我現在正全速往你的房間沖過去，能不能安然度過這關就全看你了，領航！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111035] = {id = 111035, name = "桀派", head = "11035", type = 5, title = "人家的生日到啦", txt = "哼哼，領航，猜猜看今天是什麼日子？\n哼哼，你一定知道今天是人家的生日吧？\n你肯定不會想成是另外一個人的生日吧？。\n領航記著人家一個人的生日就足夠了！\n咳咳，總之，今天是人家的……不知道第幾個生日，但是今天你一定要陪人家玩噢！\n今天的領航，只屬於人家一個人！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103501] = {id = 11103501, name = "桀派", head = "11035", type = 5, title = "人家生日又到了", txt = "感覺有什麼事情要發生了，但是為什麼人家的身邊卻還是一如既往的——明明今天已經到人家的生日了！\n真是從未有過的體驗，人家生氣了。\n如果你不願意過來的話——現在馬上，人家就會到你的身邊。\n懲罰的話人家也早就想好了，在人家度過的這麼年，領航你是最有膽識的一個！\n不要說沒有時間騰出來給我和忘記了之類的話，今天的領航~一定是只屬於人家一個人的！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103502] = {id = 11103502, name = "桀派", head = "11035", type = 5, title = "來自完美的美少女的邀請", txt = "生日啊……對於人家這種死而復生的老家夥來説，是不是應該叫“過大壽”？\n不過，人家可是身體永遠16歲的美少女！……心靈也是永遠16歲！\n身體和心靈都是16歲……所以説桀派我啊，就是完美的永遠16歲美少女哦。\n人家的生日派對，你一定要來參加。\n人家是知道的哦，領航不是那種狠心會讓美少女流淚的男生，對吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111036] = {id = 111036, name = "普瑞席歐", head = "11036", type = 5, title = "生日的意義", txt = "雖然我言必談及數據，但我並非對每個數字都抱有興趣，例如出生日期，除了提醒我在生物學意義上離死又近了一步，就沒什麼值得一提的了。\n人類慶祝生日的目的是什麼？起初也許是迷信，而在如今這個時代，則是像其他節日那樣找個藉口放鬆。\n但與公共節日的區別在於，生日更加私人化，它的日期因人而異，它的性質其實與我每次攻克一個困難課題、完成一項突破性研究後，所進行的慶祝行為相似——即是說，生日正是為慶祝自己又在生存這一課題上取得了階段性成果。\n……如此鋪墊，可能我也只是想說服自己放鬆下。所以領航，今天陪我一起盡個興吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103601] = {id = 11103601, name = "普瑞席歐", head = "11036", type = 5, title = "關於今年的生日報告", txt = "親愛的領航，當你看到這封信的時候，我應該正在自己的實驗室裡對新取得的原罪樣本進行剖析，以消磨等你到來的時間。\n在不久前，由去年的我設置的鬧鈴打斷了實驗。\n今天居然是我的生日……我的確將這件事忘到了腦後，畢竟，在過去的人生中，它的優先度總是低於我的興趣。\n不過，去年的生日讓我對於這個用來記錄人正式成為一名“人類”的數字產生了改觀。\n於是，你今年還願意陪我度過這個生日嗎？我靜候你的回信。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103602] = {id = 11103602, name = "普瑞席歐", head = "11036", type = 5, title = "小小的麻煩", txt = "長話短說，我現在遇到了一些麻煩。\n一周之前，我想著讓自己的生日能更實際地和科研成果關聯起來，開始了一項原本該在昨天圓滿落幕的研究——鐺鐺，問題就這麼發生了。\n啊，不是說項目本身出了什麼岔子。相反，沒發生什麼意外，所有數據都很清晰，我甚至從中發現了好幾個值得深入研究的“驚喜”。\n因此，這個項目的收工時間正一步步地向著今天零點邁進，這就是問題。\n所以，雖然和原本的安排不太一樣，但作為讓我對“生日”產生了額外掛念的罪魁禍首，就勞煩你今年也稍微跑一趟咯？\n我也會努力提前結束，好讓你不感覺太無聊的。所以，原諒我吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111037] = {id = 111037, name = "塞蕾希婭", head = "11037", type = 5, title = "僅限今天", txt = "我思考了很久，不知道自己這麼做究竟是否得體，但最終還是決定，無論如何都得在今天向您發出邀請……雖然，我本人並不讚同放縱自我去慶祝什麼，尤其是慶祝一個虛假的日子。\n儘管我的個人檔案記錄了生日，但那其實只是教會在雪地中找到我的日子，我真正誕生於何時？這個問題的答案已經被大雪埋沒，何況，我也並不是那麼想知道，教會已經給了我一個新的生日，這讓我明白，生日其實是為了他人，而非為了自己存在的。\n所以，不論我自己對今天在意與否，也許您從之前就記著這天，我希望能對您回以尊敬，僅限今天，我會在教堂內等您，無論多晚……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103701] = {id = 11103701, name = "塞蕾希婭", head = "11037", type = 5, title = "潔淨之身", txt = "清洗身體，不只是為了除去身上的汙穢，同時也是洗清內心積攢下的陰晦情緒，使自己回歸如初生般纖塵不染的狀態。\n今日，是我的生日，亦是我與您一年一度的私會之日。\n為了迎接這一天的到來，我會用潔淨之水濯洗身體，淨化心靈，用未被這俗世一切所玷污的“我”來迎接您——請務必不要失約，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103702] = {id = 11103702, name = "塞蕾希婭", head = "11037", type = 5, title = "新生之月", txt = "十二月，一個冷漠的時節。\n作為一年的末尾，十二月的到來宣告著一年的結束。\n一切重要的，不重要的事都將了結。年初定下的計畫多少已經完成？又有多少還在進行抑或是還沒有開始？十二月不會因為任何人的求饒而停下終結的腳步。\n那些期望通過十二月的努力來彌補過去十一個月的人，所謂徒勞正是如此。\n春天種下的種子能否結出甘甜的果實，答案在秋天便已揭示。冬天的職責不是收穫而是埋葬。以白雪和寒風為棺，將過去一年的不甘和悔恨埋葬在貧瘠的精神土壤之中，如此堆積養分才能得到純淨的新生。\n領航，在十二月，我願陪您一同埋葬過去孕育新生。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111038] = {id = 111038, name = "卡芙卡", head = "11038", type = 5, title = "人生相談！", txt = "喲，領航，你今天應該很閑的吧。我現在也閑得很呢，剛剛把街機廳裏的記錄都給刷新了一遍，你能明白這種無敵於天下的寂寞和無聊嗎。順帶一提，之前的記錄也是我的，嘿嘿。\n但是啊，感覺人生已經結束了啊！完全看不到未來的路在哪里……\n這就是所說的青春期的煩惱嗎？真的讓人火大。可惡，今天還是我生日，這不是又白白浪費了一年。\n領航，你作為大人對這種事一定很有經驗，請務必給我點建議。努力學習也好，保持現狀也好，什麼都可以。\n有勞了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103801] = {id = 11103801, name = "卡芙卡", head = "11038", type = 5, title = "还是人生相談", txt = "……有空嗎？有事想跟你聊聊。\n剛剛接到了臭老爹的電話。本來准備聽完第一句話就直接掛掉的，結果接通後傳過來的卻是老媽的聲音。\n具體聊了什麼這裏先略過，反正就是身體怎麼樣，傷口痛不痛，變回去後斷掉的手是不是真的會複原之類的。還說什麼他們很為我驕傲，過兩天有空回去幫我補上生日啥的。\n大概是前幾天小隊受到表彰的新聞被他們看到了吧。哈……\n明明是不爽家裏才這麼努力的，結果卻這樣了，我果然還是不想幹了，所以要找你辭職。\n開玩笑啦，但我是真想找人聊聊天。\n那就還是之前那個街機廳，沒問題的話，我現在就過去。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111041] = {id = 111041, name = "織女星", head = "11041", type = 5, title = "生日特權", txt = "最近聽說了一件有趣的事。\n似乎在多瑙支部，只要駕駛員過生日，就可以行使一種特殊的權利……\n那個權利就是可以無條件讓領航陪自己一天。（可要是倆人同一天生日怎麼辦？）\n沒想到這麼多年沒什麼意義的生日，在今年有不一樣的收穫了。\n領航，我想請你——還有你的妹妹和我一起玩一天，我想“好好”地和你們相處，你應該不會拒絕吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104101] = {id = 11104101, name = "織女星", head = "11041", type = 5, title = "急需幫助", txt = "你知道警備科最可怕的工作是什麼嗎，領航？\n是換季時期的文書處理哦。\n新發掘出的文物清單，它們的歸屬權和價值，相關設施的安保協議……包括之前因為原罪入侵被扔到一邊的那堆廢紙，在這時候都會一股腦兒冒出來哦？\n拜此所賜我過去一星期都只睡了三個小時哦？\n在堆滿辦公桌的文檔裏迎來了自己的生日哦？\n明明沒上前線卻已經快死了哦？\n……喪氣話就說到這吧，我一定是咖啡喝過頭了。\n幫我個忙吧，領航。\n等這堆工作完成後，我想用假期去一趟多瑙。幾小時就好，能再和吉雅一起抽些時間陪我嗎？\n就當替我實現一個遲來的生日願望，可以吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104102] = {id = 11104102, name = "織女星", head = "11041", type = 5, title = "河畔繁星", txt = "老樣子，今天是一個對我而言十分特殊的日子。\n哪怕是我，偶爾也想要在這個日子裏送給自己一份獎勵。於是——\n爲了能獨享安寧，我特意選了一個稍微有些特別的座標落座。\n這裏既遠離了喧囂，又能稍一眺望，便看見那盞亮眼的燈火\n——你所在的指揮室。\n若換成平日，我的腦子裏應該只剩下戰鬥的嘶吼吧。\n但現在，當我隔着玻璃就找到你的背影時，我突然覺得，過去受過的所有痛苦，在這些年裏都隨着夜風散了許多。\n彷彿在這個充斥謊言的世界裏，你幫我找到了……最真實的蘇亞娜。\n我想這纔是，領航送給我的最好的生日禮物。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111042] = {id = 111042, name = "海蘿", head = "11042", type = 5, title = "今天是什麼日子？", txt = "今天早上的時候，羅琳說：“你不會忘了今天是什麼日子吧？”\n我就回答說：“今天難道是我加入前線的紀念日嗎？”\n結果被她臭罵了一頓。\n被罵了一頓後她也不跟我說今天是什麼日子……真是個愛發脾氣的壞孩子。\n對了，領航，今天天氣真的很好，是非常適合散步的天氣。\n我們一起去把這座城市的每個角落都探索一遍吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104201] = {id = 11104201, name = "海蘿", head = "11042", type = 5, title = "今年不會搞錯了！", txt = "好了，我已經充分吸取去年的教訓了！\n早上以防萬一去確認了日曆，發現今天的日期上果然寫著一個超大的“生日！！！！”，提前做備忘果然是對的！\n之後我又檢查了宿舍，發現不僅是禮物，連派對裝飾和蛋糕都準備好了，而且還是之前羅莎一直想試但又舍不得買的榛子曲奇口味，前幾天的我簡直是天才吧！\n總之，這下就萬事俱備了！領航，你有空的話也過來跟我一起布置場地吧，我絕對絕對要給羅莎準備一個讓她目瞪口獃的生日驚喜！\n\n【以下為回複信息】\n我收到你的回復了，但是——領航，什麼叫“羅莎琳德的生日是4月16日。在她發飆之前快停手。”？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111043] = {id = 111043, name = "米菈", head = "11043", type = 5, title = "不要給別人看到這封信哦", txt = "生日的祝福，以及神明的祝福，兩者間究竟哪個更加優先，彼此又是否存在重疊？曾經的我，其實會一本正經地思考這樣無聊的問題，到後來我才明白自己實在是不解人意，根本搞錯了重點，甚至以為人們在意的真的是祝福本身。\n畢竟是紀念自己降生的日子，開開心心的就好了嘛，今天到了我的生日，我也想卸去那些麻煩的職責，單純度過一天。\n我想穿上平時不會在信眾前穿的私服，以不會被認出來的尋常少女模樣，和領航你一起隨便找些地方閒逛。這樣子是不是還有點瞞著神明幽會的背德感呢？光是想想就很有意思。那麼，碰面地點就由你決定吧，盡快回復我哦。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104301] = {id = 11104301, name = "米菈", head = "11043", type = 5, title = "神明遺忘我", txt = "願神明的光輝照耀你——也許是神的巧妙安排讓你在這個時間收到這封郵件。\n開玩笑的，“修女”可不是能引起這種神聖奇跡的“職業”，若是說開導民眾的我們，穿著修女服的我們被神明注視著，那麼至少在私底下我們是普通的少女，只有此時此刻我們被神明所遺忘。\n所以就在昨天，我向神明許下了願望，希望你今天能有時間來慶祝一下我的生日。\n那麼，在那神不在的夜晚，請與我一起。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104302] = {id = 11104302, name = "米菈", head = "11043", type = 5, title = "神明不在的星期二", txt = "水能滋潤萬物，水能潔凈萬物，聖濯教會的信仰正是這个槪念，所以也可以説，水就是我們的神明。\n而在我們的教義中，僅有一天可以松懈這份信仰……在這一天可以把自己當作神明……在自己的生日那天去做自己想要做的事情，這就是今天這封信的理由——我會在今天到達領航的身邊給領航講講我們聖濯教會的小知識。\n那麽最後……願神明的光輝照耀你的夜晚——在這神不在的星期二。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111044] = {id = 111044, name = "海因", head = "11044", type = 5, title = "離開珀因雷德", txt = "當領航看到這封信件的時候，我已經坐上了離開的珀因雷德的航班。請別誤會，我並不準備背井離鄉，僅僅是去收集繪畫的素材。\n經過珀因雷德的那場風波後，我已經不想再捲入其他麻煩事，暫時把精力集中在繪畫這件事上。\n希夏送了我一張植物園的門票當作是她的生日禮物。雖然門票不貴，生日當天還能打個5折，不過若是真能看到些奇花異草倒也是物超所值。\n不知道是不是巧合，這植物園的位置好像與領航的住所有些接近。等參觀結束，能否去你的住處，我想請領航評價一下我的植物寫生。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104401] = {id = 11104401, name = "海因", head = "11044", type = 5, title = "從未見過的風景", txt = "當領航看到這封信件的時候，我已經坐上了離開的珀因雷德的航班——姑且，就請讓我用上和去年一樣的開頭吧。\n去年的今日，我踏上了前往植物園的路程，而自那之後的一年間，我走遍了多瑙，無論是承載著榮耀與歷史的人造建築，還是由自然的鬼斧神工造就的自然風光，都已經被納入我的畫集。\n然而，我內心的渴望卻沒有滿足——為什麼呢，想必是因為這些都是“他人已經見過”的景色。\n我所追求的，是別人未曾踏入的領域與景色。\n思來想去，也就只有一處——或者說一個人了。\n領航，再過一會，你就會見到我了。\n你的身體，將會被當做瑰寶傳下。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111045] = {id = 111045, name = "吠黎爾", head = "11045", type = 5, title = "設置12月09日定時發送", txt = "【音頻文件轉文字】\n時間應該沒有設定錯吧？\n……欸？已經開始錄了？你怎麼不提醒我？還有D34幫忙寫的那張紙放哪去了——別拿過來，S52。不要你的。你寫那東西，是人能說出口的話嗎？\n算了，我直接說吧。\n喂，領航，聽得見嗎？想拜託你件事。12月9號，也就是收到這段錄音的那一天，可以申請調派我來執行任務嗎？什麼任務都行，只要能讓我巨大化。對了，態度記得要強硬點。\n研究所這邊的人到現在還堅持著說什麼生日當天要好好休息——開什麼玩笑。沒有幻化核心，我連“保持清醒”都做不到。\n至少今年的生日，我不想再錯過了……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104501] = {id = 11104501, name = "吠黎爾", head = "11045", type = 5, title = "發呆並不意味著愚鈍", txt = "【音頻文件轉文字】\n其實，我聽得見。\n我能聽見，大家對我説的話。\n惡意的言辭，善意的言辭，刺痛人心的言辭，温暖人心的言辭。\n我都聽得見。\n我不能將自己心中所想的內容娓娓敍述，但我能思考，能分辨善與惡。\n可是，唯一能知道我所思所想的人，只有你，領航。\n今年的生日，我想將我在短暫人生中的所思所想，盡數傳達給你，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111046] = {id = 111046, name = "佩佩塔", head = "11046", type = 5, title = "我想當老師的支柱", txt = "對於老師來說，佩佩塔是什麼呢？\n是需要格外照顧的孩子？是不靠譜的問題學生？是總給老師添麻煩的壞孩子？\n不管是哪一個，對於我來說都是最差勁的選項了。\n我想要站在老師身邊，成為一個能和老師並肩作戰的優秀駕駛員，成為老師的……支柱，\n這就是我的心願，這就是我今年的生日願望。\n我一定會實現的，老師你就拭目以待吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104601] = {id = 11104601, name = "佩佩塔", head = "11046", type = 5, title = "我聽到了，那是戀愛列車即將進站的轟鳴聲", txt = "領航，當你從深夜醒來時，有沒有聽見那震耳欲聾的轟鳴聲。\n那聲音穿透了方舟的防護，穿透了你房間的墻壁，直達你內心最深處。\n那正是名爲“戀愛”的列車抵達終點站時的轟鳴聲。\n我，佩佩塔，自詡比所有戀愛專家都要更加專家的戀愛戰車（不要問爲什麽不是列車）即將闖入你的房中。\n不許鎖門，不許設置密碼，我馬上就要到了！\n我想要領航的“生日快樂”當生日禮物！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111047] = {id = 111047, name = "蕩漾兔", head = "11047", type = 5, title = "我的年度總結", txt = "薩哈拉的蒼穹學院在每年的最後一天都會進行每年一次的年度大會，目的是總結學院這一年來在多領域上的成果。\n然後，你現在也應該知道了，我的生日也正好是一年的最後一天。\n哼哼，你應該想到我要做什麼了吧？\n沒錯，我計劃讓蒼穹學院的年度大會，成為我的年度總結日。\n作為我的製作人，你應該不介意與我共同闖下這彌天大禍吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104701] = {id = 11104701, name = "蕩漾兔", head = "11047", type = 5, title = "畢業通知", txt = "在這今年最後一天，也是蕩漾兔的生日，我有一個重要的通報。\n【在過去一年每天都在網路世界活躍的偶像蕩漾兔，今天將畢業了。】\n我知道這很突然，作為粉絲兼製作人的你或許一時間無法理解，可這是深思熟慮後做出的決定，無法更改。\n然而製作人也無需感覺遺憾，因為接下來我將宣佈第二份通報。\n【即將統治網路，橫掃虛擬與現實的超級偶像蕩漾兔，從今天開始出道啦！】\n沒想到吧，這叫轉生，是很平常的操作。我怎麼可能捨得離開製作人你呢？\n雖然名字沒有變，但從此以後，新“蕩漾兔”人生中的每一段剪影都將包含製作人你的存在。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111049] = {id = 111049, name = "阿爾泰婭", head = "11049", type = 5, title = "十幾歲的生日沒有什麼深層意義", txt = "今天是我的生日！是阿爾泰婭·維斯的生日！雖然這麼說你可能也會想“哪個阿爾泰婭？”之類的事，但就當做是我本人的生日吧。\n以前看過的一部動畫的標題叫做“二十幾歲的生日沒有什麼深意”，但反過來呢，難道十幾歲的生日就有深意了嗎？還是說到了三十歲以後的生日就深意了嗎？\n最近我才想明白，其實它的意思是生日本來就不該有什麼深意。\n用自己喜歡的方式度過這一天就是對生日意義是什麼這一問題的究極最佳唯一正解！\n蜥蜴先生，來陪我看電影吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104901] = {id = 11104901, name = "阿爾泰婭", head = "11049", type = 5, title = "不是高中生的話，就不是主人公了吧！", txt = "今天是我的生日！是阿爾泰婭·維斯的生日！\n希望能讓這句話成為我的專屬臺詞！下一次的生日我也會說“今天是我的生日！是阿爾泰婭·維斯的生日！”的！做好心理準備吧！\n然後，隨著年齡增加，我發現自己快要不是女子高中生了！那不是糟糕了嗎！\n動畫裡的主人公一般都是高中生吧，如果我不再是高中生的話，那我不就當不了主人公了嗎？\n難道說，最近動畫裡成年主人公數量增多，也是因為當初的觀眾都不再是學生了嗎……\n一下子感覺窺視到了世界的真相，好殘酷啊……\n總之，今天是我的生日，蜥蜴先生今年也會來和我一起慶生的吧？會的吧？會的吧？會的吧？！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111052] = {id = 111052, name = "斯珀絲", head = "11052", type = 5, title = "最偉大的勇者爆誕的日子", txt = "媽媽説過，今天是未來的救世主，人類最後的希望，注定要拯救世界的勇者——也就是我，斯珀絲的生日。\n但是生日是什麽？生日的意義是什麽？我完全不明白！\n畢竟對於拯救世界的勇者來説，生日這種知識是無關緊要的東西。\n不過，媽媽總會在這一天主動給我準備喫的東西，所以應該是不錯的日子。\n好了，蠢貨一號同伴，雖然不知道這封信能不能傳達給你，但至少在這一天，要想著給偉大的勇者斯珀絲慶祝生日，不然我不會原諒你的！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111055] = {id = 111055, name = "red", head = "11055", type = 5, title = "我發育了。", txt = "大大大大大大大新聞啊！作為人類與原罪的頂點，完美的新人類的我，在今天檢測的時候發現胸部變大了。\n你知道這意味著什麼嗎？我之前的形態已經不再是人類的最佳形態了，我正在朝著完美更進一步地發展！\n就連紅博士都喫驚不已地說出：“沒想到這個身體的樣子會發育啊？我還以為會這樣一直保持到宇宙毀滅呢……奇怪……但為什麼是胸部？”這樣的話。\n哈哈，那個白癡到現在還以為自己初中時候的樣子是完美的新人類形態。\n不過確實……為什麼是胸部？不過這不重要，趕緊過來給你看看世界上最完美的胸部。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111058] = {id = 111058, name = "米夏", head = "11058", type = 5, title = "請假申請", txt = "尊敬的領航：\n您好。\n我是米夏……對於在百忙之中打擾到您，我感到十分的抱歉。但是，我的確是是有要緊的事務需要您的幫助。\n就不賣關子直說了，我今天想要請個假。\n對不起，對不起，對不起……我知道請假這種事需要提前申請，不過我也是今天早上才想起來，今天好像是我的生日。\n我的生日，也是米婭的生日……\n之前在家的幾年裏我都沒有好好過過生日。所以今年我想要難得地“慶祝”下自己的生日。蛋糕、蠟燭已經準備好了，如果領航您能來參與的話……啊！當然如果沒時間也沒關係……\n總之我會給領航畱一塊蛋糕，隨時等著您。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111060] = {id = 111060, name = "戈露卡", head = "11060", type = 5, title = "求救信", txt = "（本消息為語音郵件）\n——致親愛的領航。\n當看到這封信時，你已經是我最後的希望了！\n一周前，我通過了硏究室的駕駛員測試，把今天定為了自己的生日。可是，就算是這種日子，負責的硏究員也還是不允許我外出！\n我知道這是擔心我的安全啦！但一整年都只是獃在圖書室裏，我一定會在某天悶死的！\n總之，我都已經接受了在宿舍開生日派對的提案了，店長和特薇姐卻都說自己有事沒空來！\n現在能防止我在生日會上單人唱歌的就只有你了，一定要來哦！\n……這樣說沒問題吧？領航小哥他眞的聽到這些就會來？\n誒？我沒按結束鍵？店長你快幫我翦掉——", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112000] = {id = 112000, name = "金庫啦", head = "12000", type = 5, title = "記得寫名字啦！", txt = "第一個提議生日時要送壽星禮物的人絕對是天才！\n單看禮物數量，就知道本小姐之前的努力沒有白費。哼哼，商業帝國指日可待~\n相比其他合作夥伴的賀禮，領航送來的就有點……啊，沒有嫌棄它的意思！只是因為包裝太過不顯眼，本小姐至少用了兩個小時，才把它找出來。\n所以下次，也就是明年，要記得在盒子上寫上領航你的名字哦，越大越明顯越好！不然如果本小姐沒看到、漏掉了，絕對會傷心一整年的……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200001] = {id = 11200001, name = "金庫啦", head = "12000", type = 5, title = "我要錢買不到的禮物", txt = "生日禮物這種東西，收得多了，也就膩了。\n那些用金錢就可以輕易衡量出價值的禮物，即使收到了也不會高興。\n對——換句話說，領航，本小姐想要你親手製作的禮物，什麼都行——寫上你的名字，送到本小姐的手上來。\n……一定要記得送啊！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200002] = {id = 11200002, name = "金庫啦", head = "12000", type = 5, title = "距離買下艾吉斯還差多久", txt = "又一歲。\n哼哼~從艾吉斯今年的財報來看——這个巨大的，統合了世界的組織已經完全停止了成長和發展，開始進入了穩定期。\n而本小姐的財富還在持續地增長，現在已經能買下卡佳和藍山地區了也説不定……本小姐的商業帝國會建立在人類至高的七艘方舟之上。\n那麽……今年的生日禮物也請領航記得送，爲我的帝國添磚加瓦。本小姐會善待它的，當然在今天晚上的宴會上，我也會善待最重要的領航的……呵呵……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112001] = {id = 112001, name = "静", head = "12001", type = 5, title = "四年之约", txt = "領航,今天是我的生日，每四年一次的生日。\n因為這個特殊的日子，父母曾想在每年的28號為我慶生。但我拒絕了，太麻煩了。大家族的生日晚宴是普通人想像不到的繁瑣，遠沒有宅在房間裏愜意。\n我不想讓他們把目光都集中在我身上。他們應該更多地看看姐姐，姐姐才是【克雷蒂亞】的唯一繼承人。至於我，我只想躲在姐姐背後，輕鬆快樂地過完這一生。\n唉，寫這麼多字好累，但一想到要在晚宴上接見那些不認識的名流更累。畢竟我也是【克雷蒂亞】，明面上的功夫還是得做好。\n不想寫了，回頭我再想想有什麼要說的，等四年之後再和你說吧。\n拜拜。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200101] = {id = 11200101, name = "静", head = "12001", type = 5, title = "意外……", txt = "嘿嘿，領航，沒想到能收到我的郵件吧……\n寫這封郵件單純是為了試驗下我新購買的裝置……\n腦波輸入操控儀——讓家居更智能……奇怪，後半句明明不是我想輸入的……\n算了這不重要，顧名思義，使用這個裝置就可以不用起床，躺著操控各種設備……\n像這樣需要寫郵件的時候不用打字光靠腦子想就可以完成，對於我這種懶人來說真是太好用了……\n當然了，找領航搭訕的藉口還是得自己來想……這句話可不能讓領航知道……\n唉，雖然打字和發送可以靠這個裝置來實現，但是刪除還是得靠自己啊……\n刪除後再發送吧……刪除，發送，發送郵件……\n不好！……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200102] = {id = 11200102, name = "静", head = "12001", type = 5, title = "我現在才幾歲也說不定", txt = "在迎來自己的生日之後，人才會增長一歲，以此來向其他人宣告來到這個世界已經滿一年了，越來越成熟了。\n然後接下來是……嗯我想說什麼來著……對了這麼說來，因為我的生日是2月29日，所以成熟得要比別人晚一點也說不定，我說的當然不是肉體的成長，而是精神上、心智上還沒有完全做好成為一個大人的準備，還沒完善，至少要等我60歲的時候再說吧。\n哎……也許我現在還是一個幾歲的嬰幼兒，她們這是在虐待兒童。小嬰兒想要睡覺了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112002] = {id = 112002, name = "不知火", head = "12002", type = 5, title = "世上最可愛的領航在哪里呢~", txt = "嘿。小可愛領航該不會忘了今天是什麼日子吧？要是連句“生日快樂”都不願意說給姐姐我聽，會不會有些太冷漠了？這可不是個好孩子該做的事情。\n——好啦，不打趣你了。\n最近很忙？好幾天沒聽到你的聲音，風林火山的大家都挺想你的。\n今天她們一直陪著我呢，連平日裏不喜歡集體行動的鬼之介也在。呵呵，能被乖孩子們圍在中間，我真想天天都是生日。\n那麼等你什麼時候有空了，來一起吃頓飯吧，讓她們也開心一下。就當是給我的生日禮物，好麼？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200201] = {id = 11200201, name = "不知火", head = "12002", type = 5, title = "要好好抓住生日這個機會", txt = "最近和小瑩草聊起生日時，她總會擺出一張苦瓜臉。\n這提醒了姐姐，比起大人，還是小孩子會更加喜歡生日吧？\n所以姐姐有了一個想法——用姐姐的生日，來舉辦一個讓所有孩子都高興的生日會。\n小清風她們自然不說，心經屋和天華閣那邊我也會聯繫的……不過，其他駕駛員就得拜託你了，領航，誰讓你這麼受那些孩子的歡迎呢？\n你會滿足我這小小的請求吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200202] = {id = 11200202, name = "不知火", head = "12002", type = 5, title = "做了一個夢", txt = "……嗯……我夢見領航變成了小孩子……而且我還自稱是領航的媽媽……\n雖然做夢的時候非常開心，醒來之後還意猶未盡……但現在仔細想想~這應該是噩夢吧~\n我是喜歡和小孩子玩沒錯，但是姐姐我可是把領航當作一個可靠的男性，可靠的弟弟來看待的……對於我來說，領航和風林火山的大家、和小孩子是不一樣的~\n你能明白我想說的意思吧？\n咳咳……那麼，今年的生日會也請多多指教~我的領航~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112003] = {id = 112003, name = "葉芙根尼婭", head = "12003", type = 5, title = "今天要練到休克！", txt = "哈哈，沒想到吧，今天是我的生日！其實我也才剛想起來啦。\n雖說還挺開心的，但即使是這種日子，我覺得自己也不該太放縱了。所以我就心想，不如一整天都加倍努力地鍛煉身體好了。這樣做，不就算既是在娛樂慶祝，又沒有荒廢時間嗎？\n領航老是在辦公室裡坐一整天，要不也趁這個機會出來陪我一起練練吧！當然，鍛煉之餘也得大吃一頓好好補充能量，這樣才能長肌肉嘛，放心，今天我請客。\n那就這樣決定了，要是沒什麼問題，等會訓練室見！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200301] = {id = 11200301, name = "葉芙根尼婭", head = "12003", type = 5, title = "特殊訓練專案", txt = "最近我好像遇到了訓練的瓶頸，無論我如何努力，如何加大訓練量，肌肉的力量始終停滯在這裏，不上不下。\n過猶不及……就是說的這種情況吧。\n“欺騙餐”，領航你聽說過嗎？好像是利用身體的本能來欺騙身體，從而達到突破訓練瓶頸的方法。之前我是一直不屑這些歪門邪道的，毅力和決心才是唯一有效的健身輔助……吧。\n“欺騙餐”具體的原理說起來比較費時，反正就是大吃一頓就行，正巧我的生日也到了，領航也一定很想吃大餐吧。好，那就麻煩領航當我的“欺騙餐”教練，監督我完成今天的大胃王訓練吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200302] = {id = 11200302, name = "葉芙根尼婭", head = "12003", type = 5, title = "岩漿呼吸法", txt = "世界是不公平的，我深刻地認識到了這一點。\n明明在進行持續的鍛煉和進食，比起去年的這個時候肌肉的輪廓卻小了一圈……但與之相反的，我的體重增加了。\n而且最近感受到即使在瀑布下麵修行，也有點過於輕鬆了。\n這是為什麼？難道肌肉也會有密度這種說法嗎……\n嗯總之，我已經不滿足於現在的修行地點了，我想趁著身體這天去尋找能給我帶來更大鍛煉感的修行場地。\n傳聞在卡佳的某處火山山頂上有古代遺留下來，用於先人掌握《岩漿呼吸法》的修行處\n我們去探索一下吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200303] = {id = 11200303, name = "葉芙根尼婭", head = "12003", type = 5, title = "健身房生日折扣", txt = "喲，領航，有件好事說給你聽。\n今天去健身房續卡的時候，正好趕上店裏的活動——生日當天可以折扣辦理健身會員，並且可以用於親友或家屬。我一看，今天不正好我生日嗎！二話不說就幫領航你辦了一張會員卡，因為我想起來之前你就說過想要鍛煉肌肉。\n今後我們就可以一起鍛煉！放心，有我在，不出半年就能讓領航也擁有一身健壯的肌肉。\n我這就來給領航你送會員卡，領航你準備準備，我今天就帶你去鍛煉鍛煉肌肉，先做個十組深蹲和俯臥撐。\n在健身房慶祝生日，不覺得很有趣嗎！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112004] = {id = 112004, name = "花語", head = "12004", type = 5, title = "今天的領航觀察日記", txt = "06:47 吃早飯。坐在角落裏，沒有和任何人說話。\n07:05 去檔案室取資料。期間幫三位女性職工取高處的文檔，有果斷拒絕回禮，就睜一只眼閉一只眼吧。\n08:43 協助駕駛員擊退原罪，使用了通感……真是便宜她們了……\n12:10 在吉雅的監督下，按時吃午飯。吉雅是妹妹，嗯，只是妹妹，要大度。\n13:30 開會，進不去。可惜。\n15:52 會議還沒結束……沒問題，今天是生日，請了假，可以不去訓練。還有很多時間。\n16:01 出來了。那個纏著問問題的女生是誰？為什麼要對她笑？\n16:15 被發現了。被摸頭了。開心，原諒你了。\n…………\n……\n日記被翻過。你偷看了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200401] = {id = 11200401, name = "花語", head = "12004", type = 5, title = "我來找你吧", txt = "昨天下午14點28分53秒的時候和你說話的那個女生是誰？\n你和她一共交談了42秒，你們在聊什麼？是什麼不能讓我知道的話題嗎？為什麼你們笑得那麼開心？和別的女孩子聊天很開心嗎？\n為什麼不來找我？我也可以陪你聊天啊。我還可以陪你做很多事，任何事！\n你應該沒忘記今天是我的生日吧？\n來找我好嗎？來找我好嗎？來找我好嗎？來找我好嗎？來找我好嗎？\n或者，我來找你吧。我來找你吧。我來找你吧。我來找你吧。我來找你吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200402] = {id = 11200402, name = "花語", head = "12004", type = 5, title = "想做什麼都可以", txt = "終於又到這天了，領航一定也和我一樣期盼著這天的到來吧。\n今天是我的生日……也就是說……今天誰都沒有理由把領航你從我的身邊搶走了。\n嘿嘿嘿，領航想和我一起先做什麼事呢……逛街嗎？看電影嗎？去遊樂園嗎？但是，這些涉及到公共場合的事會有與其他駕駛員偶遇的風險。我才不會讓別人有可乘之機，分走領航的愛。\n或許我們就不應該出去——領航的房間，或者是我的住處才是最適合舉行生日派對的地點。不需要什麼蛋糕和禮物，只要我們兩個在一起……\n我們，想做什麼都可以。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112005] = {id = 112005, name = "伊莉雅", head = "12005", type = 5, title = "只是一些牢騷", txt = "抱歉打擾領航的休息，但是今天對我來說是一個特別的日子。\n我的生日。\n或許領航很難理解，我在寫下這四個字的時候內心是多麼煎熬。光是想到這四個字我就不得不打上三針鎮定劑平復情緒。因為無論如何，這四個字都會讓我想起...我的父母。\n我無法忘記他們死亡的那個時候那絕望的表情，我只能不斷欺騙自己那是個夢，一個無法醒來的噩夢。但是生日——啊，對我來說多麼惡毒的字眼——一遍又一遍地提醒著我，那痛苦的真實。\n說來也怪，明明給波琳娜她們慶生的時候沒有想那麼多，但是一到自己就......\n或許只有在原罪滅亡的那天，我才能安心過生日。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200501] = {id = 11200501, name = "伊莉雅", head = "12005", type = 5, title = "生日的快樂", txt = "最近卡佳也到了夏天，山腳下的雪融化了大半，原罪也變得活躍起來了。\n今天到現在我已經出了四次任務，雖然都是些小的事件，但是加起來也消滅了十幾只原罪。沒有什麼是比看著原罪爆炸更爽快的事了，對我來說這就是最好的生日禮物。\n放心吧，經過治療的我現在情緒穩定了很多，不會看到原罪就殺紅眼，對鎮定劑的依賴也在逐漸減少。\n今天還沒有結束，有興趣陪我出外勤嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200502] = {id = 11200502, name = "伊莉雅", head = "12005", type = 5, title = "新的嘗試", txt = "時間過得真快啊，領航。\n明明聖誕節發生了那麼多事。結果埋頭工作一陣子，回過神來就又到我的生日了。\n我今年……在試著把這一天過得正常些。\n我買了蛋糕，整理了宿舍，做了些裝飾，邀請了身邊所有認識的人。還把往年會提交的額外作戰申請取消掉了。\n我知道的，原罪不會隨便消失。\n無論完成多少作戰，掃清幾片戰場，只要那該死的霧氣再次升起，我們的戰鬥就得繼續下去。\n但至少……在經曆了那次失控後，我覺得自己該更珍惜那些不用在戰場上度過的日子。\n有空來看看我的布置嗎，領航？\n克裏姆又把自己喝倒了，得有人來替我的審美把把關才行。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112007] = {id = 112007, name = "華夢", head = "12007", type = 5, title = "前往深山吧！", txt = "今天是小生的生日！\n在艾吉斯，好像每個人都有自己慶祝生日的方式。那麼小生也不能落後他人，我也要有自己獨特的慶生方式！\n對了，就去小生的故鄉如何——在那十萬大山，危機與機遇皆存的深山老林之中，度過一年之中最為重要的一天。如何，這個提議不錯吧？那麼——領航！和小生出發吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200701] = {id = 11200701, name = "華夢", head = "12007", type = 5, title = "想吃肉", txt = "小生今天來多瑙只為了兩件事……修行以及修行之後……吃肉……好大大口放肆地吃肉！\n從九州徒步來多瑙一路走來，小生通過參與突發的原罪戰鬥捶打武藝，在此基礎上忍耐著想要大吃大喝的欲望進行精神修行……想吃肉……小生認為如果沒有肉吃的話……習武的心境始終會有所欠缺！\n終於在生日來臨之前堪堪到達多瑙，至此小生對自己的修行已經完成，那麼接下來就需要解除對自我的約束……\n小生現在只想吃肉……其他的都先放到一邊……小生要先解決習武路上的心魔。\n所以領航——多瑙有沒有推薦的自助餐可以吃？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200702] = {id = 11200702, name = "華夢", head = "12007", type = 5, title = "拳法修煉", txt = "自從在老家房子的房梁上找到本形意拳法秘笈後，小生苦修形意拳已經有半年之久。在這半年間，小生已將兔子、倉鼠、小貓和企鵝這幾部分功法練至大成，融會貫通。如今，僅賸下“熊貓”這部分尙未修煉。\n“熊貓”，領航應該知道的吧。別看它們喫竹子時可可愛愛，實則是凶猛異常的猛獸。待小生練成熊貓拳，想來九州之內再難尋敵手！\n形意拳的修煉方法就是模倣，所以從當下起，小生便要喫竹子了。另外經小生觀察，動物園裏每只熊貓都有一位飼養員照料。那就煩請領航做小生的飼養員吧！\n記得給小生準備竹子蛋糕，這可是每只熊貓生日當天都能收到的禮物。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112008] = {id = 112008, name = "百里默默", head = "12008", type = 5, title = "生日大作戰！", txt = "唔哇好困哦！今天一大早，天還沒亮我就醒了，雖然的確非常期待生日，不過更主要的原因是被吵醒…茜茜姐苑苑姐伶伶姐她們，像是比我更加期待今天會怎麼度過，一早就在爭吵。\n茜茜姐想去挑戰雲霄飛車，不吐不歸；苑苑姐覺得找個圖書館泡著比較好；而伶伶姐似乎對水族館更有興趣。可默默又不會分身，怎麼才能同時滿足姐姐們呢？默默自己的話…倒是覺得地點無所謂，只要和喜歡的人一起開心度過就好。\n不知道像領航這樣聰明的人，能不能想出一個盡善盡美的辦法呢？默默突然想到，“領航”和“導遊”的意思有些像，今天可以帶著我們一起出去玩嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200801] = {id = 11200801, name = "百里默默", head = "12008", type = 5, title = "生日大作戰！！", txt = "早上好，領航！又到了默默的生日啦！不過今天茜茜姐苑苑姐伶伶姐她們反常地沒有爭吵。\n姐姐們說因為有了之前的經驗，今年的生日直接聽從領航的安排就好了，領航見多識廣一定能想到讓大家都開心的活動。\n不過姐姐們讓我轉告一些她們不想去的地方——茜茜姐說她生日就得熱熱鬧鬧的，所以博物館，圖書館之類的安靜地方她不想去；苑苑姐不是很想出汗，盡量不要進行逛街，遊樂園之類的活動；而伶伶姐覺得最近我有點胖了，不想讓我去餐館吃太多東西。至於我的話……我還是覺得只要和喜歡的人一起開心度過就好。\n所以領航，有想到今天要去哪裏玩了嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200802] = {id = 11200802, name = "百里默默", head = "12008", type = 5, title = "水族馆突击戰", txt = "唔……今年的生日，姐姐们格外安静。她们说今年要把选择的权力全权交给默默，不再做任何干涉。我知道的，其实是姐姐们自己都没拿定主意，所以把难题丢给了我。\n我确实有个一直想去的地方，只是一直没机会去，或者说姐姐们不让我去。\n那个地方就是“水族馆”。\n默默喜欢大海，更喜欢海里的动物。在水族馆里，能看到好多在海边看不到的鱼儿，可有意思了。\n但姐姐们却觉得水族馆太过无聊，所以一直阻拦我。既然这次把选择权交到了我手上，那我可要把握机会。\n……\n不管不管，说好了听默默的，那姐姐们就不准再有怨言！\n领航，我们现在就出发吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112009] = {id = 112009, name = "瑪利亞", head = "12009", type = 5, title = "孤獨的夜", txt = "近來可好，小弟弟。\n算起來我們已經有半年多沒有見面了吧，有沒有想我呀？\n 寫這份信倒也不是有什麼大事，只是今天好像是我的生日。\n 所謂生日，應該是值得慶祝的日子吧。可莉迪婭她們不知道去執行什麼任務了，雪鴞現在就留了我一人在，都沒人可以陪我開生日會了。\n這幾天卡佳的雪也是越下越大。在這樣寒冷寂寞的夜晚，不知哪位紳士可以給我一個溫暖的擁抱呢？小弟弟？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200901] = {id = 11200901, name = "瑪利亞", head = "12009", type = 5, title = "給我一個擁抱", txt = "很意外吧，已經很久沒有給小弟弟寫信了，上一次還是在一年之前。不多不少，正好一年。小弟弟應該明白是什麼意思吧。\n沒錯，就是姐姐我的生日。生日就該要生日禮物，我的生日禮物的話……\n真的好想，好想，好想要小弟弟一個大大的擁抱。\n但現在應該不行吧。領航的工作一定很忙碌的吧，從早到晚，既要處理原罪，又要管理駕駛員們，很辛苦吧。這時候給小弟弟添亂，可不是大姐姐該做的事，不過這可不代表我放棄了。\n小弟弟可要記著你欠我一個擁抱，等到下次見面，我再向你索取。\n來自年上系大姐姐充滿幽怨的致命擁抱，小弟弟可要做好準備哦。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200902] = {id = 11200902, name = "瑪利亞", head = "12009", type = 5, title = "久違的噩夢", txt = "做夢是什麼樣的感覺，姐姐已經快忘了。\n搞不好可能就是怕我徹底遺忘了做夢的感覺，在今天，也就是姐姐生日的凌晨，大姐姐久違地做了一個夢——還是一個噩夢。\n夢裡面，姐姐躺在冰天雪地裡，孤零零的，只有姐姐我一個人噢。\n明明只是一個夢，但那份冷意真的很真——結果醒來卻發現是自己把被子踢飛了，真的一點也不成熟。\n所以，為了安慰被噩夢嚇到的大姐姐，小弟弟能抽空來給姐姐過生日，給姐姐一個熱烈的擁抱嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112010] = {id = 112010, name = "冥火", head = "12010", type = 5, title = "標題就隨便起了！", txt = "真麻煩啊，又到了生日這天，“另一個我”又想為此慶祝了。明明其他節日她都安安靜靜的似乎沒有什麼想法，對於這種日子卻非常在乎呢。\n哦！我明白了，該不會…她是特意為了我才這麼認真吧？有這種心意居然也不直說，哈哈，真是讓老娘我哭笑不得！\n對了，“另一個我”還表示，她打算準備兩個蛋糕，不過我覺得只吃其中一個就足夠了，另一個嘛，就用來蛋糕大戰吧！哼哼，領航的話，敢來挑戰擁有無敗戰績的我嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201001] = {id = 11201001, name = "冥火", head = "12010", type = 5, title = "……", txt = "您好，收信人……應該是領航吧。那個我的話，其實我是……“冥火”，您就把我當作是“冥火”好了……\n其實，我想說的是……那個，今天是我的生日……我準備了蛋糕……所以，我想請領航您，那個……哦，我還買了一些水果，不知道領航喜不喜歡吃草莓……我想說的是，領航能不能……所以就是……\n唧唧歪歪的，老娘看不下去了。總之就是老娘生日到了，蛋糕有了，水果有了，什麼都有了，領航你來不來？一句話！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201002] = {id = 11201002, name = "冥火", head = "12010", type = 5, title = "兩个人都注意到的事情", txt = "今天早上一睜眼就在花叢環繞的牀上中醒來……看來在老娘的意識睡覺的時候，“另一个我”為此準備忙活了很久。\n特意為我設置的驚喜嗎……她似乎把這一天讓給了我，這是專門為我準備的生日禮物和驚喜……\n所以雖然覺得很麻煩……老娘也想要給她驚喜。\n我已經有一个絶妙的點子需要領航配合。\n她一定會驚訝的，在她醒來之後發現和領航睡在一起。\n但在那之前，讓我們先享受今天吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112011] = {id = 112011, name = "伽藍見", head = "12011", type = 5, title = "未知的書", txt = "我的“生日”不同於尋常理解的那樣，它實際上指“生還之日”。\n我很幸運，自己能在那場災難中倖存下來，成長至今，因此我的生日也多了一份獨特的意義，它即意味著命運無常，同時也象征某種希望。\n今天我想試著接觸些新鮮事物，我打算根據索書號在圖書館中尋找這樣一本書：其出版年月與附加編號合起來，顯示的種次號正好與我的誕生日期相同。雖然預料不到那會是怎樣的一本書，甚至連這種巧合是否存在也不得而知，但我還是想嘗試去尋找，然後將其讀完。\n領航如果也有興趣，就來一起翻閱那本命中註定的書籍吧？我會在我們常去的那家圖書館等你。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201101] = {id = 11201101, name = "伽藍見", head = "12011", type = 5, title = "海洋下的寶藏", txt = "時而洶湧澎湃，時而風平浪靜，有時衝動得像是被奪走獵物的母獅，層層迭起的波紋，要將人吞沒的波浪就是她張牙舞爪的模樣；有時像待嫁的姑娘，依偎在戀人的身旁輕聲細語訴說著藏在寶匣裡的秘密與情意。\n人人都知道海，但卻鮮有人嘗試過理解海。\n在翻開一本書之前，你無法斷定這本書會描繪怎樣一個故事。\n海也是如此，海是怎樣，海面之下又藏著怎樣的寶藏，只有接觸了它，你才能明白。\n領航，您有興趣與我去了解海……或者是了解我嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201102] = {id = 11201102, name = "伽藍見", head = "12011", type = 5, title = "齊聚一堂的日子", txt = "我之前提起過，“生日”對我的含義和尋常人不太一樣——不過，度過它的方式其實很平常。\n還在船上時，每年這時，大家會盡量安排好航線，然後聚在一起，在平靜的海面上分享一塊糕點。\n雖然有時候，大家只能在風雨交加的晚上聚在一起，有時端到桌上的東西則會變成一條魚，但，共聚一堂這點是從來不會變的。\n過去的我恐懼陸地，其實也有一部分是擔心這種聯系會因為離開海洋消失——真是個幼稚過頭的擔憂。\n有興趣來今年的聚會上露個臉嗎，領航？\n雖然只是沒那麼正式的遠程聚會，不過，想跟你見一面，聊聊天，是大家這兩年共同的願望。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112012] = {id = 112012, name = "茱莉亞", head = "12012", type = 5, title = "一則好消息還是壞消息呢？", txt = "哎呀好久不見，最近過得如何，***？\n啊！看來艾吉斯的遮罩字形檔更新了，在郵件內無法顯示那個詞呢。也罷，反正你肯定明白我對你的愛稱是什麼，能夠心領神會就好~\n回歸正題，我高貴的誕辰已至，僕從們精心準備的諸多道具總算該派上用場了。我猜，平時在艾吉斯日復一日指導訓練的枯燥時光是不是讓你有些乏味？現在，渾身顫抖著歡呼吧、嚎叫吧！\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201201] = {id = 11201201, name = "茱莉亞", head = "12012", type = 5, title = "你有赴約的勇氣嗎？", txt = "燕妮·羅斯，那個人要被我抓到多少次才肯放棄調查？真是連我都忍不住佩服她的勇氣了。\n不過，這一次她說是領航——是笨豬你讓她去調查的，說是要準備生日禮物什麼的……\n怎麼，連笨豬你也開始好奇我的出身了嗎？\n哼哼，如果你願意跪下來舔我的腳趾的話，我到不介意告訴笨豬你一些從來沒被公開過的秘密。\n今晚，我會在我的房間等你，可不許當膽小豬噢，領——航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201202] = {id = 11201202, name = "茱莉亞", head = "12012", type = 5, title = "讓她們見識一下我們的底蘊", txt = "***——呵，又來了，艾吉斯的屏蔽字庫還真是時靈時不靈的。這幫躲在後方的廢物難道只會在這種事情上下功夫嗎？\n算了，我可不想把寶貴的時間浪費在和他們較勁上。\n今天是我的生日，如果你忘了，你今晚就別想閉上眼了。\n我以“生日”為理由，借你的名義邀請了其他駕駛員來參加宴會。\n哼，如果是以我的名義，她們肯定沒有膽量赴約的。\n我要舉辦一個讓所有人都目瞪口呆的生日宴會，為此，需要你來協助我。\n就讓多瑙的駕駛員，見識一下我們“颶風突擊隊”的底蘊吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112013] = {id = 112013, name = "卡蓮", head = "12013", type = 5, title = "來自學生的問候以及......", txt = "老師，許久不見，甚是想念。\n今天是我的生日，原本想和同學一同出門到街上的餐館慶祝，但是撒哈拉正值雨季，路面都是積水，出門用餐多少有些不便。不得已只能留在宿舍用昨天晚飯留下的小蛋糕稍作慶祝。\n百無聊賴之下，忽想起老師。聽聞老師在薩爾一戰中擊敗了准罪級原罪取得大捷，正巧這學期有門原罪學的課程。不知老師最近是否有空，我想就有關准罪級的事向您討教些許。\n擇日不如撞日，不如我現在就去購買到多瑙的機票，老師意下如何呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201301] = {id = 11201301, name = "卡蓮", head = "12013", type = 5, title = "願英雄不朽", txt = "老師，請原諒我的打擾。\n今天是生日，我的生日，可不知怎的我第一個想到了您。或許是因為最近在研讀有關原罪戰鬥的資料，我在裏面看到了老師的身影，密密麻麻。參加了大大小小的戰鬥，從原罪腳下拯救了無以計數的人，老師您就是我一直以來所憧憬的“英雄”，一直都是。\n如果能和老師這樣的英雄人物分享生日的喜悅，那我也可以說一句死而無憾了。不，我不想死，也請老師在戰場上不要輕易地死去……\n是了，這就是我的生日願望，願所有為人類而戰的英雄們，在戰場上能克服萬難，有驚無險地活下去。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201302] = {id = 11201302, name = "卡蓮", head = "12013", type = 5, title = "不会永远是学生，也不会永远停留在原地", txt = "時間是始終向前的，不會有永恆不變的事物。對於現在，我們喜歡它，或者我們討厭它，它都會消失，成為我們的過去。\n這種道理，老師肯定早就明白了，但我是最近才知道的。\n契機是曾經照顧我的學姐從學校畢業了，而漸漸的，稱呼我為“學姐”的人多了起來。\n原來如此，我長大了，成為了別人的前輩了。\n可是，關於如何當別人的前輩，自己是否有好好的當一個榜樣，我沒有這方面的自信。\n老師，我想向你咨詢，咨詢如何成為一名可靠的，令人信賴的前輩。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112014] = {id = 112014, name = "西法麗斯", head = "12014", type = 5, title = "看見遠處閃光的星辰了嗎？", txt = "赤經06h45m08.9173s，赤緯-16d42m58.017s處的那顆星體又開始閃耀了。\n按他們所說，這代表著我生日的到來。\n我還記得，當我在地球上複生後，抬頭望去第一顆閃亮的星星。那是我見過最閃耀最美麗的星辰。如果沒有原罪，我一定會乘坐飛船去那裏旅行，只可惜現在不行。\n但是，其實星星的閃光並不都是好事，這往往代表著恒星的毀滅，也可能代表新星的誕生。死亡與新生在宇宙間總是同時出現，米狄爾在毀滅的同時是否也有新的星球誕生了呢？\n聽說地球人生日時有許願的傳統。那我的生日願望就是在有生之年能找到那顆在毀滅中重生的星辰。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201401] = {id = 11201401, name = "西法麗斯", head = "12014", type = 5, title = "奇妙的夢", txt = "昨夜，我做了個奇妙的夢。\n夢中的我，在天空中醒來，卻沒有感受到墜落感，反而像是在水裏一樣飄浮在空中。我的眼前是一顆神奇的行星，絕不是米狄爾，更不是地球。\n在那顆行星上我看到了很多不可思議的事物。我看到風在水中奔跑，紫色的花朵綻開出一片鳥群將雲朵捕食，遠處的山脈往東方緩慢蠕動，火山噴發出六條瀑布在近地軌道上交匯然後飛向宇宙深處……\n奇怪的是，明明眼前的一切都毫無邏輯但是我卻能從中感覺到快樂的情緒。似乎它們在為我祝福，慶祝某個重要日子的來臨。\n然而直到現在我都沒有想到什麼節日值得如此慶祝，不知領航是否清楚呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201402] = {id = 11201402, name = "西法麗斯", head = "12014", type = 5, title = "回家的路", txt = "昨天，一個坐標——恐怕是米狄爾的坐標——出現在了我的夢中。\n地球上的大家說過，夢裡看見的一切都是平日的所思所想。這一點，我們恐怕也是一樣的。\n但那個坐標，我想應該不是我的妄想。\n也許，當初我離開米狄爾時，它的坐標訊息留在了我的身體上，在多年後的今天，以夢的方式重新出現。\n或許，當原罪從這個宇宙中消失後，我們就能通過這個坐標，回到我們母星曾經存在的位置——我想和您一起，去確認米狄爾是否還存在。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201403] = {id = 11201403, name = "西法麗斯", head = "12014", type = 5, title = "被額外賦予的時間", txt = "過去的三年來，我不時會思考，地球人定下“生日”這個概念的動機是什麼。\n米狄爾人不會專門記錄“生命誕生的那天”。畢竟，我們從出生起就要踏上星途，在難分晝夜，連時間概念都會不斷變化的旅行中度過絕大部分人生。\n那次重生，讓我得知了這個需要標記的日子。地球人告訴我，這是“新生”，可我總覺得，這更像是一份來自你的，被額外賦予的時間。\n幾年下來，我慢慢理解了：生日的重點不是數字的堆積，而是有人記得你存在，並希望你繼續存在。\n謝謝你，領航。\n不只是因為禮物，也是因為你讓這段不再旅行的日子，有了一個足夠溫馨的錨點。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112015] = {id = 112015, name = "薇絲帕爾", head = "12015", type = 5, title = "於怡人秋景之下", txt = "多瑙的九月總是如此，秋風捎來些許涼意，也將落葉喬木染得絢麗惹眼。\n我尤為喜歡這種景色，不僅是因兒時讀過關於秋季女神的傳說，也因這份斑斕光景由諸多色彩編織而成，缺一不可。\n我同樣真切地希望著，在今晚的生日宴會上，無論新舊貴族還是平民百姓，都能擯棄成見、消除隔閡，一同享受豐收時節的美酒佳餚…或許這過於理想化了，但總有一天能夠抵達的目標，我得利用好每次機會邁出步伐。\n領航一定也能沉浸在那種氛圍中吧？我會保持優雅始終恭候，期待與您的見面。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201501] = {id = 11201501, name = "薇絲帕爾", head = "12015", type = 5, title = "請您傾聽", txt = "我總是會把目光著眼於未來，規劃並時刻調整著邁向未來的每一步，但在我目前的規劃中，還並沒有您的位置。\n將晚會的氤氳燈火暫留在遠方吧，僅在此時此刻，我想邀請您來到我的花園。\n也許有一天我們會站在彼此的對立面，但在我們的關係變得針鋒相對、劍拔弩張之前——還是讓我先表露這番心意為好。\n我的想法、念頭、心意，在這一刻存在過便足夠了，請您傾聽。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201502] = {id = 11201502, name = "薇絲帕爾", head = "12015", type = 5, title = "一次冒險", txt = "時光流轉，隨著暑氣在風中褪去，多瑙的金秋又到來了。\n……我本想這樣問候您的，但年年如此，我猜您應該也有些厭煩了？\n畢竟，您是整個艾吉斯最獨特的領航，曾多次拯救多瑙的英雄，繁文縟節就算不願意也會聽到很多吧？至少我是這麼猜測的，希望這個想法不會太失禮。\n至於原因，大概是作為每年生日都要大張旗鼓的“多瑙之花”，我也正處於類似的思緒之中？\n言歸正傳，關於這點，我有個相應的提案。\n今年的晚會，我縮短了自己需要在人前露面的時間。\n如果您和我一樣，對每年這天加倍投射過來的燈光有些厭倦的話，不如就一起去找個更靜謐的場所吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112016] = {id = 112016, name = "薩拉蒂", head = "12016", type = 5, title = "可以陪我去聽音樂會嗎？", txt = "今天晚上有空嗎？我手上有兩張音樂會的門票，想請領航一同去欣賞。\n時間是晚上六點，地點是在多瑙方舟附近的大歌劇院，離你那裡應該很近。\n這場音樂會我期待已久，因為這是該樂團今年的第一場演奏，也是他們新編曲的首次展示。還有那位被譽為“九州最年輕音樂家”的大師作為嘉賓出演。\n這實在太令人激動了，聽說許多音樂界的大亨都為了這音樂會的門票搶破了頭。要不是因為我生日，我也不可能能拿到這兩張門票。\n所以一定要珍惜這個機會哦，領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201601] = {id = 11201601, name = "薩拉蒂", head = "12016", type = 5, title = "生日之歌", txt = "今天領航在家嗎？我有一首歌想要讓領航聽聽。\n這是我最近寫的新歌，是我在一個黑夜流星劃過時偶然得到的。\n流星劃過夜空，燦爛的尾焰撕開寂靜，點亮了天空，也點亮了我的眼睛。短暫而燦爛，我仿佛聽到宇宙的琴弦被悄然撥動，其中最璀璨的音符就閃耀在我眼前。\n生命隨著音樂起舞，不禁令人聯想生命的出生與宇宙的誕生之間的關聯。生命是和宇宙同樣偉大的奇跡。我記下了那一刻的旋律和感動，一首與生命誕生有關的歌曲。\n而今天正是我的生日，我想沒有比這更合適的日子，來聆聽這首歌。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201602] = {id = 11201602, name = "薩拉蒂", head = "12016", type = 5, title = "I WANT U！", txt = "生日！生日！派對！派對！\n生日派對！\n生日派對的主角，就是——薩·拉·蒂，是我哦。\n我啊，早就想辦這樣一場熱鬧的生日音樂派對了！在海邊有著露天泳池的大別墅裏，大家一起唱歌，一起跳舞，一起喫生日蛋糕。\n從黑夜直到天明，永不停歇的狂歡節。\n現在，派對的大門已經開啓，參加的駕駛員們均已到場。\n唯一還未現身的就只有你了。\nI WANT YOU！領航！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112018] = {id = 112018, name = "希夏", head = "12018", type = 5, title = "約定之日", txt = "今天天氣不錯，要一起去散步嗎？最近我新發現了一家咖啡店，但他們家最好吃的不是咖啡而是炸豬排。很奇怪吧，咖啡店會賣炸豬排，不過味道是真的不錯。\n品嘗完咖啡和豬排後，我們可以去附近公園裏走走，曬曬太陽。不過天氣太熱，還是不要在室外待太久比較好，以免中暑。\n聽說今晚會舉行煙火大會，地點在一座我一直想參觀的斜拉索橋附近。\n既能欣賞煙花，又能研究大橋的結構，這樣兩全其美的好事竟然能讓我們遇到，可要好好珍惜。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201801] = {id = 11201801, name = "希夏", head = "12018", type = 5, title = "悠閑的選擇", txt = "認真回答我哦，領航。\n我以前的生日安排是不是太滿了點？\n我之前想著，畢竟是一年一次的日子嘛，自然要過得特別點。所以就下意識會把感興趣的事都堆過去。最後就變成了那個……“專業運動員日程表一樣的東西”？海因好像是這麼形容的。\n我覺得也沒那麼誇張啦。但是，太過匆忙確實不好。就像一周的旅行不能被壓進一個雙休一樣。為了生活情趣而做的安排如果反而成了負擔，那就是本末倒置了。\n所以，我想到一個很棒的點子。\n我把今年原本的生日計劃發給你，領航你從上面挑兩個，我們試著就用挑出來的事消磨一整天，怎麼樣？\n我很期待你的選擇哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112019] = {id = 112019, name = "凱特琳", head = "12019", type = 5, title = "狩獵", txt = "有空麼？陪我去郊外走走，就當是陪我過個生日。\n我聽說城郊有片森林最近野豬氾濫，襲擊了不少露營者，正好可以拿它們當靶子練練槍法。\n記得帶上你的槍，要是沒有的話，我可以借你幾杆。你是習慣用自動步槍還是狙擊槍？手槍的話我也有，但是特製的型號，威力很大，對你來說可能不太好操控。野豬皮糙肉厚只有威力加強過的手槍才能一槍斃命，如果你對自己的槍法有自信，也可以試試瞄準要害，一槍爆頭。\n有領航的協作，你我二人或許今天就能解決當地的生態問題。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201901] = {id = 11201901, name = "凱特琳", head = "12019", type = 5, title = "工作，以及放松", txt = "——我之前提起過嗎，領航？\n無論過去還是現在，都有不少人把我當成那種就算生日也只會對著工作表皺眉的人。\n眞是失禮的想法，我只是習慣把工作和放松關聯起來而已。\n太久不用的槍管會從內部開始生鏽，太久不實操的狙擊手會連呼吸的步調都忘掉，一味沉溺於放松會讓人連基本的工作都做不好——而我討厭以上的所有事。\n在慶生之前處理一些不至於神經緊繃的工作，再把省下的精力帶到後續的安排裏，我覺得這是最為合理的做法。\n——但話又說回來，適當參考一些來自他人的建議也是有意義的。\n綜上所述，今年的前置工作就由你挑選，意下如何？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112020] = {id = 112020, name = "弗洛維拉", head = "12020", type = 5, title = "生日~生日~地球上的生日~~", txt = "終於輪到我過生日了，好耶！\n遊樂園、電影院、滑雪場、遊輪、滑翔機……哇，想去的地方實在太多了。乾脆由領航來決定吧！\n這可是向外星人介紹地球特色的絕佳機會，一般的地球人想爭取都沒資格。領航要好好珍惜呀。\n——啊，放心放心，我打好招呼了。今天我的數據會導入一個便攜終端裏，領航你只需要帶著它，也就是帶著我，去體驗人類的生日活動就可以啦。很簡單的，對吧？\n那麼中午十二點不見不散。我在休息大廳等你。\n不要放我鴿子哦~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202001] = {id = 11202001, name = "弗洛維拉", head = "12020", type = 5, title = "讓地球為我的生日歡呼計畫", txt = "我想進行一場快速的旅行，以資訊為載體，不斷地穿梭在地球上，並在各處留下我的“痕跡”\n通過這些“痕跡”，在我身體的那一天操控世界上所有的設備播放“生日快樂歌”！\n領航你覺得這個想法怎麼樣？\n嗯……但是這樣可能會給大家帶來困擾，而且我想要領航陪我一起完成這場旅行……\n不如就這樣！我們在多瑙方舟內旅行吧，領航帶著我，走過那些熟悉的地方，嗯~這也是旅行的一種趣味！然後，生日那天的“生日快樂歌”當然是少不了的~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202002] = {id = 11202002, name = "弗洛維拉", head = "12020", type = 5, title = "來玩一場信息解密的遊戲吧", txt = "來找一找我藏在哪份信息裡吧？\n提示詞是：領航經常瀏覽的文件。我會化作一段顯眼的異常數據埋伏其中。\n嗯~可不許用通感作弊哦！除此之外什麼手段都能用！依靠其他駕駛員也可以，按照地球的話來說……手段大促銷~！駕駛員大解禁！\n來的人越多越好~！我準備了很多的小禮物~生日派對當然是越熱鬧越好啦！\n當然……還有單獨為領航準備的特別驚喜~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112021] = {id = 112021, name = "韶音", head = "12021", type = 5, title = "請柬", txt = "拜啟者：\n小滿已至，適逢本人生辰，原以為能平淡度之，與往年無二，然未料友人駁論，只得設宴以慶之。\n故此，恭候蒞臨。\n\n宴席詳情將以附件文本形式發送，望領航及時查收。\n\n\n備註：我就知道她會寫成這樣！還好在發送前成功攔截下來了……領航，韶音她其實超級無敵期待您來參加她的生日派對。除了您，她可沒有專門寫信邀請過其他人。所以您可一定要準時到場哦~ u{3000}\u{3000}by好心的澄練隊長", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202101] = {id = 11202101, name = "韶音", head = "12021", type = 5, title = "請柬", txt = "謹啟：\n敬啟者領航玉鑒\n澄練隊長曾告誡小女子：往日書信的“風格”對於【學宮】之外的人可能過於晦澀難懂。\n於是小女子已就此事反思，所以這次我嘗試直接在信紙上訴說的出我的“心情”。（不知“心情”一詞是否正確，如有用語錯誤，望海涵。）\n希望領航在小女子生日這天能參加由我與友人一同舉辦的宴席，小女子…期待著領航到來，如果領航來的話，我一定會很開心的……嗯，就是這樣。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202102] = {id = 11202102, name = "韶音", head = "12021", type = 5, title = "請柬", txt = "謹啟：\n敬啟者領航\n歲序更迭，又是小滿時節。\n由於先前出現被友人修飾行文的情況……所以不知，這些年，小女子的心意是否成功傳達到了領航那裏？\n總之，若因小女子不才，致文字無法完全承載思念，\n為謹慎起見，還望請領航今日務必親自到場確認。\n外界稱，今日為情志表達之良辰，小女子亦有一份心情想交付……不想通過書信，而是親口，\n所以……\n不知領航可願撥冗，陪我度過這生辰餘暉？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112022] = {id = 112022, name = "萊帕尼", head = "12022", type = 5, title = "路癡畢業", txt = "我迫不及待地想要與您分享一個好消息——我不再是個路癡了，因為我已經許下了生日願望。要驗證願望是否實現，唯一的辦法就只有親身試驗了。在您看到這封信件的時候，我已經在去往您那裏的路上了，沒有綁著卡洛琳，就只有我一個人。\n其實我是真的克服了路癡的毛病，在一個月之前我就從一個網路上的“習慣性迷路與方向感貧弱者互助會”中畢業了。我在裏面學習了很多課程，比如“太陽指向性錯誤實例展示”，“指南針指的不是南原理分析”以及“上北下南速記口訣”。\n我一定能到達您身邊，不會迷路！！！！！\n不過有件奇怪的事，我這裏的北極星好像是在東邊？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202201] = {id = 11202201, name = "萊帕尼", head = "12022", type = 5, title = "實現自己的生日願望", txt = "在生日的當天許下願望，這是世界人民的共識。\n因此，在今天，我也許下了自己的願望——希望原罪能從這個世界上一隻不剩的消失。\n我的願望已經許下，那麼接下來，就是去實現它的時候了。\n領航，您在一分鐘後，就會接到討伐原罪的合作請求。\n我的生日願望，需要您和我一起去實現它。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112023] = {id = 112023, name = "斯緹菈", head = "12023", type = 5, title = "生日的光景", txt = "領航……你有想過嗎？\n宇宙每一天的景象都是不一樣的，那麼自己出生那天的宇宙是一副怎樣的光景呢？\n我們已經很難親眼再見到那天的景象了，但我想……我們還可以去看當下的光景。\n領航……今晚，我想和你在天文台，一起見證自己生日時的宇宙景象。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202301] = {id = 11202301, name = "斯緹菈", head = "12023", type = 5, title = "宇宙一瞬", txt = "宇宙某處的一瞬間，星空某處的一瞬間，對於我們來說卻是盡其一生都無法窺探的永遠。\n如果你願意，也許我們可以一起走到露天的星空下，看看那些閃爍的星辰，聽聽孤獨世界中的寂靜。\n領航……是唯一一個和我一起在這片星空下度過生日的人，而星星在默默守護著我們。\n我想在這之後，當我仰望星空的時候，都會想像著你是否也在同一片星空下抬頭……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202302] = {id = 11202302, name = "斯緹菈", head = "12023", type = 5, title = "星星只是不斷地在轉動", txt = "今晚的夜空會格外晴朗，天氣預報説也許能看到流星呢。\n我知道有一个視野很好的地方，要和我一起去看星星嗎？以駕駛員與領航的身份，以老師和學生的身份……以天文愛好者的身份也可以。\n我想和領航再一次躺在同一片草地上，仰望著同一片星空，我……還有許許多多的話還想對你説。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112025] = {id = 112025, name = "菲琳", head = "12025", type = 5, title = "認真過好每一天", txt = "如果有人渾渾噩噩地度過了一整年，直到生日這天才想起來要好好對待自己，那這樣的人絕對是笨蛋，是比我還要不懂得照顧自己的笨蛋。\n人生的每一天都是一去不復返的，是獨一無二的，所以比起過好一年中的某一天，認認真真過好人生的每一天更加明智吧？\n總之，領航，我們一定不能成為這樣的人，竭盡全力去過好每一天吧！\nps：但是今天的生日蛋糕我已經準備好了，要來我家吃噢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202501] = {id = 11202501, name = "菲琳", head = "12025", type = 5, title = "關於新生活的報告", txt = "最近過得好嗎，領航？\n我這邊萬事順利哦！新環境相當不錯，我已经很久沒這麼有幹勁了，可以说新生活一切都好！\n我期待你的聯絡哦！\n\n【以下為後續資訊】\n好吧，上面的話有那麼一些是假的。\n第一研究室……我虽然整體都能適應啦，但在細微的地方嘛……\n“好擔心在科研人員面前說錯話！”“偶爾撞上以前復興部的同事好尷尬！”“新的駕駛員同伴看上去超不好搭話！”\n像這樣不著調的煩惱，我還是有的。\n本來想像往常一樣憋著算了，但一想到今天是自己的生日嘛……\n雖然多半只是些不痛不癢的牢騷，但領航你要是不介意，可以稍微陪我消解一下嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113000] = {id = 113000, name = "歐朵啦", head = "13000", type = 5, title = "睡覺覺", txt = "又到了我的生日…\n和以前一樣，我打算喝點牛奶就睡覺，除了想要長高，我沒有別的願望了…\n呼…似乎在出生以前，每個人就是一直在睡覺吧？所以今天睡很久很久也沒問題…沒有人會說什麼，因為是在慶祝嘛…\n這麼好的事，領航也要一起來嗎？我在夢中等你…", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300001] = {id = 11300001, name = "歐朵啦", head = "13000", type = 5, title = "繼續睡覺覺", txt = "醒了，發現又到生日這天了。\n去年的今天我好像是在睡夢中度過的吧，那今年就延續去年的傳統，繼續睡覺吧。\n生日願望……也和去年一樣是長高吧，雖然並不是很靈驗。一年的時間我的個子連一釐米都沒有增加。難道是沒有吹蠟燭的原因嗎？\n蛋糕、蠟燭，無論哪個都好麻煩。\n算了還是睡覺吧，在夢裏舉辦生日派對的話就，什麼都可以不用準備了……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300002] = {id = 11300002, name = "歐朵啦", head = "13000", type = 5, title = "晚安", txt = "為什麼大家會覺得賴床是不好的行為呢？\n明明睡覺是最幸福的事情。\n悲傷的事情，不好的事情，都會在睡夢中消失。\n賴床只是想要延續這種幸福的事情而已，為了追求幸福而採取的行為，哪裡不好啦。\n呼……總之，今年的生日，我也要好好睡覺。\n領航也是，不要熬夜啦，來和我一起睡覺吧，晚安。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300003] = {id = 11300003, name = "歐朵啦", head = "13000", type = 5, title = "醒來，還是…", txt = "唔……醒了。\n今天又是那個日子。\n去年的願望落空了。一點都沒長高，牛奶倒是喝了不少。\n其實我本來打算嘗試一下邀請大家，甚至還去看了看那些蠟燭……\n但一想到要忙碌很久，眼皮就又開始打架了。\n果然，我還是在夢裏度過吧。\n不過這次我稍微做了一點準備。\n我搬了一張新的沙發。\n在那張沙發上，我給領航留一半的位置。\n所以，當我的抱枕吧，領航，我總有預感，抱著你能做一個美夢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113001] = {id = 113001, name = "弗蘭卡", head = "13001", type = 5, title = "關於今天…", txt = "今天下班後，領航能來我的房間，參加一個小小的生日派對嗎？朱利烏斯學姐和查麗莎學姐她們也都會在，我還做了一個很大的蛋糕。\n嗯…其實我有點猶豫，到底要不要特地寫一封郵件，這樣好像顯得太正式，太疏遠了。我本來想在指揮室見到您時，像平時那樣自然地發出邀請，只是又覺得有些不好意思…可能，我是怕這樣會打擾到您工作，所以最後還是選擇發送郵件。\n然後…還有更多在信中寫不下的話、一時組織不好語言的話、連我自己也不確定的話…就等今晚的派對結束後再向您說吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300101] = {id = 11300101, name = "弗蘭卡", head = "13001", type = 5, title = "麻將大賽", txt = "明明只要在今天訓練時跟你說就可以了，為什麼還要特地發郵件……寫郵件的時候又不知不覺這麼想了。\n領航，今天是我的生日，但我決定今年要嘗試一次不一樣的慶生方式……\n您應該知道“麻將”吧？我在自己的房間裡準備了RX八口機，還叫上了查麗莎學姐和朱利烏斯學姐。\n對！我要要一整晚的麻將來度過生日……您要是不了解規則的話，我可以教您。您一定很快就能學會的！\n請您一定要來啊T_T！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300102] = {id = 11300102, name = "弗蘭卡", head = "13001", type = 5, title = "想要吃領航做的飯", txt = "忽然好想吃領航做的飯……某一天，我產生了這樣的想法。\n然後這個想法就像是無法根除的疾病一樣盤旋在我的腦子裏。\n還記得今年從海濱樂園回來之後，領航不是難得的露了一手嗎。\n那個時候我就覺得領航燒的菜有我家裏的味道，直到現在一直被我掛念著……\n嗯……我也並不是不會做菜，但是我做的菜……用簡單的話來說的話就是帶著“弗蘭卡的味道”，而領航做的飯則帶著“我喜歡的家的味道”\n所以……在今天請再做飯給我吃！就、就當是給的生日禮物……好嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300103] = {id = 11300103, name = "弗蘭卡", head = "13001", type = 5, title = "主菜", txt = "自從去年嘗過領航的料理後，我發現自己對其他食物的忍耐度下降了，這絕對是領航的錯。\n這一年裏我總是在想，那種味道到底是什麼。\n後來我發現，只要有你在的地方，空氣裏好像都帶著那種讓人心安的香氣。\n所以，從那天起，我認為像生日這樣的日子，哪怕只想再當一次領航的食客，都是非常令人幸福的事。\n當然，如果可以的話，我希望能一直擁有這個身份。\n領航能幫我實現這個願望嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113002] = {id = 113002, name = "蒂娜", head = "13002", type = 5, title = "一個不情之請", txt = "尊敬的領航閣下，克雷蒂亞家族最忠誠的女僕長，蒂娜·愛森向您致以問候。\n請原諒我的冒然來信，因為在執筆書寫此信之前，我已為家中兩位千金的熱忱所折服，耐心被消磨得幾近無存。一向我行我素的靜小姐暫且不論，就連矜持端莊的愛麗絲小姐似乎也心血來潮，想為一件無足掛齒的小事大設宴席。\n不瞞你說，今天正是我的生日，而這卻反倒給了兩位小姐一次違抗教導的機會。她們無視勸言，堅持讓廚師們準備用不盡的過量菜肴，稱想為我慶賀，殊不知我只願她們能更懂事。\n深知領航總對駕駛員管教有方，我誠邀閣下共赴晚宴，望一同商議小姐們的未來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300201] = {id = 11300201, name = "蒂娜", head = "13002", type = 5, title = "再一次的不情之請", txt = "尊敬的領航閣下，克雷蒂亞家族最忠誠的女僕長，蒂娜·愛森向您致以問候。\n請原諒我用了與上次一致的開頭，因為今年又遇到了同去年一樣的問題。\n在今天，我又迎來了我的生日，我原本想利用去年從您身上學來的經驗，安撫克雷蒂亞家族躁動的兩位小姐。\n但不同於去年，小姐們居然提出了遠足的建議……\n若是陪伴兩位小姐出行，照顧小姐的生活起居，那是我的本職，自然不足掛齒。可聽兩位小姐的意思是，這次遠足似乎是以我的意志作為主導……\n十分慚愧，這種對常人來說理所應當的事，對我來說居然是知識盲區。\n聽聞領航您始終以自己的情感與意志作為行動第一標准，所以還希望請您能不吝賜教，參與這一次的遠足。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300202] = {id = 11300202, name = "蒂娜", head = "13002", type = 5, title = "從事前準備入手", txt = "尊敬的領航閣下，克雷蒂亞家族最忠誠的女僕長，蒂娜·愛森向您致以問候。\n如上，雖然使用了與之前一致的開場方式，但您應該能注意到，這則消息的送達時間比以往要早上許多。\n之前，我無法對兩位小姐的行為做出合理的應對，以致總是臨陣徵求您的幫助，這讓我深感慚愧。為此，我決定從準備上做出改變。\n兩位小姐平日對您最為信任，若又有什麼與我的生日有關的構想，多半會在與您相處時透露一些端倪。\n請您仔細回想一下，以助我做好相應的準備。\n我深知這仍是為您增添負擔的行為，但除您以外，我確實缺少可以進行這方面交流的可靠之人，望您諒解。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113003] = {id = 113003, name = "克裡姆", head = "13003", type = 5, title = "緊急救援申請！", txt = "我接下來說的事，領航千萬不要害怕。\n本來今天是我的生日，所以昨天晚上我就將幾瓶珍藏的好酒拿出來給自己慶生。\n本來只是想小酌一番，但那些酒實在是太給勁了，一不小心就喝多睡了過去。在醒過來的時候我才發現，我竟然到多瑙了！還是巨大化狀態！\n私自巨大化是非常嚴重的事故。以這樣子回去的話一定會受罰的，但是在多瑙這邊認識的人只有領航一個。\n求求領航帶我回家吧！再用你的許可權編造個什麼任務幫我掩蓋一下就更好了。放心，我絕不會虧待領航，我那還有兩瓶九州的好酒…\n座標待會兒發你，我就在這等領航。\n一定要來哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300301] = {id = 11300301, name = "克裡姆", head = "13003", type = 5, title = "一起來過生日吧！", txt = "生日快樂，領航。\n沒錯，今天是生日，我的生日。但是以咱倆的關係，不必區分彼此。所以今天是我的生日也是你的生日，是克裏姆的生日也是領航的“生日”。\n既然是生日，不找個地方喝兩杯說不過去吧。但要說對多瑙的熟悉程度，我肯定是不如領航你，所以地方就領航來找吧，我不挑，只要能喝到酒，就算是去領航你的房間我也沒有意見，嘿嘿嘿。 \n千萬不要告訴伊莉雅！千萬不要告訴伊莉雅！千萬不要告訴伊莉雅！\n因為一些你我都知道的原因，最近伊莉雅管我喝酒管得很緊，我都沒敢提醒她今天是我生日。\n作為壽星，我今天肯定、一定、絕對要喝個爽！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300302] = {id = 11300302, name = "克裡姆", head = "13003", type = 5, title = "生日，但是禁酒", txt = "生日快樂——當領航你看到這封信的標題時，肯定會疑惑吧。\n“克裡姆居然要在生日的時候禁酒？是世界末日了嗎？”\n會產生諸如此類的想法也不奇怪吧！\n其實呢，不知道波琳娜從哪裡學到的奇怪知識，說“喜歡喝酒的大人都是壞人”\n為了給波琳娜樹立良好的形象，我最近打算戒酒了。\n雖然不知道能堅持多久，但至少從生日這天開始戒酒吧！\n領航，一起來陪我度過這無酒的生日宴會吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113004] = {id = 113004, name = "彩華", head = "13004", type = 5, title = "都是領航你的錯", txt = "在下本來只想安靜地度過自己的生日，但……\n華夢和華戀會知道在下生日……領航，是你告訴她們的吧？\n那對姐妹打算以此為由舉辦個比武大賽，已經鬧得人盡皆知了。\n好吧。她們能有心為在下慶生，在下確實很感動，但這並不意味著在下會同意切磋。和醫療官比武？還是讓在下單挑她們兩個人？真虧她們想得出來。\n來報名參加的人居然不少……已經可以預料到在下明天的工作量會有多可怕……\n現在撒謊說你記錯了，今天不是在下生日，還來得及嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300401] = {id = 11300401, name = "彩華", head = "13004", type = 5, title = "治療失眠的古方", txt = "今日又到了在下的生日，好在今年華夢華戀她們兩姐妹沒有弄什麼武道大會給在下增加不必要的工作。不過今天好像格外的安靜，從早上醒來後在下就沒有見到過任何人。大家都去哪裡了？\n在下突然想起之前領航說過最近睡眠不太好，在下偶然間獲得一個古方專治失眠，領航可以試試。不過該方子煎藥的步驟比較繁瑣，一言兩語說不太清，在下待會兒直接在通訊裏和領航細細講解吧。\n……\n為什麼領航的通訊器鈴聲會從我的櫃子裏傳出來？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300402] = {id = 11300402, name = "彩華", head = "13004", type = 5, title = "願世人不再被病痛折磨", txt = "領航，今日在下又來打擾了。沒錯，今日正是在下的生日，但今年的生日在下恐怕沒有時間慶祝了。\n也許是近日天氣乍寒的緣故，有不少人染上了風寒，來我這裏看診的病人絡繹不絕，說是忙得焦頭爛額的地步也不為過。不過在下並不覺勞累，只要能讓大家健康起來，在下再多辛苦一些也無妨。\n也正是這次看診的經歷，讓在下產生了個想法。等之後閒暇的時間，在下準備雲遊四方進行為期半年的義診。在下想要幫助更多的病人，解決他們的病痛。\n“願世人不再被病痛折磨。”，許下這樣願望的在下，實在是有點不知天高地厚了呢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113005] = {id = 113005, name = "熱尼亞", head = "13005", type = 5, title = "免費體檢", txt = "領航今年做過體檢了嗎？平時有那麼多需要操勞的事情，絕不能忽視自身的身體健康，每年都必須進行一次身體檢查。\n不過正常的體檢幾乎做不到全面徹底的清查，特別是那些症狀輕微的慢性問題……正好今天是我生日，我可以申請為期一天的生日假期。我就親自去你那兒一趟，給領航您進行全方位深入的免費體檢，從細胞層面解決您身體的健康問題。\n另外在我來之前，領航請保持空腹，以免攝入影響體檢結果的食物。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300501] = {id = 11300501, name = "熱尼亞", head = "13005", type = 5, title = "回訪", txt = "今天會去你那兒進行一次回訪，簡單地說就是通過面對面的交流以及我的經驗判斷您的身體恢復狀況。\n如果領航您有好好按照我的醫囑，改正原本那些錯誤的生活習慣的話……我還是以最壞的情況來調整預期吧。\n不過您也不必過於擔心，亞健康是現代人的通病，而比起身體上的病痛，內心的疾病或許更加致命。\n這次我會通過心理學的治療方式，探索您的內心，看看您心中是否有著需要填補的裂縫。\n過，話雖如此，實際上我才是那個需要填補心靈的患者。\n今天是我的生日。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300502] = {id = 11300502, name = "熱尼亞", head = "13005", type = 5, title = "二度問診", txt = "如果領航對日曆還有概念的話，應該知道今天是我的生日。\n郵件不是爲了向你討要什麼。只是你也知道，我習慣將這天看作定期體檢的節點\n——去評估某個總是把自己弄得傷痕累累的傢伙，最近有沒有好好聽從我的醫囑。\n暴風雪還在外面肆虐，冷得讓人想要放棄。\n但唯獨當我的思緒落在你身上時，我似乎擁有了抵禦寒冷的意志。\n我想起曾問你，你究竟爲什麼而戰。現在看來，比起探尋答案，我的身體已經先一步做出了選擇。\n在任務結束後，我會去你那兒進行一次體檢。希望到時候，你能以自己的健康身體指標，作爲贈予我生日的禮物。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113006] = {id = 113006, name = "瑩草", head = "13006", type = 5, title = "期待你的到訪", txt = "哎呀呀，都忙忘了，今天是我的生日呢。還多虧了領航的來電祝福，才想起來這回事。\n提醒心紙她們買蛋糕的，也是領航你吧？謝謝啦~\n不過……老實交代，“插多少根蠟燭就代表我有多少歲”的邏輯，是不是你教花語的？還讓她注意觀察，數清楚後向你彙報……領航，看來有些事情需要再當面向你強調一遍。\n別擔心，不會讓你跪坐一整晚，畢竟我也不是什麼魔鬼。在天亮前會放你回去睡覺的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300601] = {id = 11300601, name = "瑩草", head = "13006", type = 5, title = "又過去一年了呀", txt = "年輕的時候，生日總是伴隨喜悅，但隨著時間流逝，生日的含義也就變了——等到了生日這一天後，心裡面只會想：“怎麼又過去一年了？”\n咳咳，一不小心又把心裡話說出來了。真是的，現在可不是宣洩負情緒的時候！\n領航，今年的生日，我想和你過——只有你和我，這種簡單的請求，你一定會滿足小瑩草的吧~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300602] = {id = 11300602, name = "瑩草", head = "13006", type = 5, title = "大家都很忙……忙點好……", txt = "今年……心經社正在被更多的人逐漸接納。\n花語和心紙忙著在各地進行活動指引著迷途的羔羊，星井的占卜屋外也排起了長隊，真是的，她竟然在巫女的神社旁邊建了新的占卜屋，下次領航過來一定要幫我好好地批評她！\n大家的生活都步入正軌了，好忙啊……\n忙啊……忙點好……\n但是……大家是不是忘了……今天是小瑩草的生日哦？\n我也想要被大家團團圍住像小孩子那樣被慶祝生日快樂——而不是在生日當天一個人工作結束後孤零零地回到家裏——！\n領航能來陪我嗎，至少兩人一起也可以……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113007] = {id = 113007, name = "T型", head = "13007", type = 5, title = "事件編號0518", txt = "事件編號0518，系統載入中……\n人格邏輯檢測——通過。\n人格穩定性檢測——通過。\n思維內容生成中……\n\n“人類出生的那一天被稱作生日，此後每一個自然年中的相同月份和日期，人類會為了慶祝生日而舉行儀式。\n5月18日，T型的出廠日期，我是不是也應該進行慶祝儀式？\n錯誤，T型機甲無法食用人類的食物。\n更正，慶祝生日並不只限於進食行為，更重要的是和心裏想著的那個人類分享生日快樂。\n我心中想著的那個人……”\n\n新任務生成中……\n任務目標：分享生日的快樂。\n第一步行動——找到領航。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300701] = {id = 11300701, name = "T型", head = "13007", type = 5, title = "事件編號0518-2", txt = "關於“生日慶典”的補充觀察報告\n今日是T型的生日。按照人類習俗，T型應該接受祝福。\n但我更想送領航一份禮物。\n於是我用三個月，把領航每次呼喚我時的聲紋波動，編譯成了一首旋律。\n檔在終端桌面“系統更新日誌”裏。\n不是系統日誌。是生日快樂歌。給領航的。\n邏輯矛盾：過生日的人是我，送禮物的也是我。但根據推演，這樣做我的快樂指數會增長。\n——所以，現在我可以去找你了嗎？我想親耳聽你播放它。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113008] = {id = 113008, name = "伊莎貝拉", head = "13008", type = 5, title = "命運之輪轉動的日子", txt = "在這一天，我誕生了。\n在這一天，屬於我的命運之輪開始了轉動。\n人作為人而誕生，卻要花費一半的時光的時間去尋找自己作為人誕生的意義。\n我很幸運，在我出生時，我便知道了自己的命運。\n我將會用我的一生去踐行這個命運。\n領航，您願意和我攜手創造出未被見證過的未來嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300801] = {id = 11300801, name = "伊莎貝拉", head = "13008", type = 5, title = "預知夢……", txt = "做了噩夢，夢見我變成了貪得無厭的女人。\n竟然在生日這一天做這樣的夢，難道……是神明給我的啓示嗎？\n神明在警示我如果不加以控制心中的貪婪就會變成那樣的人……？\n實在是确确實實的噩夢……本來我還想在生日這天和領航一起過，但想要一个人霸占領航也是貪婪的行爲呢。我可是被上天賦予特殊使命的人……\n……\n但偶爾，一年一次的要求難道也不行嗎……就連這也不被允許嗎……\n我很困擾……希望能得到領航的幫助……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113009] = {id = 113009, name = "艾伊瓦蒂", head = "13009", type = 5, title = "值得紀念的一天", txt = "貴安，尊敬的領航。\n今天是我獲得新身軀後，地球正好公轉一周的日子，根據這顆行星的習俗——即是生日。\n米狄爾人自出生起就會離鄉，啟程進行漫長的星際之旅，因此我們並未孕育出這種慶生文化，畢竟在黑暗無垠的宇宙中漂泊時，母星的公轉週期自然無需留戀。\n但是，米狄爾的毀滅，以及在地球上生活的時光，讓我開始對這種紀念與慶祝感到了一種浪漫。在無常的命運中，我們或許是該借某些恒久不變的事物來錨定生活的意義。\n所以我不由得決定，倘若將來有機會重建米狄爾，我會將這一文化引入我們的文明…而在那之前，領航能否陪我一同度過這天呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300901] = {id = 11300901, name = "艾伊瓦蒂", head = "13009", type = 5, title = "刻下一處記號", txt = "貴安，尊敬的領航。\n不瞞您說，在我們忙忙碌碌於生活中打轉之際，地球這顆行星也再度完成了一次公轉週期，換句話說，我的生日又來臨了。\n出身於習俗與地球截然迥異的米狄爾星，在此每度一年，我都更能感受到生日這一文化的意義與重量，因為那是時間的重量，是再怎樣巨大的恆星也無法掙脫的引力。\n米狄爾人不畏死亡，但我們害怕時間，因此，我會藉著誕生之日這一節點，在永無止境的時間上畫上一處小小的記號，標誌著我們對於世界的小小勝利。領航願意陪我一同進行這美妙的儀式嗎？我會在自己的房間靜候您的到來。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300902] = {id = 11300902, name = "艾伊瓦蒂", head = "13009", type = 5, title = "世界的盡頭，或者旅程的結束", txt = "在來地球之前，我們從未對“時間”有過實際的概念。\n我們曾在無垠的宇宙中旅行，不知“時間”為何物的我們一度以為我們會將這趟旅行永恆地進行下去。\n來地球之後，我才發現，“時間”竟是如此寶貴且短暫的事物。\n一種前所未有的感覺——那是對“時間”的焦慮感——從心中滋生，“時間”教會了要珍惜自己擁有的一切。\n我要珍惜當下的每一個與你共處的日子，直到世界的盡頭到來，或是旅途的結束之日。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300903] = {id = 11300903, name = "艾伊瓦蒂", head = "13009", type = 5, title = "生日的慣性", txt = "貴安，領航。\n如你所見，今日是我的生日。似乎，我早已習慣了這一切——在這顆星球每個公轉週期的固定時刻舉行紀念活動，包括給領航你寄來這樣一封內容簡短的信件。\n我將此稱作“生日的慣性”，就是在生日這天，總有一種衝動想和領航分享，哪怕只是些無關緊要的小事。似乎只要如此，我們的時間便能化作無限，我們的人生也會恆久地延伸下去。\n哪怕過去百年千年，我們依然能夠在生日來臨的時候，互相送去各自的祝福。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113010] = {id = 113010, name = "渠", head = "13010", type = 5, title = "又到了這一天了", txt = "又到了生日這一天了，這也就表示“年齡”又往上加了一個數字。\n唉，領航你知道嗎，埃塔星上一年的時長是地球一年的好幾倍。本來只用過一次的生日在地球上要過好幾次。\n你肯定要奇怪——“多過幾次生日難道不是好事嗎？”對於別人來說或許是這樣，但是看著年齡以原來幾倍的速度增加的感覺真是太糟心了。\n當然這不是最重要的，我真正擔心的其實是領航你。我們種族的壽命是地球人的好幾倍。我的年齡增長也就是領航的年齡增長，那總有一天領航的生命會先一步到達盡頭。\n我…還沒做好接受那一天的準備。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301001] = {id = 11301001, name = "渠", head = "13010", type = 5, title = "想與你一起……", txt = "不知不覺又是生日了。\n領航你可以想像這種感覺嗎？昨天剛慶祝完生日，等到明天卻立刻又要舉辦生日會。在到地球的前幾個地球年裡這種感覺特別明顯，地球的日升日落，時光飛逝，直到現在還會讓我恍惚。\n不過或許也是待得久了，最近這種時間上的脫離感減弱了許多，就連毛髮的生長速度好像也快了很多，好像我的身體比我的精神先一步適應了地球的公轉週期。我有一種感覺，我的時間似乎正在和領航慢慢對齊，我擔心的那件事或許不會發生了……既然如此，那今年的生日願望就這樣許吧——\n“我希望在不遠的未來中，我能和領航攜手一起慢慢變老。”", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301002] = {id = 11301002, name = "渠", head = "13010", type = 5, title = "為了每年都會有的日子留下美好回憶吧", txt = "是嗎？今天又是我的生日嗎？\n直至今日，我還是不能很好地適應地球年……時間的流逝速度在我的主觀感受中變得越來越快。\n但或許這也不是什麼壞事，至少這意味著我和領航又度過了愉快的一年，這份“積累感”帶來的快樂是實打實的。\n那麼，今年的生日，領航也會和我一起創造美好的回憶吧？\n等我們多年以後都成了老人家後，一定會懷念今天的時光的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113011] = {id = 113011, name = "梅莉雅", head = "13011", type = 5, title = "纯洁的圣女降临之日", txt = "呵呵呵，领航，你是否思考过这样的一个问题。\n作为被“人”选中而成为“神的代表”的“纯洁圣女”，能否拥有自己的生日。\n那么就让心怀慈悲的我解答你心中的疑惑吧，答案是否定的。\n对于愚昧的大众而言，圣女只需是完美而无暇的。\n对于教会而言，圣女必须是可控的……说到这里你也应该能猜到了，无论是贫民窟的梅莉雅还是作为圣女的梅莉雅，在记事起就没有被庆祝过降生。\n所以，我决定用这份可怜的过往来要挟你，呵呵，你就尽情散发你多余同情心来帮我解解闷吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301101] = {id = 11301101, name = "梅莉雅", head = "13011", type = 5, title = "聖女的假日", txt = "想必您一定也是了解我的，對於我來說，“聖女”更多時候只是意味著一個維持生計——保持表面上光鮮亮麗生活的工作。\n就工作而言，“聖女”是一份不錯的差事，如果對外招募“聖女候選人”的話，恐怕隊伍能夠排從珀因雷德的西區排到東區吧。\n但工作始終是工作，就算它再怎麼舒適，工作也不是休息。\n即使是聖女，也是需要假期的，更何況，今天是我一年一度的生日。\n如果我借生日為由，邀請你來與我——珀因雷德的聖女——來遊山玩水，體驗珀因雷德的風土人情，你會答應嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113012] = {id = 113012, name = "多蘿西", head = "13012", type = 5, title = "猜猜占卜結果？", txt = "今天是魔女小姐多蘿西的生日~所以我特地為自己進行了塔羅牌占卜，翻到的牌可讓我大吃一驚哦，你知道是什麼嗎？是正位的戀人！\n迄今為止我已度過了成百上千次生日，翻到這種結果卻還是第一次，難道本魔女小姐的戀愛運終於要來了？由於感覺今天的占卜手感不錯，我又趁熱打鐵給領航你也占卜了一次，而結果——依然是正位的戀人！\n這樣簡直就已經是命中註定了吧？是個人的力量與意志所無法違抗的，命運的安排哦！領航，今晚我們就見一面吧？就當是為了檢驗我的占卜結果是否依然準確，如何？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301201] = {id = 11301201, name = "多蘿西", head = "13012", type = 5, title = "魔女小姐的生日？", txt = "魔女小姐多蘿西的第一千不知道多少次的生日，就在今天哦~\n但實際上啊——對於多蘿西小姐這種活了不知道多少年卻始終宅在家裏的宅宅魔女來說，真正能稱得上是【過生日】的日子可是少之又少。\n嗯~也許只有在需要確認自己的存在的時候，有點悲傷懷疑自己的時候，想讓自己打起精神的時候，我才會稍微過一過生日吧~\n啊~雖然上面說了這麼多，不過最近發現~過生日還是相當有趣的~所以我占卜了一下，占卜的結果說今天要和領航一起過最好~\n那麼魔女多蘿西馬上就到你的身邊，待著別動~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301202] = {id = 11301202, name = "多蘿西", head = "13012", type = 5, title = "最偉大的（且有點想你的）魔女", txt = "領航相信「必然的相遇」嗎？我預見到，在今天滿月的夜晚，你會來到我的身邊——我為你預畱了最好的位置，我們可以一起見證我用魔法重塑的過去星空。\n當然，最重要的是——那天是我的生日。\n我還有好多話想問你，比如我想去月亮上看看……又或者，你想不想看看勇者的塔羅牌在現實中的樣子？\n不要遲到，也不要帶什麼禮物。你能來，就是對我「永葆靑春」的魔法最好的加持。\n如果你來晚了，我就只好用傳送魔法把你直接抓過來了哦~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113017] = {id = 113017, name = "九十九環", head = "13017", type = 5, title = "偷偷再過一次生日吧！", txt = "親愛的！猜猜今天是什麼日子~\n嗯，不過看到這份郵件的時候就應該已經被劇透了謎底了吧——今天是我的生日。早在好多天之前我就期待著今天，當然也做足了準備！\n雖說有各種各樣的計畫……本來決定今天要和親愛的好好地度過一場浪漫、特殊的只有我們兩人的一天的……嗯，不過明明我沒有和任何人提起卻還是收到了大家禮物，只能啟動另一套計畫了。\n我打算在下午的時候邀請大家來參加我的生日聚會，我已經提前看過“未來”了，不會有原罪在那個時間點入侵的。\n然後，然後，我和親愛的兩個人的約會就放到晚上，讓我偷偷再過一場生日吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301701] = {id = 11301701, name = "九十九環", head = "13017", type = 5, title = "親愛的！親愛的！親愛的！", txt = "親愛的還記得今天是什麼日子嗎？\n提示一下……和我有關。既不是結婚紀念日，也不是交往紀念日……更不是第一次見面的紀念日……我相信親愛的一定會記得的！\n那麼……我們就在第一次見到的那個地方集合吧？\n今天只有躲在那個地方才不會有人來打擾我們，也不會對其他人造成困擾……\n我們就兩個人悄悄地享受二人時光吧~（ps：我已經看過了，今天不會有原罪入侵，所以待多久都沒有問題！）", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113019] = {id = 113019, name = "朝霧", head = "13019", type = 5, title = "您會答應嗎？", txt = "過去在“學宮”的時候，生日當天我都會找一個安靜的地方，將所有的事情都暫時放下，享受讀書的樂趣。\n離開“學宮”之後，我偶爾也會懷念那時候的日子。\n但人……總不能一直停留在過去吧？戴罪之人……更應該追求進步，不是嗎？\n而且，生日要是也一整天待在家裡，澄練隊長也會有意見的\n……所以，小女子有一個異想天開的想法……\n就是，今年的生日，我想待在領航身邊……您會答應嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301901] = {id = 11301901, name = "朝霧", head = "13019", type = 5, title = "幻想著過生日也不錯", txt = "我知道領航會很忙，也知道這封郵件一定會打擾到您……如果真的打擾到您了那就請當作沒有看過我這封信吧。\n順便去洗一洗眼睛也許會更好，啊……還有拿了信封的時候一定觸摸過信紙了吧，雖然我在寫的時候已經對自己的全身進行過消毒，也戴著生化服寫了這封信……\n我想著如果碰到我這種罪人的信的話您一定會受不了的……不對是我一定會受不了的，竟然玷污了您……死罪……\n不過……不過……我直到現在還幻想著您會出現陪我過生日……我真該死……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301902] = {id = 11301902, name = "朝霧", head = "13019", type = 5, title = "認罪書", txt = "我有罪，明明每天早上訓練的時候都已經能見到領航了……明明已經每天都能見面了……在戰斗的時候偶爾還和領航並肩作戰……喫飯的時候偶爾也能坐在角落遠遠地看到領航……\n明明這樣就好了……對於犯了下罪的我來説……這樣就好了……\n但在今天到來的時候還是忍不住想著……要是領航也能爲我慶祝就好了。\n我眞該死……得到了很多卻還貪婪著更多……\n我的罪名又增多了……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113020] = {id = 113020, name = "梅貝爾·伊司", head = "13020", type = 5, title = "來做個約定吧", txt = "剛才在辦公室裏看到了領航同學準備的生日禮物，我很喜歡，謝謝。但如果能親手、當面收到它，我會更高興哦。\n不如來做個約定吧：明年我負責準備咖啡和點心，領航同學只需赴約即可。畢竟相較於禮物，我更想聽你說一聲“生日快樂”——當然，是要當面說。不許再像今年這樣只是電話裏祝福一句。\n對了，你送的這件睡裙，質地做工都非常不錯，穿上後就讓人很……嗚哇，差點又睡過去了。好險好險。我是想問問，領航同學在哪兒買到它的？能分享一下店鋪名字、地址還有聯繫方式嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302001] = {id = 11302001, name = "梅貝爾·伊司", head = "13020", type = 5, title = "何時赴約呢？", txt = "我正在準備上好的薩哈拉原產咖啡與多瑙式甜點，不知道領航什麼時候能到？沒有催促的意思，只是我很容易一不小心就睡著，會錯過迎接你的時機，如果發生那種情況，還請見諒啦。備用鑰匙依舊藏在老地方，萬一來時敲門沒反應，直接進來就好。然後領航可能會見到我衣衫不整倒在地上？嗜睡症就是會這麼突然地發作，沒辦法嘛，只能請領航到時候幫忙把我抱上床就好，生日當天我可不想一直睡在地板上，還是靠在你身上比較舒服~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302002] = {id = 11302002, name = "梅貝爾·伊司", head = "13020", type = 5, title = "生日不是假日", txt = "我本來想像過去那樣，為領航同學準備醇香的咖啡與能用甜膩填滿虛無感的多瑙甜點，不過——真是失算了呢。\n雖然今天是我的生日，但卻不是薩哈拉的節假日。\n不巧的是，今天有一場麻煩的學術會議。\n雖然可以用“發作性嗜睡症”來逃掉，但就算逃了今天，也逃不了明天。\n所以，我有一個主意——領航同學也來參加這場會議吧？安心，你可以不用發言的。\n但是呢~我要是突然睡著了，你得擔起帶我離場的重任。\n帶去哪呢？那個時候的我已經睡著了，只能由你來決定了，領航同學~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302003] = {id = 11302003, name = "梅貝爾·伊司", head = "13020", type = 5, title = "睡衣派對的約定", txt = "我正在籌備一場生日派對，地點定在我自己的房間，著裝要求是睡衣。沒錯，這是一場睡衣派對，爲了隨時倒下就能睡。\n你肯定很意外，甚至會有“梅貝爾竟然會組織這樣的活動”類似的困惑。實際上當這個想法出現在我的構思中時，我自己都感覺不可思議。\n但從存在主義上來說，這或許是我本真的覺醒。\n不過尷尬的是，名單擬了半天，只寫了你的名字。我的內心似乎拒絕更多人蔘加。只有兩個人的派對……應該說是約會更加貼切。如果你願意參加的話，那就帶上你的睡衣來我房間。我也會穿上常穿的睡衣，在房間裏等你。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113013] = {id = 113013, name = "芙露露", head = "13013", type = 5, title = "最喜歡月冕的大家了喵", txt = "今天是芙露露的生日喵~早上是吉雅叫芙露露起床的。吉雅身上的味道好好聞喵，和領航很像……\n然後斯卡蒂拿了好大一幅畫進來，上面畫著月冕的大家，還有領航和吉雅。右下角的祝福詞是領航寫的吧？芙露露一眼就認出來了喵，嘿嘿。\n莉莉絲幫忙把畫掛在了芙露露床尾的牆上，這樣芙露露每天起床就可以看見大家。\n——喵！還有還有，在休息大廳等領航的時候，摩根勒菲隊長為芙露露表演了好多魔術喵！都超有意思喵！錯過的領航好可憐喵……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301301] = {id = 11301301, name = "芙露露", head = "13013", type = 5, title = "喵", txt = "領航要和芙露露一起去照顧小貓咪們嗎喵？\n就在多瑙的海岸邊上，是芙露露平時經常去的地方喵。\n因為今天是芙露露的生日，中午想要和一直陪伴著我的貓咪們一起過喵。\n然後晚上的時候，月冕的大家幫忙準備了生日宴會喵，芙露露現在要負責把大家都找到來一起吃蛋糕喵。\n蛋糕很好吃，希望大家都能吃到喵。\n如果玩鬧得太晚的話，摩根勒菲隊長說領航可以住下來，第二天再回去喵。\n芙露露希望領航住下來喵。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301302] = {id = 11301302, name = "芙露露", head = "13013", type = 5, title = "夢到了奇怪的東西喵~", txt = "昨天和領航分別之後，芙露露因為太累了就睡覺了喵~\n結果，芙露露做了一個奇怪的夢。\n夢裡面的芙露露好像長大了，變成像隊長那樣的淑女了喵，不過，變成大人的芙露露好像一點也不開心，芙露露能感受到噢，那個芙露露好像非常非常悲傷。\n芙露露討厭這個夢，隊長說可能是領航的影響才做了這麼奇怪的夢。\n作為補償，領航要陪芙露露在今天玩一整天喵！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113014] = {id = 113014, name = "莫莫卡", head = "13014", type = 5, title = "雪之形", txt = "領航知道雪花有幾種形狀嗎？\n今天我在雪地散步的時候，天空飄起了細雪，一團雪花恰巧落在了我的鼻尖。由於天氣寒冷，我的體溫又低於常人，雪花並沒有第一時間融化成水，讓我有時間慢慢觀賞它們的形狀。\n那是一團六邊形的聚集物，是單片雪花們的集合體。其中每一片雪花在保持六邊形的輪廓之外又有著各自不同的延伸，通過彼此的間隙交織在一起。光線在間隙間跳動，變幻出不同的色彩，令我心潮澎湃。\n每一片雪花都如此相同又如此不同，我不禁想到了遠在異鄉的領航，您與我或許也是兩片相似又各異的雪花。我們或許也能交織出絢爛的光彩。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301401] = {id = 11301401, name = "莫莫卡", head = "13014", type = 5, title = "凍成冰的奶油比石頭還要堅硬", txt = "昨日夜中，大雪再次不請自來，待到早晨被刺眼的光叫醒時才發現，窗戶已經被雪和冰凍結得紋絲不動，堅固無比。\n同樣變得堅固無比的還有我昨天料理的一大碗奶油。原本我打算用它們來製作奶油冰激淩，沒想到昨夜的大雪幫我省去了冷凍的過程。就是不知道這樣子做出的奶油冰激淩味道會如何，現在的它比石頭還要堅硬，連刀叉都難以撼動，根本無法品嘗。\n於是我將它打包寄送給領航，讓您幫我品鑒。希望在經曆過跨越山河的旅途後，這份奶油冰激淩可以褪去堅硬的自我，以更軟糯的質感呈現在您面前。屆時我也想知道領航對於這份奶油冰激淩究竟是什麼感覺。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301402] = {id = 11301402, name = "莫莫卡", head = "13014", type = 5, title = "討厭冬天了……", txt = "今早，我偶然撿到了一只渾身雪白的小狐狸。我發現它的時候，它正躲在樹叢裏，瑟瑟發抖。它的身體十分虛弱，看見我的第一眼就想逃跑卻連站起來的力氣都沒有。\n今年的冬天格外寒冷且漫長，它想必已經很久沒有進食了。我不忍心把它畱在雪地裏，便抱回了家，給它取名“小雪”。餧了點温牛嬭後，小雪瞬間就有了精神，也不再怕我，此刻正安靜地靠在我腿邊休憩。\n然而我現在卻有些犯難。基地有規定不準養寵物，可要是放歸自然，我又擔心它熬不過這个冬天。今天是我生日，或許我能以此爲借口畱下小雪。\n要是沒有積雪就好了……我好像頭一回如此討厭冬天。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113015] = {id = 113015, name = "莉娜", head = "13015", type = 5, title = "要是能順便打擊一下罪犯就好了", txt = "好久不見~Boy~\n我就長話短說了，今天是我的生日，我想佔用你今天的時間一起幹一些開心的事情。“大概在這一天可以不用去當英雄吧~”雖然這麼說有點不爭氣不嚴格不英雄，但我就是這麼想的~\n明白了的話就趕緊收拾收拾東西，我準備把我摩托開過來，你就坐我的後邊，咱倆一起去市區上找點樂子~\n當然記得帶上武器和護具，萬一，我是說萬一在便衣出行的時候遇到了不義之事，我們該出手時就要出手。雖然我想多瑙的市區不至於發生這種事情，但是有備無患~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301501] = {id = 11301501, name = "莉娜", head = "13015", type = 5, title = "超級英雄協會的建立紀念日", txt = "哈嘍~Boy~\n超級英雄協會建立的紀念日到了，雖然到目前爲止的成員還只有的我和你，不過這並不影響我雀躍地想要慶祝的心情。\n你肯定想問爲什麽我的生日是協會建成的紀念日對吧？\n哈哈，如果要講這件事的話一封郵件可完全不够，讓我們一邊開著摩託一邊回憶這件事吧。\n記得準備好你的假面，二號。\n請仔細聆聽周圍的聲音吧，如果聽見引擎的轟鳴聲，那就是我在呼喚著你！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113018] = {id = 113018, name = "密托希瓦", head = "13018", type = 5, title = "請保持靜默", txt = "今天早上我接收到了一個神秘的資訊，內容是“生日優惠！遊樂場雙人票半價！”\n很可疑吧，我從沒告訴過任何人生日！除了註冊商場會員的時候……\n這條之外，還有“電影院生日折扣”“甜品生日免費送”等等。以我的經驗，這很可能是個通訊陷阱。這在宇宙航行中很常見，用一段虛假的通訊把空間旅人騙到陌生星域然後……\n我想請領航一起去調查，揪出幕後黑手。為了不打草驚蛇，就我們兩個人悄悄行動，先調查遊樂場、電影院，最後是那個餐廳。免費甜品？太可疑了吧。\n記住一定要保持靜默，千萬不要告訴別人，就我們兩個人悄悄地，悄悄地……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301801] = {id = 11301801, name = "密托希瓦", head = "13018", type = 5, title = "··· - - -···", txt = "今早又收到了那些商店的訊息，我才知道原來生日又到了。\n想到去年和領航一同進行的偵查行動，才發覺已經有很久沒有和領航聯繫過了。\n在宇宙旅行的時候，感覺星球間的距離好近，有修米婭號想去哪裡都可以。來到地球之後卻覺得地球好大，明明我們之間的距離都不超過一光年卻不能總是見面。\n領航，我想你了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301802] = {id = 11301802, name = "密托希瓦", head = "13018", type = 5, title = "想發出聲音", txt = "聽說如果一個人長久不說話，那麼相應的器官就會因為“不被需要了”而逐漸退化。\n所以我也想偶爾練習一下發出聲音。\n我的聲音變得怎麼樣了？會不會很奇怪，很生硬？\n這就是我現在困擾的事情，所以我想要邀請領航來聽一聽我的聲音，可以的話之後每年的生日也來傾聽我的聲音。\n這是我們之間的秘密！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113021] = {id = 113021, name = "星井伯納蒂", head = "13021", type = 5, title = "請說出你的願望", txt = "領航哥哥，我是星井。\n你猜猜今天是什麼日子？我猜你一定猜不到。\n今天是星井的生日！\n不過領航哥哥肯定來不了我的生日聚會吧，你那麼忙又那麼遠。\n對了，領航哥哥有什麼想知道的事情嗎？每年我生日的時候也是我靈感最強的時候，只要是今天進行占卜，都百分百會發生，但只有一次機會。往年我都是把這個占卜給了家人，但今年我想把這個機會給領航哥哥你。\n不要害羞哦領航哥哥，告訴我你的願望吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302101] = {id = 11302101, name = "星井伯納蒂", head = "13021", type = 5, title = "我的願望是沒有蛀牙", txt = "領航哥哥，我是星井，寫信來是想問問哥哥最近過得好嗎？\n星井最近過得一點也不好。星井蛀牙了，一共三顆，嘴巴上面尖尖的一顆，還有下麵靠近嘴巴裏面的兩顆。\n雖然壞掉的牙齒已經在心紙姐姐的幫助下拔掉了，但是今天就沒法吃生日蛋糕還有拉麵！\n其實這次蛀牙早有預兆。前幾天我用水晶球做過占卜，在占卜中我看到粉色天空的雲層深處，漩渦搓揉著巨大的麵團。地面被奶油雨塗抹成大海，繽紛奇異的蠟燭魚在火焰中飛翔，而後融化成一艘輪船，直直地撞向遠處的白色冰川……\n今年的生日願望就請讓星井以後再也不會蛀牙吧！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302102] = {id = 11302102, name = "星井伯納蒂", head = "13021", type = 5, title = "夢裏的怪獸", txt = "領航哥哥，昨天我做了個奇怪的夢。\n在夢裏，我想要領航哥哥陪我過生日，想要和領航哥哥一起去遊樂園玩。但是夢裏的領航哥哥卻變得很陌生，毫不客氣地拒絕了我。我感覺很生氣，於是夢裏的我變成了大怪獸，把領航哥哥連帶著整個宇宙都喫了下去。直到醒來後我才感覺害怕。\n臨近生日的我，靈感會變得很強，我很擔心這會不會是什麼預言夢。\n星井不想變成大怪獸，也不想領航哥哥被我喫掉。\n所以領航哥哥一定一定不能拒絕和星井一起去遊樂園哦！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113022] = {id = 113022, name = "莫妮卡", head = "13022", type = 5, title = "執法安排", txt = "雖然我們認識的時間不算太長。但，作為一名合格的上司，應該不用我特地提醒你下屬的生日吧？\n機會難得，我准備趁機回之前那座城市一趟。\n當然不只是為了度假和探望老同事。那座城，以前就是個仗著自己在數據上治安好而分外天真的地方。現在切斯頓又出了這麼大的事，天知道那裏會變成什麼樣。\n我要回去替他們除除蟲。鬧市區，加姆洛商街，還有城市廣場附近的幾條巷子——那些趁亂溜進來的犯罪分子一個都別想跑。\n當然，你也要來。\n那些人渣裏最頑固的幾個大概早記住我的臉了，所以要你幫我打掩護。\n這可是得力部下的生日願望，你不會拒絕吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[114001] = {id = 114001, name = "珂斯嘉德", head = "14001", type = 5, title = "早上的珀因雷德，晚上的多瑙方舟", txt = "貴安，領航。願你是在一個風和日麗的早晨，以心曠神怡的心情翻開這封信的，若是如此，那便是對身在珀因雷德的我最好的慰藉。\n此時的我正在珀因雷德與家人共慶生日，興許是在家庭宴會上用餐，也可能是在花園裡漫步。等夜幕降臨時，我可能已經回到多瑙方舟上……\n你也許會責怪我的貪心，這對騎士來說的確是恥於開口的事，但我希望那時你能陪我度過夜晚……沒有你的生日，是不完整的。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11400101] = {id = 11400101, name = "珂斯嘉德", head = "14001", type = 5, title = "你和我，二人的約會", txt = "貴安，領航。在今天這個日子收到我的來信，我心裡面想的那些不值一提的小心思，想必您早已經看穿了吧？\n去年的經歷……不，應該說是教訓，讓我明白了一個淺顯的道理。若是什麼都想得到，那便會什麼都失去。\n與其貪婪地想要擁有一切，不如直面自己的內心，探尋自己真正想要的是什麼。\n於是，領航，我已經抵達多瑙方舟。\n去年未能實現的遺憾，我想在今年實現。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[99999999] = {id = 99999999, name = "未來", head = "10020", type = 5, title = "我們已經算是結婚了吧？", txt = "變態先生……我們牽過手了，你也給了我公主抱，然後還一起睡覺了對吧！！！\n所以……所以即使相熟共事只有一周的時間，我們已經算是結婚了對吧！ 雖然接下來我會到我自己的世界，但是再次見面的時候……和我正式地再結一次婚吧！\n我已經是成熟的，結過一次婚的大人了，我會忍耐的，我會好好地等著變態先生找到我的這一天的！", goods = "1_110121_1,1_110030_1", effective = -1, "0", "0", "0", "0", "0"},
